    ["|cff888888Click a recipe's star (or right-click the recipe) to favourite it — the star turns gold.|r"] = "|cff888888Clicca la stella di una ricetta (o cliccala con il tasto destro) per aggiungerla ai preferiti — la stella diventa dorata.|r",
