    ["Re-adds the missing BIND_SOCKET confirmation dialog so socketing a gem that binds the item no longer throws a Lua error (Anniversary client)."] = "Ripristina la finestra di conferma BIND_SOCKET mancante, così incastonare una gemma che vincola l'oggetto non genera più un errore Lua (client Anniversary).",
