    ["Stops the Lua error that fires every time a nameplate appears (Blizzard's nameplate code calls a specialization API this client does not support)."] = "Elimina l'errore Lua che scatta ogni volta che compare una nameplate (il codice delle nameplate di Blizzard chiama un'API delle specializzazioni che questo client non supporta).",
