    ["|cffaaaaaaThe default Player frame on Anniversary no longer shows when you are in combat. This restores it: a red glow pulses around your portrait while you are in combat.|r"] = "|cffaaaaaaLa finestra del giocatore predefinita su Anniversary non mostra più quando sei in combattimento. Questo lo ripristina: un bagliore rosso pulsa attorno al tuo ritratto mentre sei in combattimento.|r",
    ["Disenchant Queue"] = "Coda di disincanto",
    ["For enchanters: a window with one button that disenchants your bag items one click each, auto-advancing through the queue (no casting + picking each item by hand)."] = "Per gli incantatori: una finestra con un solo pulsante che disincanta gli oggetti nelle borse con un clic ciascuno, avanzando da sola nella coda (niente lancio e scelta a mano di ogni oggetto).",
