    ["Loadout '%s' equipped (%d items swapped)."] = "Loadout “%s” equipaggiato (%d oggetti sostituiti).",
    ["Loadout '%s' equipped (%d swapped, %d missing from bags)."] = "Loadout “%s” equipaggiato (%d sostituiti, %d mancanti nelle borse).",
    ["Loadout '%s': %d items missing from bags, nothing swapped."] = "Loadout “%s”: %d oggetti mancanti nelle borse, nessuna sostituzione.",
    ["Loadout '%s' already equipped."] = "Loadout “%s” già equipaggiato.",
    ["Delete loadout '%s'?"] = "Eliminare il loadout “%s”?",
    ["Cannot change equipment in combat."] = "Non puoi cambiare equipaggiamento in combattimento.",
    ["Equipment swap API not available on this client."] = "API di cambio equipaggiamento non disponibile su questo client.",
    ["No loadouts saved yet."] = "Nessun loadout salvato per ora.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaNessun loadout salvato per ora. Usa il pulsante qui sopra per salvare l'equipaggiamento attuale.|r",
    ["Saved loadouts:"] = "Loadout salvati:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Uso: /loadout equip <name> | save <name> | delete <name> | list",
    ["Usage: /loadout delete <name>"] = "Uso: /loadout delete <name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaComandi: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Alias breve: /lo|r",
    ["No account-wide loadouts to import."] = "Nessun loadout dell'account da importare.",
    ["Imported %d account-wide loadout(s) onto this character."] = "Importati %d loadout dell'account su questo personaggio.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "Hai loadout dell'account salvati da una versione precedente. Scrivi /lo import per copiarli su questo personaggio.",
    ["Import from older version"] = "Importa da una versione precedente",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaHai set di equipaggiamento salvati a livello di account da una versione precedente. Ora i loadout sono per personaggio — l'importazione li copia su QUESTO personaggio.|r",
    ["Import account-wide loadouts"] = "Importa i loadout dell'account",
    ["Head"] = "Testa",
    ["Chest"] = "Torso",
    ["Feet"] = "Piedi",
    ["Finger 1"] = "Anello 1",
    ["Trinket 1"] = "Monile 1",
    ["Both trinkets"] = "Entrambi i monili",
    ["Set focus"] = "Imposta focus",
    ["Healing potion"] = "Pozione di cura",
    ["Macro Factory"] = "Fabbrica di macro",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaUn clic crea una macro pronta all'uso (per personaggio). Poi apri |cffffffff/macro|r e trascinala sulla barra delle azioni. Funziona su qualsiasi client — usa slot / ID degli oggetti, senza bisogno dell'inglese.|r",
    ["Macro Factory: can't create macros in combat."] = "Fabbrica di macro: non puoi creare macro in combattimento.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Fabbrica di macro: niente da creare (es. nessuna pozione di cura nelle borse).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "Fabbrica di macro: creazione non riuscita (slot per macro del personaggio pieni?).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "Macro “%s” aggiornata — trascinala da |cffffffff/macro|r sulla barra delle azioni.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "Macro “%s” creata — apri |cffffffff/macro|r e trascinala sulla barra delle azioni.",
    ["Back"] = "Schiena",
    ["Main Hand"] = "Mano principale",
    ["Save All..."] = "Salva tutto...",
    ["Save Trinkets..."] = "Salva i monili...",
    ["Save Weapons..."] = "Salva le armi...",
