    ["Settings..."] = "Impostazioni...",
    ["Minimap Button"] = "Pulsante minimappa",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Clic sinistro per un menu rapido di cambio set, clic destro per aprire le impostazioni, trascina per spostarlo.",
    ["Left-click: switch set"] = "Clic sinistro: cambia set",
    ["Right-click: settings"] = "Clic destro: impostazioni",
    ["Drag: reposition"] = "Trascina: sposta",
    ["Auto-Switch on Stance/Form"] = "Cambio automatico con posizione/forma",
    ["Enable auto-switching"] = "Attiva il cambio automatico",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Equipaggia automaticamente un loadout quando cambi posizione/forma (posizioni del guerriero, forme del druido). Solo fuori dal combattimento — se il cambio avviene in combattimento, la sostituzione è rimandata alla fine del combattimento.",
    ["Auto-equip on form"] = "Equipaggia automaticamente con la forma",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Equipaggia automaticamente questo loadout quando si attiva la posizione/forma scelta.",
    ["Auto-Switch on Dual Spec"] = "Cambio automatico con la doppia spec",
    ["Enable spec auto-switching"] = "Attiva il cambio automatico per spec",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Equipaggia automaticamente un loadout quando passi tra Spec 1 e Spec 2 (doppia spec). Associa ogni loadout a una spec qui sotto. Richiede la doppia spec attiva.",
    ["Auto-equip on spec"] = "Equipaggia automaticamente con la spec",
    ["Equip this loadout automatically when you switch to this spec."] = "Equipaggia automaticamente questo loadout quando passi a questa spec.",
    ["None"] = "Nessuno",
    ["No Form"] = "Nessuna forma",
    ["Form %d"] = "Forma %d",
    ["Character Frame Sidebar"] = "Barra laterale della finestra del personaggio",
    ["Show sidebar on character frame"] = "Mostra la barra laterale sulla finestra del personaggio",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Aggiunge una barra laterale di accesso rapido a destra della finestra del personaggio. Clicca un set per selezionarlo, doppio clic o pulsante per equipaggiarlo, clic destro per il menu contestuale.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaSuggerimento: con la finestra del personaggio aperta, attiva la modalità modifica (Sblocca) per trascinare la barra laterale; clicca con il destro sul riquadro viola per ripristinarne la posizione.|r",
    ["New Set"] = "Nuovo set",
    ["Left-click: select"] = "Clic sinistro: seleziona",
    ["Double-click / Right-click menu: equip"] = "Doppio clic / menu col destro: equipaggia",
