    ["Add a slot"] = "Aggiungi uno slot",
    ["Re-adds an ignored slot to this set."] = "Riaggiunge a questo set uno slot ignorato.",
    ["Right-click: remove this slot from the set."] = "Clic destro: rimuove questo slot dal set.",
    ["Left-click to pick an item from your bags"] = "Clic sinistro per scegliere un oggetto dalle borse",
    ["(equipped)"] = "(equipaggiato)",
    ["Slot Picker"] = "Selettore di slot",
    ["Enable slot picker"] = "Attiva il selettore di slot",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaClicca con il destro uno slot dell'equipaggiamento nella finestra del personaggio per vedere tutti gli oggetti compatibili nelle borse e cliccane uno per equipaggiarlo.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Passa il mouse su uno slot dell'equipaggiamento nella finestra del personaggio per un menu compatto degli oggetti compatibili nelle borse, oppure usa il clic con modificatore per un selettore più grande e fissabile. Clicca un oggetto per equipaggiarlo (fuori dal combattimento).",
    ["Flyout on hover"] = "Menu al passaggio del mouse",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "Passando il mouse su uno slot dell'equipaggiamento compare una striscia compatta di oggetti da sostituire — l'aspetto del menu della scheda personaggio. Disattivalo per usare solo il selettore con clic e modificatore.",
    ["Activation modifier"] = "Modificatore di attivazione",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Scegli quale combinazione di tasti apre il selettore di oggetti quando clicchi uno slot dell'equipaggiamento.",
