    ["Grid columns"] = "Colonne della griglia",
    ["How many item icons per row in the picker popup."] = "Quante icone di oggetti per riga nel popup del selettore.",
    ["Items for: %s"] = "Oggetti per: %s",
    ["Close automatically on mouse-out"] = "Chiudi automaticamente all'uscita del mouse",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "Il selettore si chiude poco dopo che il mouse lo lascia. Trascinalo una volta per fissarlo aperto finché non lo chiudi a mano.",
