    ["Auto (client language)"] = "Auto (lingua del client)",
    ["Choose the language for the VuloClassicUI interface. 'Auto' uses your WoW client's language (German clients see German, all others see English).\n\n|cffaaaaaaRequires /reload to apply.|r"] = "Scegli la lingua dell'interfaccia di VuloClassicUI. “Auto” usa la lingua del tuo client WoW (i client tedeschi vedono il tedesco, tutti gli altri l'inglese).\\n\\n|cffaaaaaaRichiede /reload per essere applicata.|r",
    ["Language changed. /reload required to apply the new language to all UI elements."] = "Lingua modificata. /reload necessario per applicare la nuova lingua a tutti gli elementi dell'interfaccia.",
