    ["Character"] = "Personaggio",
    ["World"] = "Mondo",
    ["Crisp portrait hit numbers"] = "Numeri dei colpi nitidi sul ritratto",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Mostra i numeri di danno/cura che compaiono sul ritratto del giocatore/famiglio con un font fisso e nitido invece della sfocata animazione di ingrandimento di Blizzard.",
    ["Hit number size"] = "Dimensione dei numeri dei colpi",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Dimensione del font dei numeri sul ritratto (quando ‘Nitidi’ è attivo).",
    ["Auto-select single gossip option"] = "Seleziona automaticamente l'unica opzione di dialogo",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Salta le finestre di dialogo dei PNG che hanno una sola opzione. Tieni premuto SHIFT per ignorarlo temporaneamente.",
    ["Faster auto-loot"] = "Auto-loot più veloce",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Raccoglie tutti gli oggetti in una volta quando l'auto-loot è attivo, invece che uno alla volta.",
    ["Max camera zoom"] = "Zoom massimo della telecamera",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Aumenta la distanza massima di allontanamento della telecamera ben oltre il valore predefinito.",
    ["Player & Target Frame"] = "Riquadro giocatore e bersaglio",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "Bordo drago élite per il riquadro del giocatore, più salute reale, indicatore di minaccia e bordo raro-élite per i riquadri di bersaglio e focus.",
    ["Target & Focus Frame"] = "Riquadro bersaglio e focus",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaAggiunge il drago élite dorato (o le varianti rare) attorno al tuo ritratto — l'aspetto che i mob élite hanno sul riquadro del bersaglio.|r",
    ["Frame style"] = "Stile del riquadro",
    ["Elite (golden dragon)"] = "Élite (drago dorato)",
    ["Rare-Elite (silver dragon)"] = "Raro-Élite (drago argentato)",
    ["Rare (silver)"] = "Raro (argento)",
    ["Off (default frame)"] = "Disattivato (riquadro predefinito)",
    ["Cooldown Manager"] = "Gestore dei cooldown",
    ["Cooldowns"] = "Cooldown",
    ["Delete group"] = "Elimina gruppo",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888Ancora niente in questo gruppo.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Gruppo cooldown ‘%s’ sbloccato. Trascinaci sopra incantesimi/oggetti; |cff9b6cfftrascina|r per spostarlo.",
    ["Cooldown group '%s' locked."] = "Gruppo cooldown ‘%s’ bloccato.",
    ["Group type"] = "Tipo di gruppo",
    ["Buffs & Procs (only show while active)"] = "Buff e proc (mostra solo se attivi)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaLe icone compaiono solo mentre il relativo buff/proc è attivo su di te; altrimenti la barra è vuota. Aggiungi il BUFF (ad es. Clearcasting) per nome o ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaLe icone mostrano il cooldown di ogni incantesimo/monile.|r",
    ["Size & offsets"] = "Dimensione e scostamenti",
    ["Extra settings"] = "Impostazioni aggiuntive",
    ["Friends List"] = "Lista amici",
    ["Dialog Popups"] = "Finestre di dialogo",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Ridisegna le finestre di conferma di Blizzard (conto alla rovescia del logout, elimina oggetto, resurrezione, invito al gruppo) per adattarle allo stile scuro.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaRidisegna le finestre di conferma di Blizzard — conto alla rovescia del logout, elimina oggetto, resurrezione, invito al gruppo — per adattarle allo stile scuro.|r",
    ["Accent strip"] = "Striscia d'accento",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Disegna un sottile gradiente d'accento lungo il bordo superiore di ogni finestra.",
    ["Addon Skins"] = "Skin degli addon",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Ridisegna le finestre degli addon di terze parti supportati nello stile scuro: lista errori, tracciatore delle missioni, browser del loot, profiler e altro.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaRidisegna le finestre degli addon supportati nello stile scuro. Le skin vengono applicate al caricamento dell'addon; per disattivarne una serve un /reload (il tracciatore delle missioni si ripristina all'istante).|r",
    ["not loaded"] = "non caricato",
    ["Dark window skin"] = "Skin scura della finestra",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Ridisegna tutta la finestra degli amici in scuro con accenti viola. Per disattivarla serve un /reload che ripristini il riquadro di Blizzard.",
    ["Class color names"] = "Nomi colorati per classe",
    ["Colors each online friend's name by their class."] = "Colora il nome di ogni amico online in base alla sua classe.",
    ["Show class icons"] = "Mostra le icone di classe",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Mostra un'icona di classe accanto agli amici WoW online (in gioco e Battle.net).",
    ["Class icon style"] = "Stile delle icone di classe",
    ["Blizzard crests"] = "Stemmi Blizzard",
    ["Circles"] = "Cerchi",
    ["Squares"] = "Quadrati",
    ["Show status dot"] = "Mostra il pallino di stato",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Un pallino colorato dopo il nome: verde online, giallo assente, rosso occupato, grigio offline.",
    ["Show friend notes"] = "Mostra le note sugli amici",
    ["Shows your saved note for the friend in grey under their name."] = "Mostra in grigio, sotto il nome, la nota che hai salvato per l'amico.",
    ["Faction"] = "Fazione",
    ["Faction accent on realm line"] = "Accento di fazione sulla riga del reame",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Colora la riga di reame/zona di rosso (Orda) o di blu (Alleanza).",
    ["Faction row tint"] = "Tinta di fazione sulla riga",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Aggiunge una leggera tinta di sfondo rossa/blu alla riga di ogni amico online.",
    ["Invites"] = "Inviti",
    ["Auto-accept Battle.net friend invites"] = "Accetta automaticamente gli inviti di amicizia Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Accetta automaticamente le richieste di amicizia Battle.net in arrivo.",
    ["Auto-accept group invites from friends"] = "Accetta automaticamente gli inviti al gruppo dagli amici",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Entra automaticamente in un gruppo quando l'invito arriva da qualcuno nella tua lista amici.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Nomi colorati per classe, icone di classe, pallini di stato, note in linea, tinta di fazione e accettazione automatica opzionale.",
