    ["Countdown text color..."] = "Colore del testo del conto alla rovescia...",
    ["Warn color under (sec)"] = "Colore di avviso sotto (sec)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Sotto questo numero di secondi il conto alla rovescia passa al colore di avviso; 0 disattiva il colore di avviso.",
    ["Warn color..."] = "Colore di avviso...",
    ["Glow while ready"] = "Bagliore quando è pronto",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Un bagliore fisso mentre il cooldown è pronto - e, per gli incantesimi, solo quando è davvero utilizzabile (mana sufficiente ecc.).",
    ["Glow color"] = "Colore del bagliore",
    ["Show keybinds"] = "Mostra i tasti assegnati",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Mostra il tasto a cui l'incantesimo/oggetto è assegnato sulle tue barre delle azioni. Le macro non vengono riconosciute; le pagine delle posture seguono la barra principale.",
    ["Keybind color..."] = "Colore dei tasti assegnati...",
    ["Keep inactive buffs visible (greyed out)"] = "Mantieni visibili i buff inattivi (in grigio)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Le icone restano al loro posto quando il buff scade, solo desaturate - la barra non si sposta mai.",
    ["Add (name / ID)"] = "Aggiungi (nome / ID)",
    ["Tracked"] = "Tracciati",
    ["  |cff888888(item)|r"] = "  |cff888888(oggetto)|r",
    ["Up"] = "Su",
    ["Icons per row"] = "Icone per riga",
    ["Growth direction"] = "Direzione di crescita",
    ["Right"] = "Destra",
    ["Left"] = "Sinistra",
    ["Down"] = "Giù",
    ["Only show while on cooldown"] = "Mostra solo durante il cooldown",
    ["Hides ready icons; they reappear when on cooldown."] = "Nasconde le icone pronte; ricompaiono quando sono in cooldown.",
    ["Show countdown text"] = "Mostra il testo del conto alla rovescia",
    ["Show stacks"] = "Mostra le cariche",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(altra classe)|r",
    ["Edit mode — move the cooldown bars"] = "Modalità modifica — sposta le barre dei cooldown",
    ["Stop editing — lock the cooldown bars"] = "Termina la modifica — blocca le barre dei cooldown",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Sblocca solo le barre dei cooldown così puoi trascinarle. Le frecce per la regolazione fine; clic destro su un riquadro viola per X/Y. (Per spostare TUTTE le finestre VuloUI, usa ‘Modalità sblocco’ in Globale.)",
    ["Hide cooldowns under (sec)"] = "Nascondi i cooldown sotto (sec)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "I cooldown pari o inferiori a questo valore vengono ignorati. 1.5 nasconde il global cooldown; aumentalo per nascondere anche i cooldown brevi; 0 mostra tutto.",
    ["Move earlier"] = "Sposta prima",
    ["Move later"] = "Sposta dopo",
    ["Stack / reagent position"] = "Posizione cariche / reagenti",
    ["Stack / reagent size"] = "Dimensione cariche / reagenti",
    ["Stack / reagent color..."] = "Colore cariche / reagenti...",
    ["Bottom right"] = "In basso a destra",
    ["Bottom left"] = "In basso a sinistra",
    ["Top right"] = "In alto a destra",
    ["Top left"] = "In alto a sinistra",
    ["Show reagent counts"] = "Mostra il numero di reagenti",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Mostra il numero di reagenti PROPRI di ogni incantesimo — Soul Shards su Soul Fire, Infernal Stone su Inferno, ecc. Gli incantesimi senza reagente non mostrano nulla. Richiede ‘Mostra le cariche’ attivo.",
    ["Anchor"] = "Ancoraggio",
    ["Anchor to"] = "Ancora a",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Fissa questa barra a un riquadro unità, alla minimappa o alla barra di un altro gruppo — si sposterà insieme a essa. Trascina la barra per staccarla.",
    ["Player Frame"] = "Riquadro del giocatore",
    ["Focus Frame"] = "Riquadro del focus",
    ["Pet Frame"] = "Riquadro del famiglio",
    ["None (free)"] = "Nessuno (libero)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Gestore dei cooldown: impossibile ancorare lì — creerebbe un ciclo.",
    ["Side"] = "Lato",
    ["Below"] = "Sotto",
    ["Above"] = "Sopra",
    ["Left of"] = "A sinistra di",
    ["Right of"] = "A destra di",
    ["X offset"] = "Scostamento X",
    ["Y offset"] = "Scostamento Y",
    ["Icon shape"] = "Forma delle icone",
    ["Square"] = "Quadrata",
    ["Rounded"] = "Arrotondata",
    ["Icon crop (%)"] = "Ritaglio delle icone (%)",
    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "Quanto viene tagliato da ogni bordo dell'icona. 0 mostra l'icona intera, compreso il bordo presente nella sua grafica.",
    ["Cooldown swipe darkness"] = "Oscurità dello sweep del cooldown",
    ["Only in combat"] = "Solo in combattimento",
    ["Only with a target"] = "Solo con un bersaglio",
    ["Only with an attackable target"] = "Solo con un bersaglio attaccabile",
    ["Hide while mounted"] = "Nascondi mentre sei in sella",
    ["Only in instances"] = "Solo nelle istanze",
    ["Dim icon while on cooldown"] = "Scurisci l'icona durante il cooldown",
    ["Flash when ready"] = "Lampeggia quando è pronto",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Salva istantanee con nome delle tue barre delle azioni, macro e assegnazioni dei tasti, e le ripristina con un clic.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaSalva la configurazione completa delle tue barre (tutti gli slot delle azioni, macro, assegnazioni dei tasti) come profilo con nome e la ripristina con un clic — ad es. disposizioni PvP e Raid, o per copiare una configurazione su un twink (archiviazione a livello di account).|r",
    ["Load"] = "Carica",
    ["Save current setup"] = "Salva la configurazione attuale",
    ["Please enter a profile name first."] = "Inserisci prima un nome per il profilo.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Nessun profilo salvato.|r",
    ["Also restore macros"] = "Ripristina anche le macro",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Riscrive le macro salvate in base al nome (quelle esistenti vengono aggiornate, quelle mancanti create).",
    ["Also restore keybindings"] = "Ripristina anche le assegnazioni dei tasti",
    ["Load profile"] = "Carica profilo",
    ["Overwrite with current setup"] = "Sovrascrivi con la configurazione attuale",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Sostituisce il profilo selezionato con le tue barre/macro/assegnazioni attuali.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Nota: il profilo ‘%s’ è stato salvato su un'altra classe (%s).",
    ["Flight Timer"] = "Timer di volo",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800Database delle rotte di volo non caricato.|r Riavvia completamente WoW (dopo un aggiornamento un /reload non basta) perché i tempi di volo funzionino.",
    ["Show flight time bar"] = "Mostra la barra del tempo di volo",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Mostra destinazione e tempo rimanente durante un volo. Il primo volo di una rotta viene appreso, poi ottieni un conto alla rovescia.",
    ["Flight: %s (%s)"] = "Volo: %s (%s)",
    ["Print flight time to chat"] = "Stampa il tempo di volo in chat",
    ["After landing, prints the measured flight time."] = "Dopo l'atterraggio stampa il tempo di volo misurato.",
    ["Reset learned times"] = "Azzera i tempi appresi",
    ["Deletes all saved route durations."] = "Elimina tutte le durate delle rotte salvate.",
    ["Learned flight times reset."] = "Tempi di volo appresi azzerati.",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffTEMPO DI VOLO|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Timer di volo: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Spostamento del timer di volo attivo. |cff9b6cffTrascina|r o usa le |cff9b6cfffrecce|r (SHIFT = 5px).",
    ["Flight timer mover disabled."] = "Spostamento del timer di volo disattivato.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Debug del volo attivo — fai un volo e la risoluzione apparirà in chat.",
    ["Flight debug off."] = "Debug del volo disattivato.",
    ["LazyVulo"] = "LazyVulo",
    ["Training"] = "Training",
    ["Group Board"] = "Bacheca dei gruppi",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Aiuto per il minigioco di memoria della Apexis Relic (giornaliere di Ogri'la): registra la sequenza di colori lampeggianti, vedi sempre cosa cliccare dopo.",
    ["Green relic"] = "Reliquia verde",
    ["Yellow relic"] = "Reliquia gialla",
    ["Blue relic"] = "Reliquia blu",
    ["Red relic"] = "Reliquia rossa",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "Clic sinistro: rimuovi questa voce.\\nClic destro: rimuovi questa e tutte le voci successive.",
    ["Click to record this color."] = "Clicca per registrare questo colore.",
    ["Hotkey: %s"] = "Tasto rapido: %s",
    ["LazyVulo is disabled."] = "LazyVulo è disattivato.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaAiuto per il minigioco di memoria della Apexis Relic (giornaliere di Ogri'la). Registra la sequenza lampeggiante con i pulsanti o i tasti rapidi; la prima icona è sempre il tuo prossimo clic. I clic corretti vengono consumati automaticamente, quelli sbagliati ripristinati.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaAprilo manualmente con /lazyvulo o /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Mostra automaticamente alla Apexis Relic",
    ["Opens the window automatically when you start the relic minigame."] = "Apre la finestra automaticamente quando avvii il minigioco della reliquia.",
    ["Enable hotkeys while the window is shown"] = "Attiva i tasti rapidi mentre la finestra è visibile",
    ["Disable hotkeys while in combat"] = "Disattiva i tasti rapidi in combattimento",
    ["Hands the keys back to your action bars while you are in combat."] = "Restituisce i tasti alle tue barre delle azioni mentre sei in combattimento.",
    ["Show help tooltips"] = "Mostra i tooltip d'aiuto",
    ["Window scale"] = "Scala della finestra",
    ["Hotkeys"] = "Tasti rapidi",
    ["|cffaaaaaaOne key per color (e.g. G, Y, B, R or NUMPAD1). Empty = no hotkey.|r"] = "|cffaaaaaaUn tasto per colore (ad es. G, Y, B, R o NUMPAD1). Vuoto = nessun tasto rapido.|r",
