    ["Power Bar"] = "Barra delle risorse",
    ["A movable resource bar for your character. The power type follows your class automatically (Mana / Rage / Energy) — and for Druids it switches with your form: Bear = Rage, Cat = Energy, otherwise Mana."] = "Una barra delle risorse spostabile per il tuo personaggio. Il tipo di risorsa segue automaticamente la tua classe (Mana / Rabbia / Energia) — e per i Druidi cambia con la forma: Orso = Rabbia, Felino = Energia, altrimenti Mana.",
