    ["Mouseover mode: the bar's opacity while the mouse is elsewhere."] = "Modalità mouseover: l'opacità della barra mentre il mouse è altrove.",
    ["Marks & threshold"] = "Tacche e soglia",
    ["Hash marks"] = "Tacche",
    ["Comma-separated values, e.g. 30,60 — draws a line at each (great for tick or breakpoint marks)."] = "Valori separati da virgola, ad es. 30,60 — traccia una linea a ciascuno (ottimo per i tick o per segnare le soglie).",
