    ["Color"] = "Colore",
    ["Protection"] = "Protezione",
    ["Block group invites from strangers"] = "Blocca gli inviti al gruppo dagli sconosciuti",
    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Rifiuta automaticamente gli inviti a gruppo/raid dai giocatori che non sono nella tua gilda o nella tua lista amici.",
    ["Block trades from strangers"] = "Blocca gli scambi dagli sconosciuti",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Chiude automaticamente le finestre di scambio aperte da giocatori che non sono nella tua gilda o nella tua lista amici. Gli scambi che avvii tu non sono influenzati.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r Invito al gruppo da %s bloccato (non gilda/amico).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[QoL]|r Scambio da %s bloccato (non gilda/amico).",
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "Aggiunge al libro degli incantesimi una scheda che elenca le abilità che puoi ancora imparare dal tuo addestratore di classe, raggruppate per livello. Apri l'icona del libro sotto le scuole di magia.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaaAggiunge al libro degli incantesimi una scheda (l'icona del libro sul lato, sotto le scuole di magia) che elenca tutte le abilità che puoi ancora imparare dal tuo addestratore di classe — raggruppate per stato e colorate per livello. Nessuna visita all'addestratore necessaria.|r",
    ["Available now"] = "Disponibili ora",
    ["Available but Missing Requirements"] = "Disponibili, ma requisiti mancanti",
    ["Upcoming"] = "In arrivo",
    ["Not Yet Available"] = "Non ancora disponibili",
    ["Missing Required Talents"] = "Talenti richiesti mancanti",
    ["Already Known"] = "Già apprese",
    ["Level %d"] = "Livello %d",
    ["Cost: %s"] = "Costo: %s",
    ["What can I train?"] = "Cosa posso imparare?",
    ["No results found"] = "Nessun risultato trovato",
    ["Anchor to window..."] = "Ancora alla finestra...",
    ["WIDTH LIKE"] = "LARGHEZZA COME",
    ["HEIGHT LIKE"] = "ALTEZZA COME",
    ["Takes its width from another window and keeps it."] = "Prende la larghezza da un'altra finestra e la mantiene.",
    ["Takes its height from another window and keeps it."] = "Prende l'altezza da un'altra finestra e la mantiene.",
    ["This window sets its own size - the match will not stick."] = "Questa finestra imposta da sé la propria dimensione: l'abbinamento non verrà mantenuto.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "Trascina un riquadro, oppure passaci sopra e usa i tasti freccia (Shift = 5px). Tieni premuto Shift mentre trascini per bloccare un asse. Shift+clic destro nasconde un riquadro d'intralcio.",
    ["Then click any window to anchor this one to it."] = "Poi clicca una finestra qualsiasi per ancorarci questa.",
    ["Click a window to anchor it (right-click to cancel)."] = "Clicca una finestra per ancorarla (clic destro per annullare).",
    ["ANCHOR SIDE"] = "LATO DI ANCORAGGIO",
    ["Centered"] = "Centrato",
    ["Top of"] = "Sopra a",
    ["Bottom of"] = "Sotto a",
    ["Discard"] = "Abbandona",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "Fissa questo frame a un bordo/angolo dello schermo così resta al suo posto al cambio di risoluzione. Disattivato lo mantiene centrato.",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "Lascia questa finestra sbloccata così puoi trascinarla anche dopo aver chiuso la modalità Modifica. Resta sbloccata anche dopo un /reload.",
    ["LAYOUTS"] = "DISPOSIZIONI",
    ["Layouts"] = "Disposizioni",
    ["SAVED"] = "SALVATE",
    ["No layouts saved"] = "Nessuna disposizione salvata",
    ["No layout selected."] = "Nessuna disposizione selezionata.",
    ["Save, load, export and import named window layouts."] = "Salva, carica, esporta e importa disposizioni delle finestre con un nome.",
    ["Save your window arrangement, then load or share it any time."] = "Salva la disposizione delle tue finestre, poi caricala o condividila quando vuoi.",
    ["Pick a saved layout to load, delete or export."] = "Scegli una disposizione salvata da caricare, eliminare o esportare.",
    ["Save current as..."] = "Salva l'attuale come...",
    ["Name for this layout:"] = "Nome per questa disposizione:",
    ["Delete layout '%s'?"] = "Eliminare la disposizione '%s'?",
    ["Layout '%s' saved."] = "Disposizione '%s' salvata.",
    ["Applied layout '%s' (%d frames)."] = "Disposizione '%s' applicata (%d frame).",
    ["Layout '%s' imported."] = "Disposizione '%s' importata.",
    ["Import"] = "Importa",
    ["Export"] = "Esporta",
    ["Imported"] = "Importata",
    ["Import failed (%s)."] = "Importazione fallita (%s).",
    ["Paste a layout string and confirm:"] = "Incolla una stringa di disposizione e conferma:",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "Copia questa stringa (Ctrl+A, Ctrl+C):",
    ["Move it in the unified Edit Mode (/vedit)."] = "Spostalo nella modalità Modifica unificata (/vedit).",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "Trascina il riquadro del testo di combattimento nella modalità Modifica unificata (/vedit).",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffffFRAME ARENA|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44La modalità Modifica è ATTIVA.|r Chiudi questa finestra per raggiungere i riquadri.",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaaSposta tutto in un unico editor: le finestre di VuloUI e i frame di Blizzard (giocatore, bersaglio, focus, minimappa, buff). Si agganciano a una griglia comune.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• Trascina un riquadro viola per spostare quel frame.|n• Passa sopra un riquadro, poi i tasti freccia regolano con precisione (SHIFT = 5px).|n• Clic destro su un riquadro per X / Y esatti.|n• Anche |cffffffff/vedit|r attiva o disattiva la modalità Modifica.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Attiva 'Bersaglio e Focus' nelle impostazioni della modalità Modifica di Blizzard, poi /reload, così VuloUI può spostare il frame bersaglio/focus.",
    ["Dark Mode"] = "Modalità Scura",
    ["Desaturate (greyscale)"] = "Desatura (scala di grigi)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "Rimuove il colore dalla grafica prima di ricolorarla, per un vero effetto scala di grigi. Disattivato lascia un accenno della tinta originale.",
    ["Tint colour"] = "Colore della tinta",
    ["Unit frames"] = "Frame unità",
    ["Player, target, focus, pet and party frame borders."] = "Bordi dei frame di giocatore, bersaglio, focus, pet e gruppo.",
    ["Minimap border, compass, zoom and tracking buttons."] = "Bordo della minimappa, bussola, zoom e pulsanti di tracciamento.",
    ["Action bar artwork"] = "Grafica della barra delle azioni",
    ["The gryphons and the metal action-bar background."] = "I grifoni e lo sfondo metallico della barra delle azioni.",
    ["Action button borders"] = "Bordi dei pulsanti azione",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "Ricolora anche l'anello di bordo attorno a ogni pulsante azione. Opzionale: lascialo disattivato se risulta troppo piatto.",
    ["Bag slots"] = "Slot delle borse",
    ["Tints the backpack, bag and keyring button borders."] = "Ricolora i bordi dei pulsanti di zaino, borse e portachiavi.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaaNota: se il |cffffffffbagliore di minaccia|r del modulo Frame Giocatore e Bersaglio è attivo, la colorazione della minaccia prende il controllo del bordo bersaglio/focus mentre hai l'aggro: è voluto.|r",
    ["Chat"] = "Chat",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Rifinisce la chat di Blizzard: un pannello scuro con barra laterale di icone, orari, nomi colorati per classe, link cliccabili, schede scure, dissolvenza in inattività e cronologia che sopravvive a un /reload. Ogni parte è opzionale.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaRifinisce la chat di Blizzard — nulla viene sostituito, quindi resta leggera e compatibile. Ogni opzione qui sotto è indipendente.|r",
    ["Timestamps"] = "Orari",
    ["Show timestamps"] = "Mostra gli orari",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "Antepone l'orario a ogni riga, usando l'impostazione degli orari del gioco.",
    ["Time format"] = "Formato ora",
    ["Names & links"] = "Nomi e link",
    ["Class-coloured names"] = "Nomi colorati per classe",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "Colora i nomi dei giocatori in base alla classe in dire, gruppo, raid, gilda, sussurro e canali.",
    ["Clickable links"] = "Link cliccabili",
    ["Turns web links into clickable links that open a copy box."] = "Trasforma i link web in link cliccabili che aprono un riquadro da cui copiare.",
    ["Style chat tabs"] = "Stile delle schede della chat",
    ["Flat dark tab background with an accent underline on the active tab."] = "Sfondo scheda scuro e piatto con una sottolineatura d'accento sulla scheda attiva.",
    ["Tab label size"] = "Dimensione etichetta scheda",
    ["One uniform font size for every chat tab label."] = "Una dimensione del carattere uniforme per ogni etichetta di scheda della chat.",
    ["Chat font size (0 = Blizzard)"] = "Dimensione carattere chat (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "Cronologia di scorrimento (righe per finestra)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "Quante righe ogni finestra di chat conserva per lo scorrimento (predefinito Blizzard: 128). Più righe usano un po' più di memoria; modificarlo cancella una volta le righe attualmente mostrate.",
    ["Item levels in chat links"] = "Livelli oggetto nei link della chat",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "Aggiunge il livello oggetto ai link dell'equipaggiamento: [Spada] diventa [Spada (45)].",
    ["Panel opacity (%)"] = "Opacità del pannello (%)",
    ["Transparency of the dark background panel behind the chat."] = "Trasparenza del pannello di sfondo scuro dietro la chat.",
    ["Indent wrapped lines"] = "Rientra le righe mandate a capo",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "Manda a capo i messaggi lunghi con le righe successive rientrate sotto l'inizio del messaggio, per una colonna più pulita.",
    ["Idle fade"] = "Dissolvenza in inattività",
    ["Fade chat when idle"] = "Dissolvi la chat quando è inattiva",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "Attenua la chat dopo un po' senza attività. Un nuovo messaggio, il passaggio del mouse o la scrittura la riportano in evidenza.",
    ["Idle delay (seconds)"] = "Attesa di inattività (secondi)",
    ["Faded opacity (%)"] = "Opacità da dissolta (%)",
    ["History"] = "Cronologia",
    ["Keep chat history"] = "Conserva la cronologia della chat",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "Ricorda la chat recente per personaggio e la rimostra dopo un /reload.",
    ["Lines to keep"] = "Righe da conservare",
    ["Clear history"] = "Cancella la cronologia",
    ["Chat history cleared."] = "Cronologia della chat cancellata.",
    ["--- chat history ---"] = "--- cronologia della chat ---",
    ["Copy"] = "Copia",
    ["Copy chat"] = "Copia la chat",
    ["Link"] = "Link",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A per selezionare tutto, Ctrl+C per copiare.",
    ["Scroll to bottom"] = "Scorri in fondo",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaaIl pannello, la riga di input e la barra laterale riposizionano la chat di Blizzard. Disattivarli qui li nasconde subito; un |cffffffff/reload|r ripristina esattamente le posizioni originali.|r",
    ["Dark background panel"] = "Pannello di sfondo scuro",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "Un pannello scuro dietro la chat e la riga di input, con la barra delle schede sopra: un unico blocco coerente.",
    ["Top fade"] = "Dissolvenza superiore",
    ["Fades old lines into the panel at the top edge of the chat."] = "Dissolve le righe vecchie nel pannello sul bordo superiore della chat.",
    ["Icon sidebar"] = "Barra laterale di icone",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "Una barra sottile a sinistra della chat con le icone copia, impostazioni, nuova finestra e scorri in fondo.",
    ["Show online friends"] = "Mostra gli amici online",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "Mostra quanti amici sono online in cima alla barra laterale; clicca l'icona per aprire la lista amici.",
    ["Friends online"] = "Amici online",
    ["New chat window"] = "Nuova finestra di chat",
    ["Create new chat window"] = "Crea una nuova finestra di chat",
    ["This client can't create extra chat windows."] = "Questo client non può creare finestre di chat aggiuntive.",
    ["Use VuloUI font"] = "Usa il carattere di VuloUI",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "Applica il carattere di VuloUI al testo della chat, alle schede e alla riga di input.",
    ["Copy button (standalone)"] = "Pulsante Copia (autonomo)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "Un piccolo pulsante Copia sopra la chat. Disattivato di default perché la barra laterale ha già un'icona copia; disattiva la barra laterale per usare questo.",
    ["Bags"] = "Borse",
    ["Inventory"] = "Inventario",
    ["Items"] = "Oggetti",
    ["Hide"] = "Nascondi",
    ["Show"] = "Mostra",
    ["Color item levels by quality"] = "Colora i livelli oggetto per qualità",
    ["Tints the item level number in the item's quality color instead of plain white."] = "Colora il numero del livello oggetto con il colore di qualità dell'oggetto invece del bianco.",
    ["%d free"] = "%d liberi",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaaUna sola finestra per tutte le tue borse. Premi il tasto delle borse (B di default) per aprirla. Scrivi nel campo di ricerca per trovare oggetti; clicca il pulsante di ordinamento per fare ordine. Da un banchiere, la tua banca si apre in una finestra abbinata.|r",
    ["Quality borders"] = "Bordi di qualità",
    ["Colour each item's border by its rarity."] = "Colora il bordo di ogni oggetto in base alla sua rarità.",
    ["Item count text size"] = "Dimensione testo conteggio oggetti",
    ["Reset bag position"] = "Reimposta la posizione delle borse",
    ["Search & sorting"] = "Ricerca e ordinamento",
    ["Show search box"] = "Mostra il campo di ricerca",
    ["A search field in the window header. Dims items that don't match."] = "Un campo di ricerca nell'intestazione della finestra. Attenua gli oggetti che non corrispondono.",
    ["Show sort button"] = "Mostra il pulsante di ordinamento",
    ["A sort button in the window header. Right-click it to reverse the order."] = "Un pulsante di ordinamento nell'intestazione della finestra. Clic destro per invertire l'ordine.",
    ["Reverse sort order"] = "Inverti l'ordinamento",
    ["Sort bags"] = "Ordina le borse",
    ["Bank contents"] = "Contenuto della banca",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "Mostra cosa contiene la tua banca: dall'ultima visita, consultabile ovunque.",
    ["As of: %s"] = "Aggiornato al: %s",
    ["%d free slots"] = "%d slot liberi",
    ["No bank visit recorded on this character yet."] = "Nessuna visita in banca registrata su questo personaggio.",
    ["Right-click to toggle sort order."] = "Clic destro per invertire l'ordinamento.",
    ["Can't sort bags in combat."] = "Non puoi ordinare le borse in combattimento.",
    ["Sort order: reversed"] = "Ordinamento: invertito",
    ["Sort order: normal"] = "Ordinamento: normale",
    ["Sort order"] = "Ordinamento",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "Come il pulsante di ordinamento dispone gli oggetti. 'Blizzard' raggruppa per categoria come l'interfaccia predefinita; gli altri sono un ordine unico.",
    ["Blizzard (category)"] = "Blizzard (categoria)",
    ["Quality"] = "Qualità",
    ["Item type"] = "Tipo di oggetto",
    ["Sort in the opposite direction."] = "Ordina nella direzione opposta.",
    ["Item level"] = "Livello oggetto",
    ["Off"] = "Disattivato",
    ["Sort categories by"] = "Ordina le categorie per",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "Ordinamento solo visivo degli oggetti dentro ogni sezione di categoria. Non sposta mai nulla nelle tue borse.",
    ["Show free slots (OneBag)"] = "Mostra gli slot liberi (OneBag)",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "Vista OneBag: mostra gli slot vuoti dopo gli oggetti, così puoi trascinarci sopra le cose direttamente.",
    ["Fixed slot order (OneBag)"] = "Ordine fisso degli slot (OneBag)",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "Mostra ogni slot nel suo ordine naturale di borsa con gli slot vuoti in linea: gli oggetti restano visivamente dove li lasci, come un'unica grande borsa vera. Richiede l'opzione slot liberi qui sopra.",
    ["Junk marker (C)"] = "Indicatore cianfrusaglie (C)",
    ["Marks vendor trash with a purple C in the icon corner - grey items a merchant pays gold for."] = "Marca le cianfrusaglie con una C viola nell'angolo dell'icona: oggetti grigi per cui un mercante paga oro.",
    ["BoE/BoU markers"] = "Indicatori BoE/BoU",
    ["Tags equipment that is still tradeable (binds on equip or use, not yet soulbound) - handy for banking and the auction house."] = "Contrassegna l'equipaggiamento ancora scambiabile (si lega all'equipaggiamento o all'uso, non ancora legato) — utile per la banca e la casa d'aste.",
    ["Categories"] = "Categorie",
    ["Group items into categories"] = "Raggruppa gli oggetti in categorie",
    ["Show items in labelled sections (Quest, Consumables, Armor...). Off = one flat grid."] = "Mostra gli oggetti in sezioni etichettate (Missioni, Consumabili, Armature...). Disattivato = un'unica griglia.",
    ["Hide empty categories"] = "Nascondi le categorie vuote",
    ["Don't show a section header for a category that has no items."] = "Non mostrare l'intestazione di sezione per una categoria senza oggetti.",
    ["Consumables"] = "Consumabili",
