    ["View"] = "Vista",
    ["View mode"] = "Modalità di visualizzazione",
    ["All = categorized sections. OneBag = one flat grid. MultiBag = a section per bag."] = "Tutti = sezioni per categoria. OneBag = un'unica griglia. MultiBag = una sezione per borsa.",
    ["All Items"] = "Tutti gli oggetti",
