    ["Show sidebar"] = "Mostra la barra laterale",
    ["A collapsible left panel for view modes and category filtering."] = "Un pannello a sinistra richiudibile per le modalità di visualizzazione e il filtro delle categorie.",
    ["Collapse sidebar"] = "Richiudi la barra laterale",
    ["Expand sidebar"] = "Espandi la barra laterale",
    ["New category..."] = "Nuova categoria...",
