    ["Disable category"] = "Disattiva categoria",
    ["Show category: %s"] = "Mostra categoria: %s",
    ["Reset category order"] = "Reimposta l'ordine delle categorie",
    ["|cffaaaaaaTip: drag an item onto a category in the sidebar to keep it there; right-click a category to rename, move or delete it.|r"] = "|cffaaaaaaSuggerimento: trascina un oggetto su una categoria nella barra laterale per tenerlo lì; clic destro su una categoria per rinominarla, spostarla o eliminarla.|r",
    ["Pinned Items"] = "Oggetti fissati",
    ["Recent Items"] = "Oggetti recenti",
    ["Show Recent Items"] = "Mostra gli oggetti recenti",
    ["Show a 'Recent Items' section for new item types you gain; it clears when you close the bag."] = "Mostra una sezione 'Oggetti recenti' per i nuovi tipi di oggetto che ottieni; si svuota quando chiudi le borse.",
    ["Recent items kept"] = "Oggetti recenti conservati",
    ["Maximum number of distinct recent items to remember (0 = no limit)."] = "Numero massimo di oggetti recenti distinti da ricordare (0 = nessun limite).",
    ["Clear recent"] = "Svuota i recenti",
    ["Unpin all items"] = "Rimuovi tutti gli oggetti fissati",
    ["|cffaaaaaaTip: middle-click an item to pin it to the top; middle-click again to unpin.|r"] = "|cffaaaaaaSuggerimento: clic centrale su un oggetto per fissarlo in cima; clic centrale di nuovo per rimuoverlo dai fissati.|r",
