    ["Point colour"] = "Colore dei punti",
    ["Show crowd control (separate row)"] = "Mostra il crowd control (riga separata)",
    ["A separate, prominent row for crowd-control effects (Polymorph, Fear, Sap, …) on the unit, from anyone."] = "Una riga separata e in evidenza per gli effetti di crowd control (Metamorfosi, Paura, Fiaccare, …) sull'unità, da chiunque provengano.",
    ["CC icon size"] = "Dimensione delle icone CC",
    ["Max CC"] = "CC massimi",
    ["Highlight your focus"] = "Evidenzia il tuo focus",
    ["A second, distinct glow ring on your focus target's nameplate."] = "Un secondo anello luminoso distinto sulla nameplate del tuo focus.",
    ["Focus highlight colour"] = "Colore dell'evidenziazione del focus",
    ["Glow stealable / dispellable buffs"] = "Illumina i buff rubabili / dissolvibili",
    ["Glows enemy buffs you can remove (Spellsteal / Purge / Dispel Magic). Only for classes that can."] = "Illumina i buff nemici che puoi rimuovere (Furto Magico / Purificazione / Dissolvi Magie). Solo per le classi che possono farlo.",
    ["Dispel glow colour"] = "Colore del bagliore di dissolvimento",
    ["Show absorb shield"] = "Mostra lo scudo di assorbimento",
    ["Overlays damage-absorption shields (e.g. Power Word: Shield) on the health bar."] = "Sovrappone alla barra della salute gli scudi che assorbono danni (es. Parola di Potere: Scudo).",
    ["Absorb colour"] = "Colore dell'assorbimento",
    ["Absorb opacity"] = "Opacità dell'assorbimento",
    ["Colour by threat"] = "Colora in base alla minaccia",
    ["Colour the health bar by your threat on the unit — coloured for your role. Useful in dungeons."] = "Colora la barra della salute in base alla tua minaccia sull'unità, secondo il tuo ruolo. Utile nei dungeon.",
    ["Your role"] = "Il tuo ruolo",
    ["DPS / Healer"] = "DPS / Healer",
    ["Tank"] = "Tank",
    ["Secure (tank has aggro)"] = "Sicuro (il tank ha l'aggro)",
    ["Warning (gaining / losing)"] = "Attenzione (in aumento / in calo)",
    ["Danger (pulled / lost)"] = "Pericolo (pull preso / perso)",
    ["Show NPC title"] = "Mostra il titolo dell'NPC",
    ["Shows a friendly NPC's subtitle (e.g. <Innkeeper>) under its name in name-only mode."] = "Mostra il sottotitolo di un NPC amichevole (es. <Innkeeper>) sotto il suo nome nella modalità solo nome.",
    ["<Innkeeper>"] = "<Innkeeper>",
    ["Nameplates"] = "Nameplate",
    ["Vulo Fantasy 1"] = "Vulo Fantasy 1",
    ["Vulo Fantasy 2"] = "Vulo Fantasy 2",
    ["Vulo Epic"] = "Vulo Epic",
    ["Always shown"] = "Sempre visibile",
    ["Mouseover"] = "Mouseover",
    ["In combat"] = "In combattimento",
    ["Out of combat"] = "Fuori combattimento",
    ["Faded opacity"] = "Opacità in dissolvenza",
    ["Fade speed (sec.)"] = "Velocità di dissolvenza (sec.)",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555Barre delle azioni: attendo la fine del combattimento per ripristinare le barre di Blizzard…|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaPulsanti propri per ogni barra delle azioni (1-5): vera comparsa/scomparsa in combattimento / al mouseover, scala e layout a griglia, paginazione corretta della barra principale (forme di druido/ladro/guerriero/sacerdote) e i tuoi tasti assegnati. Spostale nella Modalità Modifica (/vedit). Dopo la disattivazione, /reload per ripristinare completamente le barre di Blizzard.|r",
    ["Action Bar 1 (Main)"] = "Barra delle azioni 1 (Principale)",
    ["Action Bar 2"] = "Barra delle azioni 2",
    ["Action Bar 3"] = "Barra delle azioni 3",
    ["Action Bar 4"] = "Barra delle azioni 4",
    ["Action Bar 5"] = "Barra delle azioni 5",
    ["Action Bar 6 (Extra)"] = "Barra delle azioni 6 (Extra)",
    ["Grow from"] = "Espandi da",
    ["Left edge (rightwards)"] = "Bordo sinistro (verso destra)",
    ["Right edge (leftwards)"] = "Bordo destro (verso sinistra)",
    ["Rows grow"] = "Espansione righe",
    ["Mouseover reveals all mouseover bars"] = "Il mouseover rivela tutte le barre in mouseover",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "Passare il mouse su UNA QUALSIASI barra in mouseover mostra contemporaneamente tutte le barre impostate su mouseover.",
    ["Button text styling"] = "Stile del testo dei pulsanti",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaaColori e regolazioni fini di posizione per i testi dei pulsanti, su tutte le barre.|r",
    ["Keybind text colour"] = "Colore del testo dei tasti",
    ["Macro text colour"] = "Colore del testo delle macro",
    ["Count text colour"] = "Colore del testo del conteggio",
    ["Keybind offset X"] = "Scostamento X del tasto",
    ["Keybind offset Y"] = "Scostamento Y del tasto",
    ["Macro offset X"] = "Scostamento X della macro",
    ["Macro offset Y"] = "Scostamento Y della macro",
    ["Count offset X"] = "Scostamento X del conteggio",
    ["Count offset Y"] = "Scostamento Y del conteggio",
    ["0 = use the game's default size."] = "0 = usa la dimensione predefinita del gioco.",
    ["Vertical layout"] = "Layout verticale",
    ["Reverse order"] = "Ordine inverso",
    ["Hide keybind text"] = "Nascondi il testo dei tasti",
    ["Hide macro text"] = "Nascondi il testo delle macro",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): square, accent edge, shadow and more.|r"] = "|cff9b6cffLo stile di bordo / icona dei pulsanti si trova nel modulo Dark Skin (Barre delle azioni > Stile barra): quadrato, bordo accentato, ombra e altro.|r",
    ["Game Menu"] = "Menu di gioco",
    ["Game menu: VuloUI look"] = "Menu di gioco: aspetto VuloUI",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Ridisegna il menu Esc per adattarlo all'aspetto dell'addon: pannello scuro, pulsanti piatti, titolo accentato. Modificare questa opzione richiede un /reload.",
    ["Game menu: VuloClassicUI button"] = "Menu di gioco: pulsante VuloClassicUI",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Aggiunge al menu Esc un pulsante VuloClassicUI che apre la finestra delle opzioni. Disattivarlo richiede un /reload.",
    ["Hide the FPS / latency bar"] = "Nascondi la barra FPS / latenza",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "Nasconde la piccola barra verde delle prestazioni (FPS / latenza) di Blizzard.",
    ["Micro menu style"] = "Stile del micro menu",
    ["World map"] = "Mappa del mondo",
    ["Friends list"] = "Lista amici",
    ["Group finder"] = "Cerca gruppo",
    ["Bag bar style"] = "Stile della barra delle borse",
    ["Key ring"] = "Portachiavi",
    ["Timer decimals below 10 seconds"] = "Decimali del timer sotto i 10 secondi",
    ["Interrupted by %s"] = "Interrotto da %s",
    ["Value + percent"] = "Valore + percentuale",
    ["Value + percent layout"] = "Disposizione valore + percentuale",
    ["Short values (12.3k)"] = "Valori abbreviati (12.3k)",
    ["Show percent sign"] = "Mostra il simbolo di percentuale",
    ["Smooth health changes"] = "Variazioni di salute fluide",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "La barra scorre fino al nuovo valore; una scia luminosa segnala la salute che si svuota.",
    ["Tint background with bar colour"] = "Colora lo sfondo con il colore della barra",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "La parte vuota della barra mostra una tonalità scurita del colore della barra invece del semplice grigio scuro.",
    ["Glow at the bar edge"] = "Bagliore sul bordo della barra",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "Un bagliore tenue accompagna la fine del riempimento, tinto con il colore della barra stessa. Vale anche per la barra di lancio.",
    ["Edge glow width"] = "Larghezza del bagliore sul bordo",
    ["Rounded bar corners"] = "Angoli arrotondati della barra",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "Ritaglia riempimento e sfondo in una forma arrotondata. Il bordo lineare resta squadrato, quindi agli angoli può restare visibile una linea sottile.",
    ["Overall plate scale (%)"] = "Scala generale delle nameplate (%)",
    ["Scales every plate at once, on top of each individual size."] = "Ridimensiona tutte le nameplate insieme, oltre alle dimensioni individuali.",
    ["Vertical offset"] = "Scostamento verticale",
    ["Moves every plate up or down relative to its unit."] = "Sposta ogni nameplate verso l'alto o verso il basso rispetto alla sua unità.",
    ["Font outline"] = "Contorno del carattere",
    ["How plate text is lifted off the background."] = "Quanto il testo della nameplate si stacca dallo sfondo.",
    ["Thick outline"] = "Contorno spesso",
    ["Show level"] = "Mostra il livello",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "Mostra il livello dell'unità a sinistra del nome; ?? indica un livello molto superiore al tuo.",
    ["Mark rare and elite"] = "Segnala rari ed élite",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "Aggiunge un grado al livello e lo colora d'oro: + élite, R raro, R+ raro élite, B boss mondiale.",
    ["Level size"] = "Dimensione del livello",
    ["0 = uses the name size."] = "0 = usa la dimensione del nome.",
    ["Emphasise casting units"] = "Evidenzia le unità che stanno lanciando",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "Mentre un'unità lancia, la sua nameplate si ingrandisce un po' e resta leggibile anche se hai selezionato un altro bersaglio.",
    ["Casting scale (%)"] = "Scala durante il lancio (%)",
    ["Casting opacity (%)"] = "Opacità durante il lancio (%)",
    ["Colour border by school"] = "Colora il bordo per scuola",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "I bordi delle aure prendono il colore della loro scuola: magia blu, maledizione viola, malattia arancione, veleno verde.",
    ["Flash before running out"] = "Lampeggia prima della scadenza",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "L'icona pulsa nell'ultima parte della durata, così vedi quando rinnovarla.",
    ["Flash below (%)"] = "Lampeggia sotto il (%)",
    ["Your Own Debuffs"] = "I tuoi debuff",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaUna riga separata per le aure dannose che lanci tu - i timer dei tuoi danni nel tempo, tenuti lontani da tutto il resto sul bersaglio.|r",
    ["Show your own debuffs (separate row)"] = "Mostra i tuoi debuff (riga separata)",
    ["Max icons"] = "Icone massime",
    ["Icons per line"] = "Icone per riga",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = una sola riga. Altrimenti la riga va a capo dopo questo numero di icone.",
    ["Reminders"] = "Promemoria",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaMostra una breve riga di icone con ciò che ti manca in questo momento. Fuori combattimento un clic lancia o usa il rimedio; passandoci sopra il mouse ne spiega il motivo. In combattimento la riga resta ferma.|r",
    ["Also warn about empty equipment slots"] = "Avvisa anche per gli slot dell'equipaggiamento vuoti",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "Disattivato di default: un anello, un monile o un mantello sono spesso vuoti legittimamente durante il livellamento.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Mostra ciò che ti manca - buff di classe, incantamenti sulle armi, cibo, postura, pet, munizioni, durabilità, slot vuoti e punti talento non spesi.",
    ["What to watch"] = "Cosa controllare",
    ["Class buffs"] = "Buff di classe",
    ["Weapon enchants"] = "Incantamenti sulle armi",
    ["Stance and aura"] = "Postura e aura",
    ["Food and flask"] = "Cibo e flask",
    ["Ammo, durability, gear, talents"] = "Munizioni, durabilità, equipaggiamento, talenti",
    ["Most icons at once"] = "Numero massimo di icone",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Tutto ciò che supera questo limite viene raccolto in un unico contatore invece di aggiungere altre icone.",
    ["Show labels"] = "Mostra le etichette",
    ["Settle time (seconds)"] = "Tempo di attesa (secondi)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Per quanto tempo qualcosa deve mancare prima che compaia un'icona. Evita che lampeggi tra un lancio e l'altro.",
    ["Warn when under (seconds)"] = "Avvisa sotto (secondi)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Avvisa anche quando un buff o un incantamento dell'arma sta per scadere. 0 = avvisa solo quando è finito.",
    ["Durability below (%)"] = "Durabilità sotto il (%)",
    ["Ammo below"] = "Munizioni sotto",
    ["Quiet while resting"] = "Silenzio mentre riposi",
    ["No reminders in a city or inn."] = "Nessun promemoria in città o in locanda.",
    ["Quiet while eating or drinking"] = "Silenzio mentre mangi o bevi",
    ["Click to cast."] = "Clicca per lanciare.",
    ["Missing: %s"] = "Manca: %s",
    ["Main hand"] = "Mano primaria",
    ["Off hand"] = "Mano secondaria",
    ["No weapon enchant: %s"] = "Nessun incantamento sull'arma: %s",
    ["Weapon enchant running out: %s"] = "Incantamento dell'arma in scadenza: %s",
    ["Stance"] = "Postura",
    ["No stance active"] = "Nessuna postura attiva",
    ["Aura"] = "Aura",
    ["No aura active"] = "Nessuna aura attiva",
    ["Pet"] = "Pet",
    ["No pet out"] = "Nessun pet evocato",
    ["Passive"] = "Passivo",
    ["Pet is set to passive"] = "Il pet è impostato su passivo",
    ["Food"] = "Cibo",
    ["Not well fed"] = "Non ben nutrito",
    ["Flask"] = "Flask",
    ["No flask or elixir"] = "Nessun flask o elisir",
    ["Low ammo: %d left"] = "Munizioni scarse: ne restano %d",
    ["Equipment damaged: %d%% left"] = "Equipaggiamento danneggiato: %d%% rimanente",
    ["Empty equipment slots: %d"] = "Slot dell'equipaggiamento vuoti: %d",
    ["Unspent talent points: %d"] = "Punti talento non spesi: %d",
    ["Racials"] = "Razziali",
    ["Racial Cooldowns"] = "Cooldown razziali",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Mostra l'abilità razziale dell'avversario e il suo cooldown non appena la usa. Sono i cooldown di questa espansione e nessuna razziale condivide ancora il cooldown con il monile PvP.",
    ["Show racial cooldown"] = "Mostra il cooldown razziale",
    ["Shadow Sight"] = "Shadow Sight",
    ["Shadow Sight up"] = "Shadow Sight attivo",
    ["Shadow Sight up - next in %d s"] = "Shadow Sight attivo - prossimo tra %d s",
    ["Shadow Sight in %d s"] = "Shadow Sight tra %d s",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Conta alla rovescia le sfere dell'arena: la prima coppia compare 95 secondi dopo l'apertura dei cancelli e ognuna ritorna 122 secondi dopo essere stata presa.",
    ["Show Shadow Sight timer"] = "Mostra il timer di Shadow Sight",
    ["Aura on the class icon"] = "Aura sull'icona della classe",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Mette sull'icona della classe dell'avversario l'unica aura più rilevante: un'immunità ha la precedenza sul controllo, che ha la precedenza su un cooldown difensivo, che ha la precedenza su uno offensivo.",
    ["Show aura on the class icon"] = "Mostra l'aura sull'icona della classe",
    ["Crowd control only"] = "Solo controllo (CC)",
    ["Dispels"] = "Dissipazioni",
    ["Dispel Cooldowns"] = "Cooldown delle dissipazioni",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaIn questa espansione la maggior parte delle dissipazioni non ha cooldown, quindi qui possono comparire solo Mass Dispel e Devour Magic del felhunter.|r",
    ["Show dispel cooldown"] = "Mostra il cooldown della dissipazione",
    ["Range"] = "Distanza",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Sfuma il frame mentre l'avversario è fuori portata, misurando con un incantesimo che la tua classe conosce invece che con una distanza fissa.",
    ["Fade out-of-range opponents"] = "Sfuma gli avversari fuori portata",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Annulla le modifiche e riporta ogni finestra all'ultimo salvataggio, o a com'era all'apertura della Modalità Modifica.",
    ["Discard all changes made since the last save?"] = "Annullare tutte le modifiche fatte dall'ultimo salvataggio?",
    ["Grey out when you walk out of range"] = "Scolora quando esci dal raggio d'azione",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Toglie il colore mentre sei fuori dal raggio di un totem e lo ripristina quando rientri. Viene riconosciuto dal buff che il totem ti applica, quindi i totem che non danno alcun buff (Searing, Magma, Tremor, ...) restano sempre accesi.",
    ["Limit to"] = "Limita a",
    ["Everything"] = "Tutto",
    ["Only mine"] = "Solo le mie",
    ["Only removable"] = "Solo quelle rimovibili",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Restringe questa riga alle aure che lanci tu, oppure a quelle che possono essere rimosse.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "Sposta tutte le righe di aure insieme, oltre allo scostamento proprio di ogni riga.",
    ["Share of the remaining duration at which the pulse starts."] = "Quota della durata rimanente alla quale inizia la pulsazione.",
    ["Own colour while your interrupt is ready"] = "Colore dedicato quando la tua interruzione è pronta",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "I lanci interrompibili vengono colorati così quando la tua interruzione non è in cooldown — puoi interrompere quando vuoi.",
    ["Interrupt-ready colour"] = "Colore interruzione pronta",
    ["Own colour while channelling"] = "Colore dedicato durante la canalizzazione",
    ["Channel colour"] = "Colore della canalizzazione",
    ["Own colour when the cast targets YOU"] = "Colore dedicato quando il lancio è su di TE",
    ["The bar turns this colour while the caster's target is you."] = "La barra assume questo colore mentre il bersaglio di chi lancia sei tu.",
    ["Targets-you colour"] = "Colore bersaglio su di te",
    ["Show who interrupted"] = "Mostra chi ha interrotto",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "Il lampo di interruzione mostra il nome di chi ha messo a segno l'interruzione.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Attivo: 9.9, 3.4 … Disattivo: secondi interi (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "Modern mette i veri pulsanti delle borse su una striscia scura e piatta nell'aspetto VuloUI — apertura, scambio e tooltip restano identici.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "Modern sostituisce i pulsanti di Blizzard con una striscia di icone scura e piatta nell'aspetto VuloUI. Clic e tooltip restano identici.",
    ["Classic (Blizzard buttons)"] = "Classic (pulsanti Blizzard)",
    ["Modern (flat icon strip)"] = "Modern (striscia di icone piatta)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Nasconde la riga dei pulsanti del menu (personaggio, libro degli incantesimi, …).",
    ["Hide the bag bar"] = "Nascondi la barra delle borse",
    ["Hides the backpack and bag slots."] = "Nasconde lo zaino e gli slot delle borse.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffIl micro menu, la barra delle borse, la barra FPS/latenza e la barra dell'esperienza qui sotto si possono spostare nella Modalità Modifica (/vedit) come le barre delle azioni.|r",
    ["Micro menu"] = "Micro menu",
    ["Bag bar"] = "Barra delle borse",
    ["FPS / latency bar"] = "Barra FPS / latenza",
    ["XP bar"] = "Barra dell'esperienza",
    ["Show a custom XP bar"] = "Mostra una barra dell'esperienza personalizzata",
    ["Colour"] = "Colore",
    ["Bar opacity"] = "Opacità della barra",
    ["Show empty buttons"] = "Mostra i pulsanti vuoti",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "Disattivato nasconde gli slot vuoti; ricompaiono automaticamente mentre trascini un'abilità.",
    ["Click through"] = "Clic passanti",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "La barra ignora completamente il mouse: i clic la attraversano. I tasti assegnati funzionano comunque.",
    ["Keybind text size"] = "Dimensione del testo dei tasti",
    ["Macro text size"] = "Dimensione del testo delle macro",
    ["Count text size"] = "Dimensione del testo del conteggio",
    ["Cooldown text size"] = "Dimensione del testo del cooldown",
    ["0 = default size."] = "0 = dimensione predefinita.",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = dimensione predefinita. Richiede che i numeri del cooldown siano attivi nelle opzioni di gioco.",
    ["Cooldown & look"] = "Cooldown e aspetto",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555La modalità di assegnazione rapida dei tasti non è disponibile su questo client.|r",
    ["Modifier paging"] = "Paginazione con modificatori",
    ["Click: open these settings"] = "Clic: apri queste impostazioni",
    ["Crowd Control"] = "Controllo (CC)",
    ["Addon font (default)"] = "Carattere dell'addon (predefinito)",
    ["The typeface for every text on the plates (name, health, cast, auras)."] = "Il carattere di ogni testo sulle nameplate (nome, salute, lancio, aure).",
    ["Health text size"] = "Dimensione del testo della salute",
    ["0 = uses the general text size."] = "0 = usa la dimensione generale del testo.",
    ["Cast text size"] = "Dimensione del testo del lancio",
    ["Cast background colour"] = "Colore di sfondo della barra di lancio",
    ["Cast background opacity"] = "Opacità di sfondo della barra di lancio",
    ["0 = uses the global background opacity."] = "0 = usa l'opacità di sfondo globale.",
    ["Icon scale"] = "Scala dell'icona",
    ["Icon on the right"] = "Icona a destra",
    ["Icon offset X"] = "Scostamento X dell'icona",
    ["Icon offset Y"] = "Scostamento Y dell'icona",
    ["Shield on uninterruptible casts"] = "Scudo sui lanci non interrompibili",
    ["Tick where your interrupt becomes ready"] = "Tacca dove la tua interruzione diventa pronta",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "Segna il punto sulla barra di lancio nemica in cui la TUA interruzione esce dal cooldown: tutto ciò che viene dopo la tacca è interrompibile.",
    ["Tick colour"] = "Colore della tacca",
    ["Flash when a cast is interrupted"] = "Lampeggia quando un lancio viene interrotto",
    ["Flash colour"] = "Colore del lampo",
