    ["Execute line"] = "Linea di Execute",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "Una sottile linea indicatrice sulla barra alla percentuale di salute scelta (es. 20 per Execute).",
    ["Execute line only on your target"] = "Linea di Execute solo sul tuo bersaglio",
