    ["Own colour while your interrupt is on cooldown"] = "Colore dedicato quando la tua interruzione è in cooldown",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "I lanci interrompibili vengono colorati diversamente mentre la TUA abilità di interruzione è ancora in cooldown: capisci a colpo d'occhio se interrompere è possibile.",
    ["Interrupt-on-cooldown colour"] = "Colore interruzione in cooldown",
    ["Own bar colour on your target"] = "Colore dedicato per la barra del tuo bersaglio",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "La barra della salute del tuo bersaglio attuale usa questo colore invece dei colori di reazione / classe / minaccia.",
    ["Target bar colour"] = "Colore della barra del bersaglio",
    ["Mouseover highlight"] = "Evidenziazione al mouseover",
    ["Lightens the health bar of the plate under your mouse cursor."] = "Schiarisce la barra della salute della nameplate sotto il cursore del mouse.",
    ["Target plate scale"] = "Scala della nameplate del bersaglio",
    ["Your target's plate is drawn this much larger (100 = off)."] = "La nameplate del tuo bersaglio viene disegnata più grande di questa quantità (100 = disattivato).",
    ["Behaviour"] = "Comportamento",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaaQueste sono le impostazioni delle nameplate del gioco stesso, modificate in tempo reale (non fanno parte del profilo). Non modificabili in combattimento.|r",
    ["Plate motion"] = "Movimento delle nameplate",
    ["Overlapping"] = "Sovrapposte",
    ["Stacking"] = "Impilate",
    ["Stacked spacing"] = "Spaziatura delle impilate",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "Distanza verticale tra le nameplate impilate (un decimo del valore del gioco).",
    ["Line-of-sight opacity"] = "Opacità fuori linea di vista",
    ["Opacity of plates whose unit is out of your line of sight."] = "Opacità delle nameplate la cui unità è fuori dalla tua linea di vista.",
    ["Plate view distance"] = "Distanza di visualizzazione delle nameplate",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaMentre il tasto è premuto (o il tuo bersaglio corrisponde), la barra principale mostra le abilità della barra scelta. Completamente sicuro: funziona in combattimento.|r",
    ["Shift held"] = "Shift premuto",
    ["Ctrl held"] = "Ctrl premuto",
    ["Alt held"] = "Alt premuto",
    ["Friendly target"] = "Bersaglio amichevole",
    ["Hostile target"] = "Bersaglio ostile",
    ["Group visibility"] = "Visibilità in gruppo",
    ["Always"] = "Sempre",
    ["Only in a group"] = "Solo in gruppo",
    ["Only in a party"] = "Solo in party",
    ["Only solo"] = "Solo da solo",
    ["Hide when mounted"] = "Nascondi in cavalcatura",
    ["Hide without target"] = "Nascondi senza bersaglio",
    ["Hide without enemy target"] = "Nascondi senza bersaglio nemico",
    ["Quick keybind mode (/vkb)"] = "Modalità assegnazione rapida tasti (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Passa il mouse su un pulsante azione e premi un tasto per assegnarlo. Le barre nascoste vengono mostrate durante l'assegnazione.",
    ["Swipe colour"] = "Colore della spazzata",
    ["Icon opacity on cooldown"] = "Opacità dell'icona in cooldown",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Attenua l'intera icona mentre l'abilità è in cooldown (100 = disattivato).",
    ["Show cooldown numbers"] = "Mostra i numeri del cooldown",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "I numeri del conto alla rovescia del gioco stesso sui cooldown (un'impostazione di gioco, modificata in tempo reale).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaVale per tutte le barre delle azioni.|r",
    ["Cooldown swipe opacity"] = "Opacità della spazzata del cooldown",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Quanto è scura la spazzata del cooldown (0 = invisibile).",
    ["Desaturate icons on cooldown"] = "Desatura le icone in cooldown",
    ["Out-of-range colouring"] = "Colorazione fuori portata",
    ["Tints the whole icon while your target is out of range."] = "Colora l'intera icona mentre il tuo bersaglio è fuori portata.",
    ["Tooltips"] = "Tooltip",
    ["Hide in combat"] = "Nascondi in combattimento",
    ["Hide always"] = "Nascondi sempre",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Una barra dell'esperienza spostabile e ridimensionabile con sovrapposizione del riposo. Nascosta al livello massimo. Quando è attiva sostituisce la barra di Blizzard.",
    ["Hide Blizzard's XP / reputation bar"] = "Nascondi la barra esperienza / reputazione di Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Rimuove la barra blu residua di esperienza / reputazione sotto la barra delle azioni.",
    ["Stance bar"] = "Barra delle posture",
    ["Pet bar"] = "Barra del pet",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Prende il controllo di ogni barra delle azioni con frame propri e spostabili: vera comparsa/scomparsa in combattimento e al mouseover, scala e layout a griglia per barra, paginazione corretta della barra principale (forme di druido/ladro/guerriero/sacerdote) e i tuoi tasti assegnati. SPERIMENTALE — prova i clic sulle abilità e la paginazione in combattimento; /reload dopo la disattivazione.",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bars.|r"] = "|cffffcc00Barre delle azioni disattivate — digita /reload per ripristinare completamente le barre predefinite.|r",
    ["Buttons per row"] = "Pulsanti per riga",
    ["Button spacing"] = "Spaziatura dei pulsanti",
    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DELLA RISORSA|r\\n|cffaaaaaaTrascina o frecce direzionali|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "Spostamento della barra della risorsa attivo. |cff9b6cffTrascina il riquadro viola|r o usa le |cff9b6cfffrecce direzionali|r (SHIFT = 5px). Clicca di nuovo su “Sblocca / Sposta” per terminare.",
    ["Power Bar mover disabled."] = "Spostamento della barra della risorsa disattivato.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaaBarra della risorsa che segue automaticamente la tua classe (Mana / Ira / Energia). I Druidi cambiano con la forma: Orso = Ira, Gatto = Energia, altrimenti Mana.|r",
    ["v%s loaded. /vcui to open."] = "v%s caricato. /vcui per aprire.",
    ["UI not loaded. Likely a Lua error during init. Enable /console scriptErrors 1 and /reload."] = "Interfaccia non caricata. Probabile errore Lua durante l'avvio. Attiva /console scriptErrors 1 e /reload.",
    ["Not possible in combat."] = "Non possibile in combattimento.",
    ["DB reset. UI reloading."] = "Database azzerato. Ricaricamento dell'interfaccia.",
    ["Debug = %s"] = "Debug = %s",
    ["Registered modules:"] = "Moduli registrati:",
    ["ON"] = "ON",
    ["off"] = "off",
    ["Gold Tracker not active."] = "Monitoraggio dell'oro non attivo.",
    ["|cffff5555Error while executing:|r %s"] = "|cffff5555Errore durante l'esecuzione:|r %s",
    ["|cffff5555Event handler error (%s):|r %s"] = "|cffff5555Errore nel gestore dell'evento (%s):|r %s",
    ["WARN: Module '%s' already registered."] = "ATTENZIONE: modulo “%s” già registrato.",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Errore nell'attivazione del modulo “%s”:|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Errore nella disattivazione di “%s”:|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Modulo “%s” disattivato. /reload consigliato per l'effetto completo.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 non trovata, il Media Registry verrà saltato.|r",
    ["Profiles"] = "Profili",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Gestisci profili con impostazioni diverse. Un profilo predefinito può essere assegnato a ogni classe e viene caricato automaticamente all'accesso.",
    ["Active Profile"] = "Profilo attivo",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Stai usando: |cff9b6cff%s|r  (Classe: %s)",
    ["Switch Profile"] = "Cambia profilo",
    ["Profile for this character"] = "Profilo per questo personaggio",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaFissa un profilo SOLO a QUESTO personaggio. All'accesso ha la priorità sull'assegnazione per classe e sulla selezione dell'account, così ogni personaggio può mantenere le proprie impostazioni di minimappa, barre e finestre.|r",
    ["This character"] = "Questo personaggio",
    ["Create New Profile"] = "Crea nuovo profilo",
    ["Name"] = "Nome",
    ["Copy Settings From"] = "Copia le impostazioni da",
    ["- empty profile (defaults) -"] = "- profilo vuoto (predefiniti) -",
    ["- none -"] = "- nessuno -",
    ["Create Profile"] = "Crea profilo",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Inserisci un nome.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Inserisci un nuovo nome.|r",
    ["Error."] = "Errore.",
    ["Share Profile"] = "Condividi il profilo",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaEsporta il profilo attuale come stringa di testo, come backup o per condividerlo. L'importazione crea sempre un NUOVO profilo e non sovrascrive mai nulla.|r",
    ["Export as string"] = "Esporta come stringa",
    ["Import from string"] = "Importa da stringa",
    ["This is not a VuloClassicUI profile string."] = "Questa non è una stringa di profilo VuloClassicUI.",
    ["The profile string is damaged."] = "La stringa del profilo è danneggiata.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Profilo “%s” importato. Attivalo con “Cambia profilo”.",
    ["Manage Profiles"] = "Gestisci i profili",
    ["Delete..."] = "Elimina...",
    ["Reset to defaults..."] = "Ripristina i predefiniti...",
    ["Delete profile '%s'? This cannot be undone."] = "Eliminare il profilo “%s”? L'operazione non può essere annullata.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "Ripristinare il profilo “%s” alle impostazioni predefinite? L'operazione non può essere annullata.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Profilo cambiato. Ricaricare ora l'interfaccia così che tutti i moduli lo applichino?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Impossibile caricare il profilo “%s”:|r %s",
    ["Rename to"] = "Rinomina in",
    ["Rename"] = "Rinomina",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555Il profilo predefinito non può essere eliminato.|r",
    ["Apply to Active Class"] = "Applica alla classe attuale",
    ["Sets the current profile as the default for %s."] = "Imposta il profilo attuale come predefinito per %s.",
    ["'%s' is now the default profile for %s."] = "“%s” è ora il profilo predefinito per %s.",
    ["Per-class profile (quick setup)"] = "Profilo per classe (configurazione rapida)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaUn clic: crea un profilo con il nome della tua classe (copiato da quello attuale) e lo carica automaticamente per questa classe. Eseguilo una volta su ogni personaggio: ogni classe manterrà così le proprie barre dei cooldown, finestre e impostazioni.|r",
    ["Set up a %s profile"] = "Crea un profilo %s",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "“%s” è ora il profilo per %s. |cffffff00/reload|r per applicare.",
    ["Profile Assignment per Class"] = "Assegnazione dei profili per classe",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Scegli un profilo predefinito per ogni classe. Accedendo con un personaggio di quella classe, il profilo verrà caricato automaticamente.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Impostazioni migrate al sistema dei profili (tutte le impostazioni sono nel profilo “%s”).",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555Il profilo “%s” non esiste.|r",
    ["Profile '%s' created%s."] = "Profilo “%s” creato%s.",
    [" (copy of '%s')"] = " (copia di “%s”)",
    ["Name cannot be empty."] = "Il nome non può essere vuoto.",
    ["Profile already exists."] = "Il profilo esiste già.",
    ["Default profile cannot be deleted."] = "Il profilo predefinito non può essere eliminato.",
    ["Profile does not exist."] = "Il profilo non esiste.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "Profilo attivo eliminato. Caricato quello predefinito. /reload consigliato.",
    ["Profile '%s' deleted."] = "Profilo “%s” eliminato.",
    ["Default profile cannot be renamed."] = "Il profilo predefinito non può essere rinominato.",
    ["New name already exists."] = "Il nuovo nome esiste già.",
    ["Profile '%s' renamed to '%s'."] = "Profilo “%s” rinominato in “%s”.",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "Profilo “%s” caricato. |cffffff00/reload|r consigliato affinché tutti i moduli usino le nuove impostazioni.",
    ["Settings imported from VuloFontBars."] = "Impostazioni importate da VuloFontBars.",
