    ["Global UI settings + profile management."] = "Impostazioni globali dell'interfaccia + gestione dei profili.",
    ["UI Scale"] = "Scala interfaccia",
    ["Manual UI scaling. 0.65 is smaller, 1.0 is default."] = "Scala manuale dell'interfaccia. 0.65 è più piccola, 1.0 è il valore predefinito.",
    ["Pixel Perfect"] = "Pixel Perfect",
    ["UI Scale = %.4f (pixel perfect)"] = "Scala interfaccia = %.4f (pixel perfect)",
    ["1080p Scale"] = "Scala 1080p",
