    ["Max Camera Distance"] = "Distanza massima della telecamera",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "Distanza massima della telecamera (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "Mostra il pulsante sulla minimappa",
    ["Toggle the VuloClassicUI button on the minimap."] = "Attiva o disattiva il pulsante VuloClassicUI sulla minimappa.",
    ["Show CPU Usage in Header"] = "Mostra l'uso della CPU nell'intestazione",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Mostra l'uso totale della CPU di tutti gli addon attivi (più la quota di VuloClassicUI) in cima all'intestazione della configurazione.\\n\\n|cffaaaaaaRichiede un /reload dopo la modifica.\\n\\nNota: attiva la CVar scriptProfile di WoW, che comporta un costo prestazionale del 3-5% circa: è il prezzo da pagare perché WoW raccolga questi dati.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Profilazione degli script modificata. È necessario un /reload perché l'indicatore della CPU si aggiorni.",
    ["Reload now"] = "Ricarica ora",
    ["Later"] = "Più tardi",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Mostra un pulsante sulla minimappa per aprire rapidamente VuloClassicUI. Shift+trascina sposta il pulsante.",
    ["UI is not loaded yet."] = "L'interfaccia non è ancora caricata.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffClic sinistro:|r apre le opzioni",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffClic destro:|r selezione rapida dei moduli",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+trascina:|r sposta il pulsante",
    ["Open Options"] = "Apri le opzioni",
    ["Show button on minimap"] = "Mostra il pulsante sulla minimappa",
    ["If off, the button is completely hidden."] = "Se disattivato, il pulsante è completamente nascosto.",
    ["Distance from center"] = "Distanza dal centro",
    ["Angle (degrees)"] = "Angolo (gradi)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Suggerimento: puoi spostare il pulsante anche direttamente sulla minimappa: tieni premuto Shift e trascinalo nella posizione desiderata.",
    ["Font Bars"] = "Caratteri delle barre",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Dimensioni ridotte del carattere per le barre di salute e mana di Giocatore/Bersaglio/Pet, con opzione per nascondere TargetFrameBackground.",
    ["Health Bar Text"] = "Testo della barra della salute",
    ["Font size on health bars (Player/Target/Pet)."] = "Dimensione del carattere sulle barre della salute (Giocatore/Bersaglio/Pet).",
    ["Power Bar Text"] = "Testo della barra della risorsa",
    ["Font size on mana/power bars."] = "Dimensione del carattere sulle barre di mana/risorsa.",
    ["Pet Combat Feedback Text"] = "Testo del feedback di combattimento del Pet",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Dimensione del carattere per “Danno”, “Schivata”, “Mancato” sul pet.",
    ["Only affect Player/Target/Pet bars"] = "Applica solo alle barre di Giocatore/Bersaglio/Pet",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Se disattivato: tutte le TextStatusBar dell'interfaccia vengono sovrascritte con le dimensioni sopra (può interferire con altri addon).",
    ["Hide TargetFrame background"] = "Nascondi lo sfondo del TargetFrame",
    ["Permanently hides the dark background element of the TargetFrame."] = "Nasconde permanentemente l'elemento scuro di sfondo del TargetFrame.",
    ["Target Frame"] = "Finestra del bersaglio",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaAggiunge alla finestra di bersaglio/focus le funzioni moderne che mancano all'interfaccia predefinita Anniversary: tutto estetico, senza corrompere il codice protetto.|r",
    ["Numeric threat %"] = "Minaccia numerica in %",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Mostra la tua percentuale di minaccia sul bersaglio (e sul focus) sopra la finestra, colorata in base allo stato della minaccia.",
    ["Threat glow"] = "Bagliore di minaccia",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Illumina la finestra del bersaglio (e del focus) in giallo/arancione/rosso al crescere della tua minaccia.",
    ["Rare-Elite border"] = "Bordo Raro-Elite",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Mostra il bordo argentato con drago alato dei Rari-Elite sui mob raro-elite.",
    ["Class icon on player targets"] = "Icona di classe sui bersagli giocatore",
    ["Shows the target's class crest on the frame when you target a player."] = "Mostra lo stemma di classe del bersaglio sulla finestra quando selezioni un giocatore.",
    ["Also apply to the Focus frame"] = "Applica anche alla finestra del focus",
    ["Health"] = "Salute",
    ["Show real NPC health"] = "Mostra la salute reale degli NPC",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Mostra il valore reale di salute sugli NPC invece della percentuale offuscata (i giocatori nemici restano in %).",
    ["Player Castbar"] = "Barra di lancio del giocatore",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Barra di lancio del giocatore con due modalità: Originale (barra Blizzard estesa) o Barra personalizzata (stile VUI).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DI LANCIO|r\\n|cffaaaaaaTrascina o frecce direzionali|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Posizione della barra di lancio: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffMind Flay|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Spostamento della barra di lancio attivo. |cff9b6cffTrascina il riquadro viola|r o usa le |cff9b6cfffrecce direzionali|r (SHIFT = 5px). Clicca di nuovo su “Sblocca / Prova” per terminare.",
    ["Castbar mover disabled."] = "Spostamento della barra di lancio disattivato.",
    ["Castbar Variant"] = "Variante della barra di lancio",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Passa tra Originale (barra Blizzard estesa) e Barra personalizzata (stile VUI con icona e nome dell'incantesimo sotto la barra).",
    ["Original (Blizzard bar extended)"] = "Originale (barra Blizzard estesa)",
    ["Custom Castbar (VUI style)"] = "Barra personalizzata (stile VUI)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Modalità della barra di lancio impostata su |cff9b6cffOriginale|r. |cffffff00/reload|r consigliato affinché la barra predefinita torni a funzionare normalmente.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Modalità della barra di lancio impostata su |cff9b6cffStile VUI|r.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaCambio di modalità: dopo il passaggio può essere necessario un /reload affinché la barra predefinita torni a funzionare normalmente.|r",
    ["Show spell name"] = "Mostra il nome dell'incantesimo",
    ["Show cast timer"] = "Mostra il timer di lancio",
    ["Show channel ticks"] = "Mostra i tick del channeling",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Mostra linee verticali nei punti di tick (Mind Flay, Drain Soul, Hellfire, ecc.)",
    ["Show clip window"] = "Mostra la finestra di clip",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Ombreggia la tua latenza alla fine della barra: sui channel il momento per rilanciare senza perdere l'ultimo tick, sui lanci la finestra di coda in cui il prossimo incantesimo può già essere premuto.",
    ["Timer format"] = "Formato del timer",
    ["Remaining / total (1.5 / 2.0)"] = "Rimanente / totale (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "Solo rimanente (1.5)",
    ["Whole seconds (2)"] = "Secondi interi (2)",
    ["Show pushback"] = "Mostra il pushback",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Mostra brevemente in rosso sopra la barra il tempo perso per il pushback.",
    ["Merge crafting casts"] = "Unisci i lanci di creazione",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "Quando crei più oggetti di seguito la barra mostra un contatore come 3/20 invece dei singoli lanci.",
    ["Fill color"] = "Colore di riempimento",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Texture della barra = la classica grafica gialla/verde. Il colore d'accento o quello di classe tingono invece una barra neutra.",
    ["Bar textures (yellow/green)"] = "Texture della barra (giallo/verde)",
    ["Accent color"] = "Colore d'accento",
    ["VUI Style: Position & Size"] = "Stile VUI: posizione e dimensione",
    ["Unlock / Test"] = "Sblocca / Prova",
    ["Center Position"] = "Posizione centrale",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaSuggerimento: tieni premuto |cffffffffSHIFT|r e trascina la barra di lancio con il tasto sinistro durante un lancio per spostarla. Oppure usa “Sblocca / Prova” per avere una barra di prova permanente da posizionare.|r",
    ["Show icon"] = "Mostra l'icona",
    ["Icon Size"] = "Dimensione dell'icona",
    ["Icon X Offset"] = "Scostamento X dell'icona",
    ["Icon Y Offset"] = "Scostamento Y dell'icona",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Sposta l'icona in orizzontale. Negativo = sinistra, positivo = destra.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Sposta l'icona in verticale. Positivo = su, negativo = giù.",
    ["Test only available in 'Custom Castbar' mode."] = "Prova disponibile solo in modalità “Barra personalizzata”.",
    ["Cooldown Pulse"] = "Impulso cooldown",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center (based on Doom_CooldownPulse)."] = "Mostra l'icona di un cooldown scaduto come breve animazione pulsante al centro dello schermo (basato su Doom_CooldownPulse).",
    ["Test Spell"] = "Incantesimo di prova",
    ["Cooldown Pulse position reset."] = "Posizione dell'impulso cooldown ripristinata.",
    ["Test Pulse"] = "Prova l'impulso",
    ["Plays a test animation."] = "Riproduce un'animazione di prova.",
    ["Reset Position"] = "Ripristina la posizione",
    ["Max Opacity"] = "Opacità massima",
    ["Animation Scale"] = "Scala dell'animazione",
    ["Fade-In Time (s)"] = "Tempo di dissolvenza in entrata (s)",
    ["Hold Time (s)"] = "Tempo di permanenza (s)",
    ["Fade-Out Time (s)"] = "Tempo di dissolvenza in uscita (s)",
    ["Show Before Available (s)"] = "Mostra prima della disponibilità (s)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Avvia l'animazione X secondi PRIMA che il cooldown finisca. 0 = esattamente alla fine del cooldown.",
    ["Spell Filter"] = "Filtro degli incantesimi",
    ["Show spell names"] = "Mostra i nomi degli incantesimi",
    ["Shows the name of the spell under the icon."] = "Mostra il nome dell'incantesimo sotto l'icona.",
    ["Invert filter (whitelist instead of blacklist)"] = "Inverti il filtro (whitelist invece di blacklist)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "Disattivato: la lista = incantesimi ignorati. Attivato: la lista = mostra SOLO questi incantesimi.",
    ["Spell List (comma-separated)"] = "Lista degli incantesimi (separati da virgola)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Nomi degli incantesimi esattamente come nel gioco, separati da virgola. Funzionano anche gli ID degli incantesimi.",
    ["Arena Frames"] = "Finestre arena",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Migliora le finestre dei nemici in arena: sposta/scala, colori di classe, icone di classe, cooldown del monile PvP, tracciamento DR, barra di lancio, disposizione con drag&drop.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555Errore del sottomodulo ArenaFrames:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555Errore OnEnable del sottomodulo Arena:|r %s",
    ["Layout"] = "Disposizione",
    ["Class Color"] = "Colore di classe",
    ["PvP Trinket"] = "Monile PvP",
    ["DR Tracker"] = "Tracciamento DR",
    ["Castbar"] = "Barra di lancio",
    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "Ripristina la posizione",
    ["Position reset."] = "Posizione ripristinata.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "In modalità sblocco appare un overlay viola sopra le finestre. Clic + trascina per spostare, rotella del mouse per scalare.",
    ["Layout (Order)"] = "Disposizione (ordine)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Ordine delle finestre arena. Usa su/giù per spostare gli slot 1-5.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  Slot arena %d",
