    ["Downward"] = "Verso il basso",
    ["Upward"] = "Verso l'alto",
    ["Reset order"] = "Ripristina l'ordine",
    ["Class Visuals"] = "Aspetto di classe",
    ["Class-colored health bars"] = "Barre della salute con colore di classe",
    ["Colors the health bar in the player's class color."] = "Colora la barra della salute con il colore di classe del giocatore.",
    ["Class-colored name"] = "Nome con colore di classe",
    ["Class icon instead of portrait"] = "Icona di classe al posto del ritratto",
    ["Replaces the 3D portrait with a class symbol."] = "Sostituisce il ritratto 3D con un simbolo di classe.",
    ["PvP Trinket Tracker"] = "Tracciamento del monile PvP",
    ["Show PvP trinket cooldown"] = "Mostra il cooldown del monile PvP",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Mostra un'icona con la spirale del cooldown accanto alla finestra arena quando l'avversario usa il suo monile PvP.",
    ["Icon size"] = "Dimensione dell'icona",
    ["Left of frame"] = "A sinistra della finestra",
    ["Right of frame"] = "A destra della finestra",
    ["Offset X"] = "Scostamento X",
    ["Offset Y"] = "Scostamento Y",
    ["Diminishing Returns Tracker"] = "Tracciamento delle riduzioni di efficacia (DR)",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Mostra accanto a ogni finestra arena le icone delle categorie DR attive (Stordimento, Paura, Polimorfia ecc.) con indicatore di colore: |cff00ff00verde|r = pieno, |cffffff00giallo|r = 1/2, |cffff8000arancione|r = 1/4, |cffff0000rosso|r = immune.",
    ["Enable DR tracking"] = "Attiva il tracciamento DR",
    ["INTERRUPTED"] = "INTERROTTO",
    ["Castbar for arena opponents"] = "Barra di lancio per gli avversari in arena",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Mostra una barra di lancio sotto la finestra quando l'avversario lancia o channella un incantesimo.",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Raccolta di semplici opzioni di comodità: accettazione automatica (missioni, resurrezione, evocazione), vendita automatica, riparazione, meno spam nell'interfaccia, dimensioni del testo.",
    ["Auto-sold: %d items, +%s"] = "Venduti automaticamente: %d oggetti, +%s",
    ["Auto-sold: %d items."] = "Venduti automaticamente: %d oggetti.",
    ["Repair exceeds gold (%d < %d)."] = "La riparazione supera l'oro disponibile (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Riparazione automatica (%do %da).",
    ["MAX"] = "MAX",
    ["General - Auto Actions"] = "Generale - Azioni automatiche",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaSemplici interruttori per le azioni di comodità più comuni. Hanno effetto subito, senza /reload.|r",
    ["Auto-accept quests"] = "Accetta automaticamente le missioni",
    ["Automatically accepts quests when clicking an NPC."] = "Accetta automaticamente le missioni quando clicchi su un NPC.",
    ["Auto-turn in quests"] = "Consegna automaticamente le missioni",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Completa automaticamente le missioni terminate. Attende la scelta dell'utente per le missioni con più ricompense (nessuna selezione automatica).",
    ["Auto-accept resurrect"] = "Accetta automaticamente la resurrezione",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Clicca automaticamente su “Accetta” nei popup di resurrezione (non in combattimento).",
    ["Auto-accept summon"] = "Accetta automaticamente l'evocazione",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Clicca automaticamente su “Accetta” nei popup di evocazione con stregone/pietra.",
    ["Auto-release spirit in PvP/Arena"] = "Rilascia automaticamente lo spirito in PvP/Arena",
    ["Releases instantly on death in BG or arena."] = "Rilascia subito alla morte in BG o in arena.",
    ["Auto-sell junk (grey)"] = "Vendi automaticamente le cianfrusaglie (grigie)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Vende tutti gli oggetti grigi all'apertura di un mercante. I guadagni sono mostrati in chat.",
    ["Auto-repair"] = "Riparazione automatica",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Ripara l'intero equipaggiamento dal mercante se l'oro è sufficiente.",
    ["Stack-split popup: MAX button"] = "Popup di divisione delle pile: pulsante MAX",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Aggiunge un pulsante “MAX” al popup della quantità. Clic = compra l'intera pila (dal mercante) o divide completamente (per gli oggetti nelle borse).",
    ["Stack-split popup: VuloUI look"] = "Popup di divisione delle pile: aspetto VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Ridisegna il popup della quantità (acquisto/divisione delle pile) per adattarlo all'aspetto dell'addon: pannello scuro, pulsanti e frecce puliti. Disattivarlo richiede un /reload.",
    ["Hide UI error messages"] = "Nascondi i messaggi di errore dell'interfaccia",
    ["Hides the red error messages in the screen center."] = "Nasconde i messaggi di errore rossi al centro dello schermo.",
    ["Hide zone text"] = "Nascondi il nome della zona",
    ["Hides the large zone name when entering new areas."] = "Nasconde il grande nome della zona quando entri in una nuova area.",
    ["Hide level numbers on portrait"] = "Nascondi il livello sul ritratto",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Nasconde l'indicazione del livello sul ritratto di Giocatore/Bersaglio/Pet.",
    ["Hide keybind text on action buttons"] = "Nascondi il testo dei tasti sui pulsanti d'azione",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Nasconde le piccole etichette dei tasti (1, F1, ecc.) sui pulsanti d'azione.",
    ["Hide macro/spell names on action buttons"] = "Nascondi i nomi di macro/incantesimi sui pulsanti d'azione",
    ["Hides the text labels under the action buttons."] = "Nasconde le etichette di testo sotto i pulsanti d'azione.",
    ["Hide stack/charge numbers on action buttons"] = "Nascondi i numeri di pila/cariche sui pulsanti d'azione",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Nasconde i piccoli riquadri con i numeri in alto a destra (pile di oggetti, cariche, secondi di cooldown per i CD lunghi).",
    ["Hide raid group labels"] = "Nascondi le etichette dei gruppi raid",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Nasconde le etichette “Gruppo 1”/“Gruppo 2” sopra le finestre raid compatte.",
    ["Mail Text Size"] = "Dimensione del testo della posta",
    ["Font size in mail body (opened + sent mail)."] = "Dimensione del carattere nel corpo della posta (posta aperta e inviata).",
    ["Quest Text Size"] = "Dimensione del testo delle missioni",
    ["Font size in quest descriptions + quest log."] = "Dimensione del carattere nelle descrizioni delle missioni e nel diario.",
    ["Book Text Size"] = "Dimensione del testo dei libri",
    ["Font size in readable books and letters from item text."] = "Dimensione del carattere nei libri leggibili e nelle lettere dal testo degli oggetti.",
    ["Queue Timer"] = "Timer della coda",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Mostra un conto alla rovescia sulla finestra di conferma della coda PvP/PvE. Avviso sonoro opzionale a 5 secondi.",
    ["Queue expires in"] = "La coda scade tra",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffQueueTimer:|r ",
    ["Dungeon queue popped instantly!"] = "Coda per il dungeon scattata subito!",
    ["Dungeon queue popped after %s"] = "Coda per il dungeon scattata dopo %s",
    ["Dungeon queue popped."] = "Coda per il dungeon scattata.",
    ["Queue popped instantly!"] = "Coda scattata subito!",
    ["Queue popped after %s"] = "Coda scattata dopo %s",
    ["Sound on queue pop"] = "Suono allo scattare della coda",
    ["Plays a sound as soon as the queue pops."] = "Riproduce un suono non appena la coda scatta.",
    ["5-second warning"] = "Avviso a 5 secondi",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Riproduce 3 suoni rapidi quando restano solo 5 secondi per accettare.",
    ["Hide other timers (e.g. BigWigs)"] = "Nascondi gli altri timer (es. BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Nasconde le StatusBar esterne sul popup di conferma LFG così che sia visibile solo il nostro timer.",
    ["Tooltip IDs"] = "ID nei tooltip",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Mostra SpellID, ItemID, ID degli NPC e molti altri ID nei tooltip (basato su idTip di silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffTalenti:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffiLvL:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(disattivato di default)|r",
    ["Shows %s in tooltips."] = "Mostra %s nei tooltip.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Mostra righe aggiuntive di ID nei tooltip, ad es. ID di incantesimi, oggetti o NPC.",
    ["Quick Select"] = "Selezione rapida",
    ["All on"] = "Attiva tutto",
    ["All off"] = "Disattiva tutto",
    ["Defaults"] = "Predefiniti",
    ["Player Tooltip (Inspect-based)"] = "Tooltip del giocatore (basato sull'ispezione)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaQuando passi il mouse su un giocatore, nel tooltip compaiono il suo livello oggetto medio e la distribuzione dei talenti (es. 14/0/47). I dati restano in cache 60s per giocatore, con limite di ispezione 1/s.|r",
    ["Show average iLvL"] = "Mostra l'iLvL medio",
    ["Show talent distribution (e.g. 14/0/47)"] = "Mostra la distribuzione dei talenti (es. 14/0/47)",
    ["ID Types"] = "Tipi di ID",
    ["Auto Item Buy"] = "Acquisto automatico di oggetti",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Compra automaticamente gli oggetti configurati dai mercanti configurati. Shift all'apertura della finestra del mercante = arresto d'emergenza.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "Acquisto: ",
    ["Close merchant window after purchase"] = "Chiudi la finestra del mercante dopo l'acquisto",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Chiude automaticamente la finestra del mercante circa 0,2s dopo l'acquisto.",
    ["Chat message on each purchase"] = "Messaggio in chat a ogni acquisto",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaSuggerimento: tieni premuto SHIFT all'apertura della finestra del mercante per saltare una volta l'acquisto automatico.|r",
    ["Add Vendor"] = "Aggiungi mercante",
    ["Vendor Name"] = "Nome del mercante",
    ["Add"] = "Aggiungi",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Inserisci il nome di un mercante.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555Il mercante “%s” esiste già.|r",
    ["Vendor '%s' added."] = "Mercante “%s” aggiunto.",
    ["Manage Vendors"] = "Gestisci i mercanti",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaNessun mercante ancora aggiunto. Aggiungi un mercante qui sopra, poi selezionalo qui per configurare gli oggetti.|r",
    ["Currently selected vendor"] = "Mercante attualmente selezionato",
    ["Delete this vendor"] = "Elimina questo mercante",
    ["Vendor '%s' removed."] = "Mercante “%s” rimosso.",
    ["Items at '%s'"] = "Oggetti presso “%s”",
    ["Item name (exactly as in-game)"] = "Nome oggetto (esattamente come in gioco)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Inserisci il nome di un oggetto.|r",
    ["Item '%s' added at vendor '%s'."] = "Oggetto '%s' aggiunto al mercante '%s'.",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaI nomi degli oggetti devono corrispondere esattamente al nome in gioco (comprese maiuscole e caratteri speciali).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaNessun oggetto configurato. Aggiungi sopra gli oggetti da acquistare automaticamente da questo mercante.|r",
    ["Remove"] = "Rimuovi",
    ["Item '%s' removed."] = "Oggetto '%s' rimosso.",
    ["Inspect Fix"] = "Fix Ispezione",
    ["Inspect state manually reset. Try again now."] = "Stato dell'ispezione azzerato manualmente. Riprova adesso.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r Stato dell'ispezione azzerato.",
    ["Auto-reset on timeout"] = "Reset automatico al timeout",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Se dopo X secondi il server non risponde, lo stato dell'ispezione in sospeso viene azzerato automaticamente, così il tentativo successivo funziona di nuovo.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Quanto attendere INSPECT_READY prima che scatti il reset automatico. 5 secondi è il nuovo valore predefinito per Anniversary: abbastanza rapido per recuperare in fretta.",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaComandi: /inspectreset (reset forzato), /inspectstate (info di debug in chat)|r",
    ["Timeout (seconds)"] = "Timeout (secondi)",
    ["Manual Reset"] = "Reset manuale",
    ["Reset inspect state now"] = "Azzera ora lo stato dell'ispezione",
    ["Inspect state manually reset."] = "Stato dell'ispezione azzerato manualmente.",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "Hook NotifyInspect: %s\\nHook InspectFrame: %s",
    ["|cff66ff66active|r"] = "|cff66ff66attivo|r",
    ["|cffff8800waiting|r"] = "|cffff8800in attesa|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800in attesa di Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaCosa fa la correzione: traccia le ispezioni attive con un timestamp, ridisegna i dati degli oggetti che arrivano in ritardo, richiede una seconda volta un'ispezione del tutto vuota e chiama ClearInspectPlayer() alla chiusura e al timeout. Evita che uno stato bloccato impedisca tutte le ispezioni successive.|r",
    ["Auto-retry empty inspects"] = "Ripeti automaticamente le ispezioni vuote",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "Dopo la risposta del server, gli slot degli oggetti vengono ridisegnati poco dopo (i dati arrivano spesso in ritardo). Se la finestra è ancora del tutto vuota, l'ispezione viene richiesta automaticamente un'altra volta.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaStato: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Hook attivo|r",
    ["LFG Browse Nil Fix"] = "Fix nil per la ricerca LFG",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Intercetta gli errori Lua nel Cerca Gruppo di Anniversary (LFGBrowseSearchEntry_Update con resultID obsoleti). Evita lo spam in chat e le liste di ricerca rotte.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Errore di ricerca LFG di Blizzard intercettato (voce obsoleta ignorata).",
    ["Chat message on first error"] = "Messaggio in chat al primo errore",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Mostra in chat un breve messaggio una volta per sessione quando viene intercettato un errore di ricerca LFG.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Questa correzione racchiude la funzione |cffffffffLFGBrowseSearchEntry_Update|r di Blizzard in una chiamata protetta (xpcall). Quando la voce va in errore per un resultID obsoleto (“searchResultInfo nil”), l'errore viene ignorato: il successivo aggiornamento di Blizzard ripulisce automaticamente la voce dell'elenco.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "in attesa di Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "Fix nil per le notizie di gilda",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Intercetta gli errori Lua nelle voci delle notizie di gilda (di solito “formatString” o “GuildUtil”) e sostituisce le voci danneggiate con un testo di riserva invece di far saltare l'intero pannello.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Voce delle notizie di gilda non valida|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Errore delle notizie di gilda di Blizzard intercettato (testo di riserva applicato).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Mostra in chat un breve messaggio una volta per sessione quando viene intercettato un errore delle notizie di gilda.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Questa correzione racchiude la funzione |cffffffffGuildNewsButton_SetNews|r di Blizzard in una chiamata protetta (xpcall). Quando una voce genera un errore noto (“formatString” o “GuildUtil”), viene sostituita con il testo di riserva “Voce delle notizie di gilda non valida”: il pannello resta utilizzabile.",
    ["waiting for Blizzard_Communities"] = "in attesa di Blizzard_Communities",
    ["Auction Price Fix"] = "Fix prezzi casa d'aste",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Corregge un errore nil nell'interfaccia della casa d'aste tedesca (PriceDropdown non definito).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Questa correzione risolve un bug noto della localizzazione tedesca di WoW: l'interfaccia della casa d'aste fa riferimento a un elemento “PriceDropdown” mai definito, che provoca errori Lua all'apertura della casa d'aste.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaLingua attuale: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaLa correzione si applica solo ai client tedeschi (deDE). Nelle altre lingue il modulo è inattivo.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66applicata|r",
