    ["Show spell icons"] = "Mostra le icone degli incantesimi",
    ["Party member died"] = "Membro del gruppo morto",
    ["%s died"] = "%s è morto",
    ["Shows the spell icon inline next to the spell name."] = "Mostra l'icona dell'incantesimo accanto al suo nome.",
    ["Parried"] = "Parato",
    ["Dodged"] = "Schivato",
    ["Missed"] = "Mancato",
    ["Blocked"] = "Bloccato",
    ["Absorbed"] = "Assorbito",
    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffffTESTO DI COMBATTIMENTO|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "Notifiche di combattimento lampeggianti (con anteprima dal vivo) più un motore di testo scorrevole per il registro di combattimento.",
    ["Show Preview"] = "Mostra anteprima",
    ["Text"] = "Testo",
    ["Thick Outline"] = "Contorno spesso",
    ["Also apply font to Blizzard mob FCT"] = "Applica il font anche all'FCT sui mob di Blizzard",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Imposta inoltre DAMAGE_TEXT_FONT a livello globale: cambia il font dei numeri di danno sopra mob e famigli. Richiede /reload per avere effetto.",
    ["Interrupted"] = "Interrotto",
    ["Parried/Dodged/Missed"] = "Parato/Schivato/Mancato",
    ["Engine FCT (above mob/pet)"] = "FCT del motore (sopra mob/famiglio)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "Font più nitido per gli indicatori dei colpi (Friz Quadrata)",
    ["Engine FCT Scale"] = "Scala dell'FCT del motore",
    ["Damage numbers above mob/pet — bitmap scaling."] = "Numeri di danno sopra mob e famigli: scalatura bitmap.",
    ["Center"] = "Centra",
    ["Unlock / Position"] = "Sblocca / Posiziona",
    ["Trinkets"] = "Monili",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Due slot per monili sullo schermo con cooldown, selezione a tendina e coda automatica.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaDue slot per monili con cooldown, selezione a tendina e coda automatica.|nClic sinistro = usa, clic destro = menu a tendina.|r",
    ["Show frame"] = "Mostra il riquadro",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Nasconde o mostra i due slot dei monili. La coda automatica continua a funzionare anche quando sono nascosti.",
    ["Position locked"] = "Posizione bloccata",
    ["If on, the frame cannot be accidentally moved."] = "Se attivo, il riquadro non può essere spostato per sbaglio.",
    ["Size"] = "Dimensione",
    ["Scales the trinket slots."] = "Ridimensiona gli slot dei monili.",
    ["Character Panel"] = "Pannello del personaggio",
    ["Dark Skin"] = "Skin scura",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "L'aspetto scuro dell'interfaccia in un unico posto: una skin scura integrata per i pulsanti d'azione e le icone di WeakAuras, più una Modalità Scura opzionale che scurisce i riquadri predefiniti di Blizzard, la minimappa e le barre.",
    ["The dark action-bar button skin."] = "La skin scura dei pulsanti della barra delle azioni.",
    ["Enable Dark Mode"] = "Attiva la Modalità Scura",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Ricolora in tonalità scura i riquadri predefiniti di Blizzard, la minimappa e la grafica della barra delle azioni. Disattivata per impostazione predefinita.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaOpzionale: scurisce e desatura la grafica predefinita di Blizzard — riquadri unità, minimappa e barre delle azioni — verso una tonalità scura neutra. Reversibile: disattivala e torna l'aspetto dorato.|r",
    ["Action Bars"] = "Barre delle azioni",
    ["Skin the action bars"] = "Applica la skin alle barre delle azioni",
    ["Bar style"] = "Stile della barra",
    ["Bar icon size"] = "Dimensione delle icone della barra",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "Quanta parte del pulsante occupa l'icona nello stile Ombra. Più alto = icone più grandi con bordo più sottile.",
    ["WeakAuras Icons"] = "Icone di WeakAuras",
    ["Skin WeakAuras icons"] = "Applica la skin alle icone di WeakAuras",
    ["WeakAuras style"] = "Stile WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Stile delle icone di WeakAuras, indipendente dalle barre delle azioni.",
    ["Hide WeakAuras' own border"] = "Nascondi il bordo proprio di WeakAuras",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Nasconde il bordo chiaro che WeakAuras disegna sulle icone, così resta visibile solo il nostro bordo scuro. Usa /reload per ripristinarlo del tutto.",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "Scegli l'aspetto dei pulsanti d'azione. Arrotondato/Cerchio usano una maschera sull'icona; Minimale è solo l'icona ritagliata.",
    ["Shadow (dark rounded rim)"] = "Ombra (bordo scuro arrotondato)",
    ["Rounded icon (masked corners)"] = "Icona arrotondata (angoli mascherati)",
    ["Square (black edge)"] = "Quadrato (bordo nero)",
    ["Square (accent edge)"] = "Quadrato (bordo con colore d'accento)",
    ["Circle"] = "Cerchio",
    ["Minimal (icon only)"] = "Minimale (solo icona)",
    ["Minimal Dark (darkened Blizzard border)"] = "Minimale scuro (bordo Blizzard scurito)",
    ["Also skin pet & stance buttons"] = "Applica la skin anche ai pulsanti del famiglio e delle posture",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Migliora il pannello del personaggio: iLvL per slot, visualizzazione dei socket, testo degli incantamenti abbreviato.",
    ["Show item level per slot"] = "Mostra il livello oggetto per slot",
    ["Show average item level"] = "Mostra il livello oggetto medio",
    ["Show sockets"] = "Mostra i socket",
    ["Shorten enchant text (DE/EN)"] = "Abbrevia il testo degli incantamenti (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Esempio: 'Stamina' → 'Stam', 'Ausdauer' → 'Ausd'.",
    ["Treat rings as enchantable"] = "Considera gli anelli incantabili",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "Mostra il testo dell'incantamento anche sugli anelli (in TBC alcune professioni possono incantare gli anelli). Richiede /reload.",
    ["Text Size"] = "Dimensione del testo",
    ["Item Level Text Size"] = "Dimensione del testo del livello oggetto",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Dimensione del carattere del livello oggetto su ogni slot. Ha effetto immediato con il pannello del personaggio aperto.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Nota: alcune modifiche hanno pieno effetto solo dopo un /reload, perché il pannello del personaggio viene agganciato al caricamento.",
    ["|cffff0000No Ench|r"] = "|cffff0000No ench|r",
    ["|c%siLvL - %d|r"] = "|c%siLvL - %d|r",
    ["Gold Tracker"] = "Contatore dell'oro",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Mostra nel tooltip dell'oro dello zaino quanto oro è stato guadagnato o speso dall'ultimo azzeramento. Salvato per personaggio.",
    ["Gold Tracker reset|r. Start = "] = "Contatore dell'oro azzerato|r. Inizio = ",
    ["Gold Balance|r"] = "Bilancio dell'oro|r",
    ["Gained:|r"] = "Guadagnato:|r",
    ["Spent:|r"] = "Speso:|r",
    ["|cffffffffNet:|r"] = "|cffffffffNetto:|r",
    ["Start:|r"] = "Inizio:|r",
    ["Now:|r"] = "Adesso:|r",
    ["Reset with /vcui goldreset|r"] = "Azzera con /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaMostra nel tooltip dell'oro dello zaino il bilancio dall'ultimo azzeramento manuale:|n  - |cff44ff44Guadagnato|r (missioni, loot, vendite ai mercanti, posta)|n  - |cffff4444Speso|r (riparazioni, acquisti dai mercanti, spese postali)|n  - |cffffffffNetto|r (+/- dall'azzeramento)|n|nI valori sono |cffffffffsalvati per personaggio|r attraverso /reload e disconnessione.|nL'oro ricevuto offline (posta della casa d'aste, scambi) non viene conteggiato.|n|nAzzeramento: pulsante qui sotto oppure |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Azzera la sessione",
    ["Class Specific"] = "Specifico per classe",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaContatore di mana di Tocco Vampirico: mostra in tempo reale quanto mana hai dato al gruppo (5% per tick del danno Ombra, per ogni utilizzatore di mana).|n|cffffffffAzzerato automaticamente all'inizio del combattimento.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Questi strumenti sono attivi solo giocando un Sacerdote.|r",
    ["No tools yet"] = "Ancora nessuno strumento",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaNessuno strumento specifico per questa classe, per ora. Hai un'idea? Fammelo sapere!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffMana VT:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffMana VT:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "Tocco Vampirico: %d mana dati al gruppo.",
    ["|cffffffffVT MANA|r"] = "|cffffffffMANA VT|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "Riquadro mana VT: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Spostamento del mana VT attivo. |cff9b6cffTrascina|r o usa le |cff9b6cfffrecce|r (SHIFT = 5px).",
    ["VT mana mover disabled."] = "Spostamento del mana VT disattivato.",
    ["Print to chat at combat end"] = "Scrivi in chat a fine combattimento",
    ["Writes a summary in chat after each fight."] = "Scrive un riepilogo in chat dopo ogni combattimento.",
    ["Reset manually"] = "Azzera manualmente",
    ["VT mana reset."] = "Mana VT azzerato.",
    ["Bars"] = "Barre",
    ["Icons"] = "Icone",
    ["Shadow Word: Pain"] = "Parola d'Ombra: Dolore",
    ["Vampiric Touch"] = "Tocco Vampirico",
    ["Devouring Plague"] = "Peste Divorante",
    ["Warning (seconds left)"] = "Avviso (secondi rimanenti)",
    ["Bar width"] = "Larghezza barra",
    ["Bar height"] = "Altezza barra",
    ["Spacing"] = "Spaziatura",
    ["Color the timer text"] = "Colora il testo del timer",
    ["Show recast gain %"] = "Mostra il guadagno del rilancio in %",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Mostra quanto colpirebbe più forte un lancio nuovo adesso (es. +12% con un proc di potere magico attivo). I valori negativi indicano che il DoT attivo ha fatto snapshot più forte: conservalo.",
    ["DoT Tracker"] = "Tracciatore di DoT",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaTraccia i tuoi DoT sul bersaglio. |cff44ff44Verde|r = è attivo un buff che li fa colpire più forte se li rilanci adesso (snapshot di TBC); |cffff4444rosso|r = in scadenza.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Attivo solo giocando un %s.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaTraccia i tuoi DoT da Stregone (Corruzione, Maledizione dell'Agonia, Afflizione Instabile, Sifone Vitale, Immolazione, Maledizione del Fato) sul bersaglio, con la stessa lettura dello snapshot di rilancio del tracciatore del Sacerdote.|r",
    ["Corruption"] = "Corruzione",
    ["Curse of Agony"] = "Maledizione dell'Agonia",
    ["Unstable Affliction"] = "Afflizione Instabile",
    ["Siphon Life"] = "Sifone Vitale",
    ["Immolate"] = "Immolazione",
    ["Curse of Doom"] = "Maledizione del Fato",
    ["|cffffffffDOTS|r"] = "|cffffffffDOT|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "DoT Ombra: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Spostamento dei DoT Ombra attivo. |cff9b6cffTrascina|r o usa le |cff9b6cfffrecce|r (SHIFT = 5px).",
    ["Shadow DoTs mover disabled."] = "Spostamento dei DoT Ombra disattivato.",
    ["Mark empty sockets"] = "Evidenzia i socket vuoti",
    ["Adds a red ring around item sockets that have no gem."] = "Aggiunge un anello rosso attorno ai socket dell'oggetto senza gemma.",
    ["Text shadow (instead of outline)"] = "Ombra del testo (invece del contorno)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Testo più pulito con un'ombra al posto di un contorno spesso.",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaUna minimappa rotonda moderna con anello smussato, nome della zona e orologio in una pillola sottile. Zoom con la rotellina del mouse. |cffffffffShift+trascina la mappa|r per spostarla, oppure usa Sblocca / la modalità Modifica dell'addon (/vedit). La modalità Modifica di Blizzard non gestisce questa mappa.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffMINIMAPPA|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Minimappa: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Spostamento della minimappa attivo. |cff9b6cffTrascina|r o usa le |cff9b6cfffrecce|r (SHIFT = 5px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Modulo minimappa disattivato: /reload ripristina completamente la disposizione predefinita.",
    ["Minimap ping: %s"] = "Ping sulla minimappa: %s",
    ["Shape"] = "Forma",
    ["Round"] = "Rotonda",
    ["Accent ring"] = "Anello d'accento",
    ["Ring color"] = "Colore dell'anello",
    ["Accent (purple)"] = "Accento (viola)",
    ["Class color"] = "Colore della classe",
    ["Custom color"] = "Colore personalizzato",
    ["Theme color"] = "Colore del tema",
    ["Dark guild & communities window"] = "Finestra scura di gilda e comunità",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Applica alle finestre di gilda e comunità lo stesso aspetto scuro. Per disattivarlo serve un /reload.",
    ["Debuffs on target (yours only)"] = "Debuff sul bersaglio (solo i tuoi)",
    ["Missing buffs (reminder)"] = "Buff mancanti (promemoria)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaLe icone compaiono mentre il TUO debuff/DoT è sul bersaglio, con il tempo rimanente. Aggiungi il debuff per nome o ID.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaLe icone compaiono mentre il buff ti MANCA: un promemoria per oli per armi, benedizioni e buff del cibo. Aggiungi il buff per nome o ID.|r",
    ["Tint blue when out of mana"] = "Colora di blu quando manca il mana",
    ["Tint red when out of range"] = "Colora di rosso quando è fuori portata",
    ["Needs a target; uses the spell's own range."] = "Richiede un bersaglio; usa la portata dell'incantesimo stesso.",
    ["Auto-track equipped trinkets"] = "Traccia automaticamente i monili equipaggiati",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Mantiene automaticamente entrambi i monili equipaggiati in questo gruppo: si aggiornano quando cambi monile.",
    ["(copy)"] = "(copia)",
    ["Show tooltips on hover"] = "Mostra i tooltip al passaggio del mouse",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Le icone intercettano così il mouse: lascialo disattivato se la barra si trova sopra elementi cliccabili dell'interfaccia.",
    ["Copy the link with Ctrl+C:"] = "Copia il link con Ctrl+C:",
    ["Click: copy link"] = "Clic: copia il link",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaColora nella tinta che preferisci tutto ciò che oggi è viola: barra laterale, bordi, evidenziazioni, barre. Un /reload lo applica ovunque.|r",
    ["Preset"] = "Preimpostazione",
    ["Purple (default)"] = "Viola (predefinito)",
    ["Turquoise"] = "Turchese",
    ["Pink"] = "Rosa",
    ["Orange"] = "Arancione",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Colore del tema cambiato. /reload lo applica a tutto (gli elementi già disegnati mantengono il vecchio colore fino ad allora).",
    ["Custom ring color"] = "Colore personalizzato dell'anello",
    ["A thin colored line around the dark ring (round shape only)."] = "Una linea sottile colorata attorno all'anello scuro (solo forma rotonda).",
    ["Zone panel"] = "Pannello della zona",
    ["Zone text and clock"] = "Nome della zona e orologio",
    ["Above the map"] = "Sopra la mappa",
    ["Below the map"] = "Sotto la mappa",
    ["Hidden"] = "Nascosto",
    ["Show clock"] = "Mostra l'orologio",
    ["Show date"] = "Mostra la data",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Mostra la data accanto all'orologio. Cliccala per aprire il calendario.",
    ["Buttons"] = "Pulsanti",
    ["Zoom buttons (+/-)"] = "Pulsanti di zoom (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Mostra un + e un - piatti sul bordo destro della mappa. Anche la rotellina del mouse esegue sempre lo zoom.",
    ["Show day/night button"] = "Mostra il pulsante giorno/notte",
    ["Restyle addon buttons"] = "Ridisegna i pulsanti degli addon",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Rimuove i bordi dorati dai pulsanti sulla minimappa degli altri addon e dà loro un aspetto rotondo e pulito. Per disattivarlo serve un /reload.",
    ["Addon buttons only on mouseover"] = "Pulsanti degli addon solo al passaggio del mouse",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Nasconde i pulsanti sulla minimappa degli altri addon finché il mouse non è sopra la minimappa.",
    ["Ping in chat"] = "Ping in chat",
    ["Prints who pinged the minimap."] = "Scrive chi ha pingato la minimappa.",
    ["Totem Bar"] = "Barra dei totem",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffClic sinistro|r su un'icona per (ri)lanciare il totem di quell'elemento, |cffffffffpassa il mouse|r su uno slot per scegliere il totem dall'elenco di icone, |cffffffffclic centrale|r per richiamare tutti i totem. Il bordo dell'icona diventa rosso poco prima che il totem scada.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Attivo solo giocando uno Sciamano.|r",
    ["Totem set"] = "Set di totem",
    ["Active set"] = "Set attivo",
    ["Set name"] = "Nome del set",
    ["New set"] = "Nuovo set",
    ["Delete set"] = "Elimina il set",
    ["Shown elements"] = "Elementi mostrati",
    ["Sound before a totem expires"] = "Suono prima della scadenza di un totem",
    ["Icon border (action-bar style)"] = "Bordo dell'icona (stile barra delle azioni)",
    ["Style"] = "Stile",
    ["VuloUI (dark)"] = "VuloUI (scuro)",
    ["Classic (metal)"] = "Classic (metallo)",
    ["Flyout direction"] = "Direzione del menu a comparsa",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "Da che parte si apre il selettore dei totem quando passi il mouse su uno slot. Automatico sceglie il lato lontano dal bordo dello schermo.",
    ["Automatic"] = "Automatico",
    ["Upwards"] = "Verso l'alto",
    ["Downwards"] = "Verso il basso",
    ["To the left"] = "Verso sinistra",
    ["To the right"] = "Verso destra",
    ["Open flyout in combat"] = "Apri il menu a comparsa in combattimento",
    ["Tooltip with cooldown on hover"] = "Tooltip con cooldown al passaggio del mouse",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Passando il mouse su uno slot totem o su un'icona del selettore compaiono il nome del totem e il cooldown rimanente.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Disattivato = passare il mouse su uno slot non apre mai il selettore dei totem mentre combatti (i clic lanciano comunque). Il selettore ora si chiude anche quando il mouse esce e dopo ogni lancio, pure in combattimento.",
    ["Earth"] = "Terra",
    ["Water"] = "Acqua",
    ["|cffffffffTOTEMS|r"] = "|cffffffffTOTEM|r",
    ["Totems: x=%.0f, y=%.0f"] = "Totem: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Spostamento del timer dei totem attivo. |cff9b6cffTrascina|r o usa le |cff9b6cfffrecce|r (SHIFT = 5px).",
    ["Totem timer mover disabled."] = "Spostamento del timer dei totem disattivato.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Errore dello strumento di classe:|r %s",
    ["EDIT MODE"] = "MODALITÀ MODIFICA",
    ["Edit Mode"] = "Modalità Modifica",
    ["Open Edit Mode"] = "Apri la modalità Modifica",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Chiude la modalità Modifica e blocca tutte le finestre. Le modifiche restano applicate.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Mantiene la disposizione attuale e continua la modifica. Annulla riporterà a questo punto invece che all'aspetto di quando è stata aperta la modalità Modifica.",
    ["Window positions saved."] = "Posizioni delle finestre salvate.",
    ["Exit"] = "Esci",
    ["Close"] = "Chiudi",
    ["Reset"] = "Ripristina",
    ["Reset this frame"] = "Ripristina questo riquadro",
    ["Reset all VuloUI window positions to the screen centre."] = "Riporta al centro dello schermo tutte le posizioni delle finestre di VuloUI.",
    ["Reset all VuloUI window positions to the screen centre?"] = "Riportare al centro dello schermo tutte le posizioni delle finestre di VuloUI?",
    ["Done — lock everything"] = "Fatto: blocca tutto",
    ["Grid"] = "Griglia",
    ["Snap"] = "Aggancia",
    ["Show an alignment grid."] = "Mostra una griglia di allineamento.",
    ["Snap windows to the grid while dragging."] = "Aggancia le finestre alla griglia durante il trascinamento.",
    ["%d frames here - hold Alt to cycle"] = "%d riquadri qui: tieni premuto Alt per scorrerli",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "A quale punto dello schermo è ancorato il riquadro (lo mantiene in posizione al cambio di risoluzione).",
    ["ANCHOR"] = "ANCORAGGIO",
    ["POSITION"] = "POSIZIONE",
    ["SCALE"] = "SCALA",
    ["FREE MOVE"] = "SPOSTAMENTO LIBERO",
    ["FOLLOW WINDOW"] = "SEGUI FINESTRA",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Ancora questa finestra a un'altra: si sposterà insieme a essa ogni volta che quella viene mossa. Trascinando questa finestra l'ancoraggio resta e viene solo aggiornata la distanza.",
    ["Not possible - that would create a loop."] = "Non è possibile: si creerebbe un ciclo.",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "Reimpostare TUTTE le impostazioni di VuloClassicUI per ogni personaggio di questo account? L'operazione non può essere annullata.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Swing Timer disattivato: registra solo gli attacchi automatici in mischia, che i talenti di questo personaggio non usano.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Migrazione delle impostazioni %s non riuscita:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Riproduce un suono di avviso incursione appena un avversario usa il suo monile PvP.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Fa lampeggiare brevemente l’icona quando un avversario usa il suo monile PvP.",
    ["Icon gap"] = "Distanza icona",
    ["Distance between the icon and the bar."] = "Distanza tra l’icona e la barra.",
    ["Accent colour"] = "Colore d’accento",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Usato per la barra quando la modalità di riempimento non è una texture, e per le magie incanalate sulla barra di Blizzard.",
    ["Cast finished"] = "Magia completata",
    ["The bar flashes in this colour when a cast completes."] = "La barra lampeggia in questo colore quando una magia si completa.",
    ["Cast interrupted"] = "Magia interrotta",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "La barra lampeggia in questo colore quando una magia viene interrotta o fallisce.",
    ["Fade-in time"] = "Tempo di comparsa",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Quanto tempo impiega un’icona ad apparire. 0 la mostra subito.",
    [" and %d item(s)"] = " e %d oggetto/i",
    ["/vlfg toggles the group board."] = "/vlfg apre o chiude la bacheca dei gruppi.",
    ["Auto-apply a lure when the pole has none"] = "Applica automaticamente un’esca se la canna non ne ha",
    ["Auto-equip a fishing pole if none is worn"] = "Equipaggia automaticamente una canna da pesca se non ne indossi una",
    ["Auto-loot while fishing"] = "Raccolta automatica mentre peschi",
    ["Bags are full — some items were left in the mail."] = "Borse piene — alcuni oggetti sono rimasti nella posta.",
    ["Boost fishing sound (hear the bite clearly)"] = "Aumenta il suono della pesca (senti bene l’abboccata)",
    ["Burning Crusade Dungeons"] = "Spedizioni di Burning Crusade",
    ["Burning Crusade Raids"] = "Incursioni di Burning Crusade",
    ["Can't change the fishing key in combat."] = "Non puoi cambiare il tasto della pesca in combattimento.",
    ["Classic Dungeons"] = "Spedizioni di Classic",
    ["Classic Raids"] = "Incursioni di Classic",
    ["Clear key"] = "Cancella tasto",
    ["Extra items & macros"] = "Oggetti e macro aggiuntivi",
    ["Fishing key cleared."] = "Tasto della pesca cancellato.",
    ["Fishing key set to: %s"] = "Tasto della pesca impostato su: %s",
    ["Fishing key: %s  —  click to change"] = "Tasto della pesca: %s  —  clicca per cambiarlo",
    ["Fishing sound volume"] = "Volume del suono della pesca",
    ["Friends"] = "Amici",
    ["Guild"] = "Gilda",
    ["H"] = "H",
    ["Hide the reel error spam while fishing"] = "Nascondi gli errori di recupero mentre peschi",
    ["In Progress"] = "In corso",
    ["Invite"] = "Invita",
    ["Keep requests for (minutes)"] = "Conserva le richieste per (minuti)",
    ["Keep sound audible when the game is in the background"] = "Mantieni l’audio quando il gioco è in secondo piano",
    ["Keep this many bag slots free"] = "Lascia liberi questi spazi nelle borse",
    ["Mail emptied: looted %s%s."] = "Posta svuotata: raccolto %s%s.",
    ["No contacts yet"] = "Ancora nessun contatto",
    ["No groups forming right now."] = "Al momento nessuno sta formando un gruppo.",
    ["One-key reel (soft-target interact)"] = "Recupero con un tasto (interazione bersaglio morbido)",
    ["Open All"] = "Apri tutto",
    ["Press the key for fishing  (ESC to cancel)"] = "Premi il tasto per la pesca  (ESC per annullare)",
    ["Print a looted summary"] = "Stampa un riepilogo del bottino",
    ["Recently mailed"] = "Inviati di recente",
    ["Recipient dropdown on the Send tab"] = "Menu dei destinatari nella scheda Invia",
    ["Scan guild chat"] = "Analizza la chat di gilda",
    ["Scan say / yell"] = "Analizza dire e urlare",
    ["Scan world / trade / LFG channels"] = "Analizza i canali mondo, commercio e cerca gruppo",
    ["Set fishing key"] = "Imposta il tasto della pesca",
    ["Slot %d"] = "Spazio %d",
    ["Speed (seconds between actions)"] = "Velocità (secondi tra le azioni)",
    ["Take item attachments"] = "Prendi gli oggetti allegati",
    ["Take money"] = "Prendi il denaro",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Finché il galleggiante è in acqua, il volume degli effetti e quello generale vanno al massimo e musica e ambiente si abbassano, così senti bene il tonfo. Ripristinato quando recuperi.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Finché il galleggiante è in acqua, lo stesso tasto interagisce con esso per recuperare. Richiede l’interazione bersaglio morbido, attivata solo durante la pesca e ripristinata dopo.",
    ["Whisper"] = "Sussurra",
    ["Who"] = "Chi",
    ["Your characters"] = "I tuoi personaggi",
    ["now"] = "ora",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaAggiunge un pulsante «Apri tutto» alla cassetta postale. Prende tutti gli allegati e il denaro, saltando i contrassegni e la posta dei MG. Maiusc+clic sul pulsante per ignorare i filtri e prendere tutto.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaOggetti o macro usati dal tasto anche durante la pesca — solo quando sono pronti (fuori recupero, beneficio assente, condizioni soddisfatte), poi si torna a lanciare. Scrivi il nome o l’ID di un oggetto, Maiusc+clic per inserirne uno, o incolla una /macro.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaUn tasto fa tutto: lancia, recupera e applica l’esca — poi raccoglie da solo. Imposta un tasto qui sotto, guarda verso l’acqua e premilo.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Errore OnDisable del sottomodulo Arena:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Lingue",
    ["Reminders (new module)"] = "Promemoria (nuovo modulo)",
    ["Arena"] = "Arena",
    ["Totems"] = "Totem",
    ["Fixes"] = "Correzioni",
    ["Resource Bar"] = "Barra delle risorse",
    ["Settings Window"] = "Finestra delle impostazioni",
    ["Character Window"] = "Finestra del personaggio",
    ["Nameplates (German: Namensplaketten)"] = "Nameplate (in tedesco: Namensplaketten)",
    ["German client"] = "Client tedesco",
    ["Performance"] = "Prestazioni",
    ["Equipment Sets"] = "Set di equipaggiamento",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Spagnolo, francese, italiano, portoghese, russo e coreano. Tutte e sei le lingue sono complete — ognuno dei 2244 testi è tradotto, niente ricade sull'inglese. Lo spagnolo copre anche i client latinoamericani. Scegli la tua lingua in Generale, oppure lasciala su Auto.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Mostra cosa ti manca prima di un pull: oli e pietre per le armi, benedizioni, buff di cibo e flask, l'aura o la postura che hai dimenticato di attivare. Clicca un promemoria per lanciarlo o usarlo. Disattivato per impostazione predefinita, si trova sotto Comodità.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Una scintilla nel punto di riempimento della barra, angoli arrotondati, righe di aure assegnabili liberamente e i tuoi effetti di danno nel tempo su una riga tutta loro.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "I bordi delle aure prendono il colore della loro scuola di magia, e un'aura lampeggia poco prima di esaurirsi.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Testo del livello e dell'élite, più scala generale e scostamento verticale per ogni nameplate.",
    ["A window can take its width or height from another window and keep it."] = "Una finestra può prendere la larghezza o l'altezza da un'altra finestra e mantenerla.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Pulsante Salva. Mentre trascini, tieni premuto Shift per bloccare un asse.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Cooldown di monili e abilità razziali, timer della Vista dell'Ombra, un anello sull'icona di classe per l'aura più importante e controllo della distanza.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Le icone dei totem diventano grigie quando esci dal raggio del totem e riprendono colore quando torni.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "La scheda del personaggio e il libro degli incantesimi si aprono di nuovo in combattimento. Le barre delle azioni non impostano più un campo protetto dal nostro codice, che era la vera causa.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "Lo swing timer in mischia è disattivato per impostazione predefinita e si carica solo per classi e specializzazioni da mischia.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "I cursori hanno ricevuto un aspetto curato: bordi morbidi, un'ombra interna e un hover più fluido.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Icone proprie per le tre pagine delle collezioni e icone di classe sulle schede delle classi.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Ancora una finestra al bordo di un'altra (sinistra/destra/alto/basso) — la distanza è mantenuta da bordo a bordo, così sopravvive al ridimensionamento di una delle due finestre.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Ancoraggio con un clic: premi “Ancora alla finestra...” nel pannello di una finestra, poi clicca la finestra di destinazione. Cicli e auto-ancoraggio sono bloccati.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Mentre trascini, le linee di allineamento ora mostrano anche la distanza in pixel dalla finestra con cui ti allinei.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Pulsante Abbandona — fotografa il layout all'apertura della modalità Modifica e lo ripristina (posizioni, scala, ancoraggi e collegamenti) se abbandoni le modifiche.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "L'area di trascinamento ora copre l'intero pannello scuro della chat fino alla casella di scrittura, non solo la stretta striscia dei messaggi.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Corretto il clic destro sulla finestra della chat che non apriva il suo pannello delle impostazioni nella modalità Modifica.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Aiuto per gli interrupt sulla barra di lancio: colori propri mentre il tuo interrupt è in cooldown o pronto, una tacca che segna dove tornerà disponibile a metà lancio, uno scudo sui lanci non interrompibili e un lampo di interruzione che può mostrare chi ha messo a segno il kick.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Suite della barra di lancio: lato e scala dell'icona, tempo rimanente, sfondo proprio, colore di incanalamento, un colore di avviso quando il lancio è diretto a TE — e sul tuo bersaglio la barra di lancio si allinea a filo con la barra della salute, bordo compreso.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Linea di esecuzione, effetti per bersaglio e mouseover, sezione per il controllo di massa, forme e posizionamento dei punti combo, controlli di posizione, dimensione e dimensione del testo per ogni elemento, più un selettore di font.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "La pagina delle opzioni include un'anteprima dal vivo cliccabile che resta fissata mentre scorri — clicca un elemento qualsiasi per saltare alle sue impostazioni.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Movimento fluido della salute con una scia del danno, layout di testo con valore e percentuale con numeri abbreviati, e un interruttore per i decimali nei timer delle aure.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Condizioni di visibilità per ogni barra (istanze, in sella, bersaglio, gruppo), cambio pagina con modificatore, modalità rapida di assegnazione tasti (/vkb), una sesta barra, direzioni di crescita, stile del testo dei pulsanti e opzioni sull'aspetto dei cooldown.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Stile moderno per micro menu e barra delle borse: strisce scure piatte con un proprio set di icone monocromatiche, più i pulsanti per mappa del mondo, lista amici, ricerca gruppi, negozio e portachiavi.",
    ["The experience bar width now adjusts in single steps."] = "La larghezza della barra dell'esperienza ora si regola a passi singoli.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Condizioni di visibilità, modalità colore con gradiente, colori di sfondo e bordo, variazioni fluide dei valori, tacche di divisione e colorazione a soglia.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "Il pannello delle statistiche della scheda del personaggio non sconfina più nelle altre schede; la barra laterale dei loadout si allinea con la scheda del personaggio moderna.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "Il pannello e il pulsante del calcolatore di punti arena vestono l'aspetto dell'addon e si agganciano accanto alla scheda del personaggio.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Il menu di Esc ora veste l'aspetto scuro dell'addon — pulsanti piatti, titolo con colore d'accento — e guadagna un pulsante VuloClassicUI che apre la finestra delle opzioni. Entrambi hanno il proprio interruttore in Generale.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "La finestra di aggiunta amici è rivestita in tinta: pannello scuro, intestazione con colore d'accento, campo di testo scuro e pulsanti piatti.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "Hover e clic sulle intestazioni delle colonne del registro di gilda non sporgono più oltre la riga piatta delle intestazioni.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "La barra dei filtri del registro di combattimento ora condivide esattamente larghezza e altezza della riga delle schede della chat, a filo con il bordo del pannello.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "Dopo un aggiornamento, un punto pulsante sulla voce “Note della patch” segnala le nuove note finché non le apri una volta — a livello di account, per versione.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "Con lo stile Modern, la barra laterale dei set di equipaggiamento ora si aggancia a destra del pannello delle statistiche esattamente all'altezza della finestra, invece di sovrapporsi. Cambiare stile con la finestra aperta la sposta immediatamente.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "I pulsanti del micro menu che il gioco nasconde a seconda della situazione vengono mostrati di nuovo, così la riga non ha più un buco.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "La nameplate predefinita non traspare più come una debole barra trasparente sotto quella personalizzata — ora è nascosta del tutto e resta nascosta mentre la nameplate personalizzata è attiva.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Tutti i pulsanti del micro menu aprono di nuovo le loro finestre — il guscio svuotato del micro menu predefinito inghiottiva invisibilmente i clic sui pulsanti spostati.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Corretto un errore di azione bloccata quando la barra delle posture si aggiornava in combattimento; la visibilità dei pulsanti delle posture ora cambia solo fuori dal combattimento, mentre tinta dell'icona, cooldown e indicatore attivo continuano ad aggiornarsi dal vivo.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Un modulo Barre delle azioni mette ogni barra delle azioni su un proprio frame spostabile — barre delle azioni da 1 a 5, barra delle posture e barra del pet — ognuna posizionata e ridimensionata nella modalità Modifica e configurata singolarmente.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "La barra principale cambia pagina correttamente con le forme di druido, ladro, guerriero e sacerdote, e le tue assegnazioni dei tasti continuano a funzionare su ogni barra, con il tasto mostrato sui pulsanti.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Per ogni barra: visibilità (sempre, al mouseover, dentro o fuori dal combattimento), opacità, dimensione delle icone, pulsanti per riga, spaziatura, layout verticale, ordine inverso e possibilità di nascondere il testo del tasto o della macro — con dimensioni del testo regolabili per tasto, macro, conteggio e numeri dei cooldown.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Gli slot vuoti possono essere nascosti e ricompaiono automaticamente mentre trascini un'abilità sulla barra, e una barra può essere resa trasparente ai clic.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Impostazioni di cooldown e aspetto per tutte le barre: oscurità dell'animazione di cooldown, desaturazione delle icone in cooldown, colorazione delle icone quando il bersaglio è fuori portata e possibilità di nascondere i tooltip dei pulsanti sempre o solo in combattimento.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Una barra dell'esperienza propria con larghezza, altezza e colore regolabili, sovrapposizione del riposo e testo di avanzamento — sostituisce la barra predefinita finché è attiva e si nasconde al livello massimo.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "Il micro menu, la barra delle borse e la barra delle prestazioni poggiano su supporti spostabili, e ognuno di essi può essere nascosto — così come la barra dell'esperienza predefinita.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "Disattivato per impostazione predefinita: le barre standard restano intatte finché non attivi il modulo, e disattivandolo tutto torna com'era (un reload ripristina completamente le barre predefinite).",
    ["The dark button skin now also covers the new action-bar buttons."] = "La skin scura dei pulsanti ora copre anche i nuovi pulsanti delle barre delle azioni.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Un modulo Nameplate personalizzato disegna barra della salute, barra di lancio, nome e testo della salute propri sulle nameplate di nemici e NPC — completamente configurabile, con un'anteprima dal vivo che si aggiorna a ogni modifica.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Barra della salute con texture, larghezza, altezza e sfondo a tua scelta, e un bordo disegnato come linee sottili o come texture, tutto nei tuoi colori.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Colorazione per reazione (ostile, neutrale, amichevole, preso da altri) e per classe per i giocatori, più colorazione della minaccia in base al ruolo per tank e danni.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Anelli di evidenziazione per bersaglio e focus, e una dissolvenza opzionale per le nameplate che non sono il tuo bersaglio.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Barra di lancio con icona e nome dell'incantesimo, e un colore separato per i lanci che non possono essere interrotti.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Righe di aure: i tuoi debuff (o tutti), i buff dei nemici e una riga separata in evidenza per il controllo di massa come Polimorfia, Paura e Sap. Un bagliore contrassegna i buff nemici che puoi rubare o dissolvere.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Indicatori dei punti combo sul tuo bersaglio per Ladri e Druidi in forma felina.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Segnalini bersaglio dell'incursione (teschio, croce e gli altri) con dimensione e posizione regolabili.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "Le nameplate alleate possono mostrare solo il nome, la nameplate completa o niente — impostabile separatamente per giocatori e NPC — e possono mostrare il sottotitolo di un NPC amichevole sotto il suo nome.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Un unico modulo “Dark Skin” ora copre la skin scura dei pulsanti delle azioni e di WeakAuras più la Modalità Scura opzionale che scurisce i frame predefiniti di Blizzard — prima erano due moduli separati. Le tue impostazioni esistenti vengono mantenute.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "I moduli di reskin (skin, pannello del personaggio, chat, lista amici, minimappa) sono ora un'unica voce a schede, in linea con come sono già organizzati gli altri gruppi.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "I gruppi consolidati ora elencano i loro moduli in una colonna verticale con icone ed etichette invece di una riga di schede che va a capo — più facile da scorrere quando sono tanti.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Una pagina “Note della patch” sotto Panoramica mostra le modifiche di ogni versione direttamente nel gioco.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Nomi delle schede più puliti per alcuni strumenti: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Gli extra del riquadro del bersaglio e il bordo élite del riquadro del giocatore sono ora un unico modulo chiamato “Riquadro giocatore e bersaglio”. Le tue impostazioni esistenti e lo stato attivo/disattivo per personaggio vengono mantenuti automaticamente.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "Le impostazioni ora usano per impostazione predefinita un profilo separato per classe, così ciò che imposti su una classe non cambia più le altre. Le tue impostazioni attuali vengono copiate in ogni profilo di classe, e puoi ancora condividere o fissare i profili come prima.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "I messaggi scorrevoli che scattano nello stesso momento ora si impilano con uno spazio invece di sovrapporsi.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Corretto un errore che poteva comparire quando il combattimento iniziava mentre la tua lenza era in acqua. Le impostazioni di suono e interazione ora vengono ripristinate alla fine del combattimento.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Testo del tempo della barra di lancio più leggero, barre dei cooldown che raggruppano gli aggiornamenti nei momenti frenetici, un controllo del registro di combattimento più economico per il pulse dei cooldown e un controllo dell'hover sulla minimappa più leggero.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Le statistiche magiche sono ordinate come potere magico, cura, critico magico e poi precisione magica.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "Le schede Pesca e Posta ora riportano “Angeln” e “Post”.",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Un menu a tendina per lo stile in cima alle opzioni del modulo. Classic+ mantiene l'aspetto attuale; Modern è un nuovo stile scuro a finestra singola.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern riveste di scuro l'intera finestra del personaggio con un bordo d'accento e un pannello delle statistiche a destra: un grande livello degli oggetti equipaggiati, poi categorie richiudibili — attributi, mischia, magia, difesa e resistenze — con dettagli al passaggio del mouse per ogni statistica e scorrimento con la rotellina.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "Con Modern le statistiche integrate, le icone delle resistenze e le frecce di rotazione del modello sono nascoste, e le sotto-schede reputazione, abilità e giocatore contro giocatore più le schede inferiori sono rivestite in tinta. Tutto torna a Classic+ dal vivo e si adatta al client (statistiche di rating solo dove esistono).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Skin scura per una finestra di opzioni della mappa del mondo, con il proprio interruttore nelle opzioni Skin degli addon.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "L'orologio ora sta sulla stessa riga di data e zona invece di fluttuare più in alto.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Skin scura per un addon di distribuzione del bottino — le sue finestre di assegnazione e tiro, le finestre di impostazioni e panoramica, e le due barre sempre visibili di tiro e offerta ricevono il pannello nello stile della casa, il bordo d'accento e il pulsante di chiusura piatto.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Skin scura per un tracker degli attunement — la finestra principale e i suoi pulsanti si adeguano all'aspetto scuro; le righe di stato colorate restano come sono, così i colori di stato rimangono leggibili.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Entrambe hanno un interruttore separato nelle opzioni Skin degli addon, accanto agli altri.",
    ["NEW:"] = "NUOVO:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Un'unica finestra unificata dell'inventario: tutte le borse in una sola griglia, con bordi di qualità, conteggi, cooldown, denaro e slot liberi. Spostabile e ridimensionabile.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Corregge i bug dell'ispezione bloccata (nessuna ispezione dei giocatori possibile dopo una chiusura difettosa o un timeout). Reimpostazione automatica dopo un timeout, nuovo tentativo automatico quando la finestra resta vuota, pulizia alla chiusura di InspectFrame + comando /inspectreset.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Una minimappa moderna: rotonda con un anello scuro pulito e linea d'accento, testo della zona e orologio in un pannello sottile, zoom con la rotellina, spostabile e ridimensionabile. Volendo nasconde i pulsanti degli altri addon fino al mouseover.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Nameplate personalizzate per nemici e NPC con anteprima dal vivo: barra della salute, barra di lancio, nome e testo della salute, colori di reazione / classe, evidenziazione del bersaglio e colorazione della minaccia.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Passa il mouse su uno slot dell'equipaggiamento per un menu compatto degli oggetti compatibili nelle borse, oppure usa il clic con modificatore per un selettore più grande. Clicca un oggetto per equipaggiarlo.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Sposta ogni finestra VuloUI e i frame predefiniti di Blizzard in un unico editor.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Pesca con un solo tasto: un tasto lancia la lenza, la ritira e applica un'esca, e raccoglie automaticamente il pescato.",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Aggiunge alla cassetta postale un pulsante “Apri tutto” che raccoglie ogni allegato e moneta in un solo clic.",
    ["Top"] = "In alto",
    ["Bottom"] = "In basso",
    ["Top-Left"] = "In alto a sinistra",
    ["Top-Right"] = "In alto a destra",
    ["Bottom-Left"] = "In basso a sinistra",
    ["Bottom-Right"] = "In basso a destra",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: rimossi tutti i monili ignorati/nascosti.",
    ["Trinkets usage:"] = "Uso di Trinkets:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket or /Trinkets : apre/chiude la finestra",
    ["/trinket reset : reset all settings"] = "/trinket reset : reimposta tutte le impostazioni",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : rimuove tutti i monili ignorati/nascosti",
    ["/trinket opt : summon options window"] = "/trinket opt : richiama la finestra delle opzioni",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : attiva/disattiva il blocco della finestra",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (number) : imposta una scala esatta",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom profilename : carica un profilo sul monile superiore o inferiore",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Vuoi davvero riportare Trinkets allo stato predefinito e ricaricare l'interfaccia?",
    ["Queued: %s"] = "In coda: %s",
    ["Priority"] = "Priorità",
    ["Pause Queue"] = "Metti in pausa la coda",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "Il parametro deve essere 0 per il monile superiore o 1 per quello inferiore.",
    ["No profiles saved yet."] = "Nessun profilo salvato per ora.",
    -- Patch notes 1.37.1
    ["Visuals"] = "Aspetto",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "L'opzione della lingua in Generale ora si applica davvero. Non aveva mai effetto, in silenzio: l'addon leggeva la lingua del client prima che la tua scelta salvata fosse caricata. Dopo un /reload ogni etichetta, menu a tendina e finestra segue la tua scelta.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "La pagina delle note della patch è tradotta in tutte le lingue, comprese tutte le versioni precedenti.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "Il pannello dei monili, la sua finestra di coda e l'aiuto di /trinket sono anch'essi tradotti.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Tedesco: sedici traduzioni duplicate ripulite, cinque delle quali si contraddicevano.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Terzo passaggio sui percorsi di codice più carichi: le aure delle targhette dei nomi vengono esaminate una volta invece di quattro, gli eventi del registro di combattimento e delle aure risparmiano un involucro di sicurezza, i testi dei timer si ridisegnano solo quando cambia il numero mostrato e diversi ascoltatori in sottofondo dormono finché la loro funzione è spenta o nascosta. Meno scatti in incursione e in arena.",
    ["The frames can be turned off again without leftovers."] = "Le finestre si possono di nuovo disattivare senza residui.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Un incantesimo nemico interrotto ora mostra brevemente INTERROTTO — prima spariva nello stesso istante.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Le icone dei rendimenti decrescenti si ripuliscono correttamente dopo aver attivato o disattivato il tracciamento in piena arena.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Sette impostazioni funzionanti ma invisibili nelle opzioni sono di nuovo mostrate, e diversi interruttori che non facevano nulla ora sono collegati.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "I moduli fanno ordine quando vengono disattivati: l'oscuramento per distanza dei totem, la finestra di ispezione, il timer della coda, il registro delle missioni e le barre dei caratteri non lasciano più pezzi obsoleti.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Tre moduli hanno ricevuto icone proprie nella barra laterale al posto del segnaposto, e i Promemoria una campana più bella.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Indicatore di inizio missione (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Sovrappone un punto esclamativo giallo agli oggetti che avviano una missione non ancora accettata.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555Impossibile costruire la pagina delle opzioni '%s':|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Impossibile costruire questa pagina. Esegui /reload e segnalalo se persiste.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/fotogramma |cff666666(%.1f%% nostro, picco %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaL'intestazione mostra quanto tempo di fotogramma costa VuloClassicUI. Il tuo client lo misura da solo, sempre, senza impostazioni né ricariche.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore e Season of Discovery",
    ["Under the hood"] = "Sotto il cofano",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "L'addon si carica di nuovo senza spuntare «Carica AddOn non aggiornati». L'aggiornamento dell'interfaccia di Blizzard di luglio ha portato questi reami a un nuovo numero di versione.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Corretto un blocco che disattivava l'intera pagina dell'Addestratore di classe su Season of Discovery: una sola abilità sconosciuta al reame si portava dietro l'intero modulo.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "Il bordo élite della finestra del giocatore è di nuovo al posto giusto. Era allineato alla vecchia disposizione della finestra, sostituita da quello stesso aggiornamento.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Corretta una rara raffica di errori a fine combattimento. Il lavoro di pulizia di diciannove file poteva essere saltato e la chat si riempiva di righe di errore.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Le funzioni legate al registro di combattimento (timer dei colpi, impulso di recupero, testi di combattimento, tracciatore d'arena, targhette dei nomi, indicatore di mana) non dipendono più da un'impostazione disattivabile.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Un incantesimo nemico interrotto mostra ora davvero l'interruzione per un istante.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Gli oggetti che avviano una missione non ancora accettata sono contrassegnati da un punto esclamativo giallo, in borse, banca e portachiavi.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Sette delle otto traduzioni incluse non costruiscono più la loro tabella di consultazione. Viene assemblata solo la lingua che leggi davvero, liberando circa un megabyte a ogni accesso.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Modalità modifica: tre gestori in secondo piano non girano più di continuo, trascinare una finestra produce molti meno scarti e trovare una finestra è una consultazione diretta invece di una ricerca.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Disattivare un modulo ora lo scollega del tutto: diversi lasciavano ascoltatori attivi per il resto della sessione.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "L'indicatore di prestazioni nell'intestazione usa la misurazione sempre attiva del tuo client, quindi non serve né impostazione né ricaricare.",
    -- Patch notes 1.37.2
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Ancora nessuna misurazione. Gioca un po' e rileggi.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Misurato su %.1f s: %.1f ms in totale, di cui %.2f%% nostri:",
    ["Measurement off."] = "Misurazione disattivata.",
    ["Measurement reset."] = "Misurazione azzerata.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Misurazione attiva. Gioca un po', poi digita di nuovo /vcuiprof per leggerla.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Pagina dell'Addestratore di classe",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Corretto il fatto che la pagina venisse scartata subito dopo l'apertura, riportandoti su una scheda di classe. Il libro degli incantesimi reimposta la propria pagina ogni volta che i tuoi incantesimi cambiano, e la nostra si trova oltre l'ultima scheda reale: era quindi sempre quella scartata. Si nota soprattutto in Season of Discovery, dove l'incisione cambia incantesimi di continuo.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` misura quanto tempo di fotogramma costa ogni parte dell'addon e stampa un elenco. Viene distribuito disattivato e in quello stato non costa nulla: il codice di misurazione viene inserito solo quando lo attivi. Scrivilo una volta per avviare e una seconda per leggere.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Fare clic su un pulsante dei monili con lo slot vuoto non genera più un errore. La scorciatoia del gioco per «usa l'oggetto nello slot N» non tollera più uno slot vuoto dall'aggiornamento dell'interfaccia di luglio, quindi il pulsante segue ora un'altra strada verso la stessa azione.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Corretto uno scatto di quasi due fotogrammi a ogni inizio e fine combattimento, se usi WeakAuras e hai attivo il nostro stile per WeakAuras. Ogni cambio di combattimento ridipingeva ogni aura mai salvata — comprese quelle non a schermo — con un aspetto che non era cambiato. Ora le aure vengono ridipinte solo se impostazioni o dimensioni cambiano davvero. Misurato: da 28 ms a meno di 2 ms. Lo stile in sé resta identico.",
    -- Patch notes 1.39.0
    ["Download"] = "Download",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Posizione della riduzione degli effetti – Mette la fila su entrambi i lati della finestra, con scostamento X e Y propri",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "La fila della riduzione degli effetti non finisce più sopra l'icona del monile o dell'abilità razziale. Era fissata a una distanza rigida dal bordo destro, esattamente dove si trova l'icona laterale, così attivandola le due si sovrapponevano. Il nuovo valore predefinito la sposta oltre, e sul bordo sinistro la fila cresce verso l'esterno invece di attraversare la finestra.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Le icone del monile e dell'abilità razziale sono più distanti dalla finestra del nemico e un po' più piccole, così le barre di salute e mana si leggono come il centro della finestra invece di competere con un'icona su ogni spalla. Sono entrambi cursori, quindi i tuoi valori restano.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "La cartella dell'addon non contiene più strumenti di compilazione e file sorgente che nessun giocatore usa. I file di licenza restano dove sono.",
    ["The release notes on the distribution pages are written in English now."] = "Le note di versione sulle pagine di distribuzione sono ora scritte in inglese.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "A sei lingue mancavano sette testi che esistevano solo in tedesco. Tutte e nove sono di nuovo complete.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "L'aiuto sulle parole chiave della ricerca oggetti era fuorviante in cinese: come esempio riportava un nome di tipo in inglese che un client cinese non avrebbe mai trovato. Ora l'esempio è scritto nella lingua di chi legge.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Aiuto per il cambio dei sigilli – Una barra del colpo con la finestra di cambio segnata e la prossima azione sensata",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "La barra conta alla rovescia fino al tuo prossimo attacco automatico con due tacche: il verde è l'ultimo istante in cui il secondo sigillo può ancora entrare, il viola indica quanto tempo un Giudizio riesce ancora a starci prima. La prossima azione viene calcolata dal vivo dal tuo ritmo di colpo, dal tempo di recupero globale e dai sigilli realmente attivi su di te — non da una rotazione fissa. Colpo del Crociato viene suggerito solo finché resta spazio per esso e per il sigillo che mantieni. Il Giudizio non ne riceve volutamente alcuna: consuma il sigillo, e lì un consiglio sbagliato costa più di nessun consiglio. Disattivato per impostazione predefinita.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Borse e oggetti",
    ["Chat & Social"] = "Chat e sociale",
    ["Extras"] = "Extra",
    ["Tools"] = "Strumenti",
    -- Overview page
    ["peak %.1f ms"] = "picco %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d su %d",
    ["moved"] = "spostate",
    ["Modules"] = "Moduli",
    ["Frame time"] = "Tempo per fotogramma",
    ["Memory"] = "Memoria",
    ["Windows"] = "Finestre",
    ["%d modules are switched off."] = "%d moduli sono disattivati.",
    ["The edit mode grid is switched on."] = "La griglia della modalità modifica è attiva.",
    ["There are patch notes you have not read yet."] = "Ci sono note di versione che non hai ancora letto.",
    ["What would you like to change?"] = "Cosa vuoi impostare?",
    ["Worth knowing"] = "Utile sapere",
    ["Recently visited"] = "Visitati di recente",
    -- Talent overrides
    ["active"] = "attivi",
    ["Talent Overrides"] = "Impostazioni per gruppo talenti",
    ["Talent group %d"] = "Gruppo talenti %d",
    ["%d settings overridden"] = "%d impostazioni sostituite",
    ["Forget all overrides for this talent group"] = "Dimentica tutte le impostazioni di questo gruppo talenti",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Le impostazioni si applicano da sole al cambio di gruppo talenti. Questo client non ha specializzazioni, quindi l’asse è il sistema a doppio talento.",
    -- Override groups
    ["Talent group %d (%s)"] = "Gruppo talenti %d (%s)",
    ["Name for the new group"] = "Nome del nuovo gruppo",
    ["Editing as"] = "Modifica come",
    ["Yourself"] = "Te stesso",
    ["Manage groups..."] = "Gestisci gruppi...",
    ["Owns the current talent group"] = "Vale per il gruppo talenti attuale",
    ["Delete this group"] = "Elimina questo gruppo",
    ["No groups yet."] = "Nessun gruppo ancora.",
    -- Anchor points
    ["Centre"] = "Centro",
    ["Thin outline"] = "Contorno sottile",
    ["Bar Setups"] = "Configurazioni barra",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Spostato dalla barra laterale alle Impostazioni globali, come scheda a sé accanto ai Profili. Le configurazioni salvate sono state mantenute.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Erano memorizzate una volta per ogni profilo di classe: sette copie della stessa libreria di macro. Ora sono memorizzate una sola volta, il che ha ridotto di un terzo il file delle impostazioni. Le copie identiche vengono unite, quelle diverse restano affiancate.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "La finestra della chat non torna più indietro appena apri la modalità di modifica. Un cambio di layout riancora ogni finestra che il gioco conosce, comprese quelle che posizioniamo noi.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Un menu a tendina con una voce lunga non va più a capo nella riga sottostante.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "La prima pagina mostra lo stato della tua interfaccia invece di una seconda barra laterale: moduli attivi, tempo per fotogramma e memoria, finestre spostate e ultime pagine visitate.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Sostituzioni dei talenti – I gruppi con nome conservano valori propri per singole impostazioni e si applicano quando cambi selezione dei talenti",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Un gruppo può anche indicare una situazione: incursione, spedizione, arena, campo di battaglia, in gruppo, da solo. Tutto ciò che modifichi con un gruppo attivo viene registrato al suo interno e ogni riga sostituita è contrassegnata.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "I cursori occupano una riga come ogni altra impostazione, il loro numero si può digitare e le etichette si allineano in una colonna misurata su tutta la pagina. Una traduzione lunga non spinge più un blocco valore nella colonna accanto né un pulsante fuori dalla sua scheda.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Ogni sezione parte chiusa, così una pagina lunga si apre come un elenco di intestazioni.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "La coda di scambio automatico ha di nuovo i comandi: ordine, ritardo e il segnale di arresto, nella pagina dei monili. Prima esistevano solo in una finestra che questo componente nasconde.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Le icone dei monili sono di nuovo visibili: sui pulsanti, sul segnale della coda e sui monili indossati subito dopo l'accesso, invece che solo dopo un clic.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s non ha ancora un gestore — è un errore, segnalalo per favore.",
    ["%s belongs to %s, which is switched off."] = "%s appartiene a %s, che è disattivato.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffComandi|r — %d in totale. Quelli grigi appartengono a un modulo disattivato.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s è rivendicato anche da un altro componente (%s) — vince solo uno dei due.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555Il modulo delle configurazioni barra non è caricato.|r",
    ["Bar setup '%s' saved."] = "Configurazione barra '%s' salvata.",
    ["Bar setup '%s' deleted."] = "Configurazione barra '%s' eliminata.",
    ["Not in combat — bars can't be changed while fighting."] = "Fuori dal combattimento — le barre non si possono cambiare mentre combatti.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Configurazione barra '%s' caricata: %d slot impostati, %d svuotati, |cffff8800%d saltati|r (incantesimo sconosciuto / oggetto o macro mancante).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Configurazione barra '%s' caricata: %d slot impostati, %d svuotati.",
    ["on"] = "attivo",
    ["Overridden settings: %s"] = "Impostazioni sostituite: %s",
    ["Situation"] = "Situazione",
    ["Everywhere"] = "Ovunque",
    ["Raid instance"] = "Incursione",
    ["5-player instance"] = "Spedizione (5 giocatori)",
    ["Battleground"] = "Campo di battaglia",
    ["In a group"] = "In gruppo",
    ["Alone"] = "Da solo",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Vale solo in questa situazione. Insieme a una selezione dei talenti devono essere vere entrambe — e quel gruppo prevale allora su uno che indica soltanto la selezione dei talenti.",
    ["Icon"] = "Icona",
    ["No icon"] = "Nessuna icona",
    ["Shown in front of the group name in the menu and on the header button."] = "Compare davanti al nome del gruppo nel menu e sul pulsante di intestazione.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Disattivare rimuove solo questa sostituzione. L'impostazione torna poi a seguire il profilo.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Le configurazioni barra ora sono memorizzate una sola volta per tutto l'account: %d conservate, %d duplicate unite.",
    ["Trinket window settings now live in this addon's own database."] = "Le impostazioni della finestra dei monili risiedono ora nel database di questo componente.",
    ["Auto queue: top slot"] = "Coda automatica: slot superiore",
    ["Auto queue: bottom slot"] = "Coda automatica: slot inferiore",
    ["Auto queue for this slot"] = "Coda automatica per questo slot",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "Lo stesso interruttore di un alt-clic sullo slot. Attiva, la coda scambia questo monile in combattimento seguendo l'ordine qui sotto.",
    ["Order"] = "Ordine",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "La coda percorre questo elenco dall'alto. Scegli una voce per spostarla o per cambiarne le impostazioni.",
    ["- empty -"] = "- vuoto -",
    ["— queue stops here —"] = "— la coda si ferma qui —",
    ["Add from bags"] = "Aggiungi dalle borse",
    ["Adds a trinket you are carrying to the end of this list."] = "Aggiunge in fondo a questo elenco un monile che porti con te.",
    ["Swap delay"] = "Ritardo di scambio",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Secondi in cui questo monile resta equipaggiato prima che la coda lo scambi di nuovo. 0 = nessuna attesa.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Questo monile viene equipaggiato prima di quelli sopra non appena è pronto.",
    ["Pause while equipped"] = "Sospendi mentre è equipaggiato",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Finché indossi questo monile la coda resta ferma — per un monile il cui effetto non vuoi interrompere.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaSuggerimento: clic sinistro su uno slot per usare il monile, clic destro per l'elenco. Alt-clic arma la coda automatica di quello slot.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d istantanea/e avevano lo stesso nome ma contenuto diverso e sono state conservate con un nuovo nome.",
    ["GAP"] = "DISTANZA",
    ["Distance from that edge, in pixels. 0 is flush."] = "Distanza da quel bordo, in pixel. 0 significa a filo.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Aggancia questa finestra a quel lato della finestra di riferimento e ve la centra. 'Centrato' non la sposta — la fa solo seguire. La distanza è mantenuta da bordo a bordo, quindi sopravvive al ridimensionamento di entrambe le finestre.",
    ["waiting for a swing"] = "in attesa di un colpo",
    ["  -  lag %.0fms"] = "  -  latenza %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Nessun sigillo da cui scambiare. Solo il Sigillo del Comando e il Sigillo della Rettitudine valgono ancora su un colpo dopo essere stati sostituiti, quindi serve conoscerne uno dei due.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Conosci un solo sigillo. Ne serve un secondo verso cui scambiare.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800Dal sigillo che mantieni non si può scambiare. Solo il Sigillo del Comando e il Sigillo della Rettitudine valgono ancora sul colpo che li sostituisce.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Qui vanno bene solo il Sigillo del Comando e il Sigillo della Rettitudine: sono i due il cui effetto vale ancora sul colpo che li sostituisce.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "Le impostazioni delle targhette sono state sostituite. Cambia profilo per riavere quelle precedenti.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Sovrascrive le impostazioni delle targhette di questo profilo con un aspetto largo, piatto e scuro. Gli altri profili restano intatti.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaSovrascrive le impostazioni delle targhette di questo profilo con un aspetto largo, piatto e scuro. Gli altri profili restano intatti.|r",
    ["Apply the wide, flat look"] = "Applica l'aspetto largo e piatto",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Posizioni principali",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaUna cosa per slot. Ciò che assegni a uno slot viene tolto a quello che lo aveva.|r",
    ["Debuffs"] = "Penalità",
    ["Buffs"] = "Benefici",
    ["Crowd control"] = "Controllo di massa",
    ["Your own debuffs"] = "Le tue penalità",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "Bagliore a vita bassa",
    ["A coloured ring around the bar once the unit drops below the mark."] = "Un anello colorato attorno alla barra appena il bersaglio scende sotto la soglia.",
    ["Glow below (%)"] = "Bagliore sotto (%)",
    ["Low health colour"] = "Colore a vita bassa",
    ["Glow in the aura's own school colour"] = "Bagliore nel colore di scuola dell'aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Magia blu, maledizione viola, malattia arancione, veleno verde — invece di un colore per tutto.",
    -- Absorptionsstil
    ["Absorb style"] = "Stile assorbimento",
    ["Flat colour"] = "Tinta unita",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "Mostrare su chi è lanciata la magia",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "Il bersaglio attuale di chi lancia, accanto alla barra di lancio. Il tuo nome viene colorato.",
    ["Cast target size"] = "Dimensione del bersaglio della magia",
    -- Zielpfeile
    ["Arrows beside your target"] = "Frecce accanto al bersaglio",
    ["Two arrows pointing in at the target's bar, one on each side."] = "Due frecce che puntano alla barra del bersaglio, una per lato.",
    ["Arrow size"] = "Dimensione frecce",
    ["Arrow distance"] = "Distanza frecce",
    ["Arrow colour"] = "Colore frecce",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Contrassegno sulla targhetta del focus",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Un testo breve sulla targhetta del tuo focus. Un anello dice che quella è speciale; il contrassegno dice quale.",
    ["Mark text"] = "Testo del contrassegno",
    ["Mark position"] = "Posizione del contrassegno",
    ["Mark size"] = "Dimensione del contrassegno",
    -- Kleine Plaketten
    ["Back to the small plates"] = "Torna alle targhette piccole",
    ["Puts the same settings back to the small plates this addon ships with."] = "Riporta le stesse impostazioni alle targhette piccole fornite con questo componente.",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaMantieni il Sigillo del Comando e lancia il secondo sigillo nell'ultima frazione di secondo prima dell'attacco automatico: quel colpo li porterà entrambi. Sotto il livello 64 il secondo sigillo è quello della Rettitudine; da lì in poi lo sostituiscono Sangue e Martire.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaLa barra conta alla rovescia fino al colpo per zone: |cff5c8aebblu|r è libera per un riempitivo, |cffd93636rosso|r è il tratto in cui un lancio sarebbe ancora in recupero globale all'apertura della finestra, e |cff33ff66verde|r è la finestra di scambio. L'ultimo segno nel verde è lo scambio tardivo, che lascia spazio a un giudizio davanti al sigillo.|r",
    ["Late twist window (seconds)"] = "Finestra di scambio tardivo (secondi)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "La coda della finestra di scambio, segnata a parte. Scambiare così tardi lascia ancora spazio a un giudizio davanti al sigillo. Impostala uguale alla finestra di scambio per nascondere il segno.",
    ["Second cue for the late window"] = "Secondo segnale per la finestra tardiva",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Un suono diverso sul segno dello scambio tardivo, per distinguere le due estremità della finestra senza guardare la barra.",
    ["Shade the zones"] = "Colora le zone",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Tinge la parte di colpo ancora da venire con il colore della zona in cui finisce.",
    ["Show the marks"] = "Mostra i segni",
    ["The three boundary lines: danger zone, twist window, late twist."] = "Le tre linee di confine: zona di pericolo, finestra di scambio, scambio tardivo.",
    ["Show seal indicators"] = "Mostra gli indicatori dei sigilli",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "I sigilli che hai addosso e quanto durano, a destra della barra. Durante lo scambio si vedono entrambi: quella sovrapposizione è il guadagno.",
    ["Seal icon size"] = "Dimensione icone dei sigilli",
    ["Head start for the prompt (ms)"] = "Anticipo del segnale (ms)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Mostra il segnale di scambio e riproduce il suo suono con questo anticipo rispetto all'apertura reale della finestra, per dare il tempo di vederlo e premere. I colori sulla barra restano esatti.",
    ["auto"] = "Auto",
    ["Twist only"] = "Solo scambio",
    ["Rotation"] = "Rotazione",
    ["Show the rotation helper"] = "Mostra l'aiuto alla rotazione",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Una fila di passi sopra la barra: quale sequenza si adatta alla tua arma e alla tua celerità, e a che punto sei. Avanza in base a ciò che lanci davvero e ai tuoi colpi.",
    ["Sequence"] = "Sequenza",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Automatica segue la velocità d'attacco e la celerità magica, che decidono quanti scambi stanno fra due colpi. Scegline una a mano per allenare una singola sequenza.",
    ["Rotation icon size"] = "Dimensione icone",
    ["Sound when the twist lands"] = "Suono quando lo scambio riesce",
    ["Hit sound"] = "Suono di riuscita",
    ["Listen"] = "Ascolta",
    ["Chime"] = "Campanello",
    ["Raid warning"] = "Avviso incursione",
    ["Ready check"] = "Controllo prontezza",
    ["Click"] = "Clic",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "Spostare una finestra poteva generare un errore di azione bloccata se eri in combattimento mentre le finestre venivano costruite. La tastiera viene presa solo quando uno spostatore è a schermo.",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "Le impostazioni della finestra dei monili venivano scritte una seconda volta nel file salvato con i vecchi nomi. Ora sono memorizzate una sola volta.",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "42 testi esistevano solo in tedesco, fra cui tutta l’interfaccia delle sostituzioni dei talenti e la coda dei monili. Le nove lingue sono di nuovo complete.",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "Posizioni principali – Sei slot attorno alla targhetta, ognuno con una sola cosa: penalità, benefici, controllo di massa o i tuoi danni nel tempo",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "Bagliore a vita bassa – Un anello colorato appena il bersaglio scende sotto la tua soglia",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "Frecce accanto al bersaglio – Due frecce che puntano alla barra da entrambi i lati",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "Contrassegno sulla targhetta del focus – Un testo breve per distinguere bersaglio e focus a colpo d’occhio",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "Modello – Un clic per un aspetto largo, piatto e scuro, e uno per tornare alle targhette piccole",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "Due dei sei slot stanno accanto alla targhetta come colonna, cosa prima impossibile. E due righe non possono più sovrapporsi: ciò che assegni a uno slot viene tolto a quello che lo aveva.",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "La barra di lancio può indicare su chi è lanciata la magia, con il tuo nome colorato.",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "Zone di twist – La barra di attacco risponde a cosa puoi premere ora invece di fare il conto alla rovescia",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "Aiuto alla rotazione – Una breve sequenza invece di un singolo passo successivo, calcolata dalla velocità di arma e di lancio",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "Il sigillo verso cui passi può essere qualsiasi altro sigillo, non solo i due che arrivano al livello 64.",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "Le sezioni non si chiudono più. Le pagine lunghe si chiudono sull’ingranaggio di una riga, che dice qualcosa che una sezione non ha mai detto: le righe dietro appartengono all’interruttore su cui si trova.",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "I controlli sono allineati lungo la pagina e un interruttore sta al centro della sua riga.",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Scurire i nemici fuori dal combattimento",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Attenua i nemici che non stanno combattendo, così risaltano quelli che lo fanno. Mai il tuo bersaglio.",
    ["Darken to (%)"] = "Scurire al (%)",
    ["Cast bars in front of other plates"] = "Barre di lancio davanti alle altre targhette",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "In un pull le targhette si sovrappongono e una barra di lancio può finire dietro quella davanti.",
    ["Highlight strength"] = "Intensità dell’evidenziazione",
    ["Hitbox width (%)"] = "Larghezza area cliccabile (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Area cliccabile della targhetta. 100 lascia intatta la dimensione del gioco. Salvato nel profilo.",
    ["Hitbox height (%)"] = "Altezza area cliccabile (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Colpo di fucile",
    -- Aktionszeile
    ["Action text size"] = "Dimensione del testo di azione",
    ["The line that names what to press. 0 follows the general text size."] = "La riga che dice cosa premere. 0 segue la dimensione generale del testo.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Dimensione del timer del sigillo",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "Il conto alla rovescia sulle icone dei sigilli. 0 lo scala con l’icona.",
    -- Warnzeile
    ["Warning text size"] = "Dimensione del testo di avviso",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Gli avvisi rossi e gialli sulla barra. 0 segue la dimensione del testo di azione.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Limita questa icona a un numero di cariche, o agli ultimi secondi prima che scada.",
    ["Only from stacks"] = "Solo da cariche",
    ["0 = any number of stacks."] = "0 = qualsiasi numero di cariche.",
    ["Only in the last seconds"] = "Solo negli ultimi secondi",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = in qualsiasi momento. Altrimenti l’icona appare solo così vicino alla scadenza.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Osserva questa unità",
    ["Whose auras this group reads. The default is what the group type has always used."] = "Di chi legge le aure questo gruppo. Il valore predefinito è quello che il tipo di gruppo ha sempre usato.",
    ["You"] = "Tu",
    ["Target"] = "Bersaglio",
    ["Focus"] = "Focus",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Solo ciò che lancio io stesso",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Disattivato conta l’aura da chiunque sia stata messa — per una penalità da incursione che chiunque può applicare.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Fisso mantiene l’ordine in cui li hai aggiunti. Gli altri due riordinano dal vivo in base al tempo rimasto.",
    ["As added"] = "Come aggiunti",
    ["Least time left first"] = "Prima il tempo rimasto più breve",
    ["Most time left first"] = "Prima il tempo rimasto più lungo",
    ["Practice"] = "Pratica",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaUn orologio dei colpi che gira da solo, senza bersaglio e senza consumare nulla. Premi i tuoi tasti assegnati e ogni colpo viene valutato: il twist è riuscito, è arrivato troppo presto, oppure non hai tentato nulla. Il modello dei sigilli è quello vero -- un sigillo sostituito continua a risolversi per 0,4 secondi -- quindi il tempismo che impari qui è il tempismo che funziona.|r",
    ["Start / stop practice"] = "Avvia / ferma la pratica",
    ["Stop practice"] = "Ferma la pratica",
    ["Simulated weapon speed"] = "Velocità dell'arma simulata",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0 usa ciò che hai equipaggiato. Qualsiasi altro valore ti allena su una velocità che ancora non possiedi, ed è così che scopri che l'arma per cui stai risparmiando richiede una sequenza diversa.",
    ["Spell queue window (ms)"] = "Finestra di accodamento incantesimi (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Un tasto premuto con questo anticipo rispetto alla fine del tempo di recupero globale viene trattenuto e parte nell'istante esatto in cui esso finisce, proprio come fa il client. Allenarsi senza insegna un ritmo che il gioco non chiede mai.",
    ["Result text size"] = "Dimensione del testo del risultato",
    ["Result text duration (seconds)"] = "Durata del testo del risultato (secondi)",
    ["Landed colour"] = "Colore di riuscita",
    ["Missed colour"] = "Colore di fallimento",
    ["Show the fight timeline"] = "Mostra la cronologia del combattimento",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Ogni colpo e ogni lancio su un'unica striscia, con un righello. Il righello è il punto: senza di esso vedi che due colpi erano vicini, ma non quanto vicini, ed è l'unico numero di cui la pratica si occupa.",
    ["Timeline width"] = "Larghezza della cronologia",
    ["Timeline pixels per second"] = "Pixel al secondo della cronologia",
    ["TWIST"] = "TWIST",
    ["MISS"] = "MANCATO",
    ["TOO EARLY"] = "TROPPO PRESTO",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "velocità %.2fs  -  GCD %.2fs  -  %d di %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffPRATICA|r",
    ["|cffffffffRESULT|r"] = "|cffffffffRISULTATO|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffCRONOLOGIA|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Pratica del twist|r",
    ["Practice needs two seals: pick them under Seals first."] = "La pratica richiede due sigilli: prima scegline due sotto Sigilli.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Modalità pratica attiva. Premi i tuoi tasti assegnati; il colpo gira da solo.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Modalità pratica disattivata. %d colpi su %d hanno portato il twist.",
    ["Bloodlust"] = "Bramasangue",
    ["Haste potion"] = "Pozione di celerità",
    ["Abacus"] = "Abaco",
    ["Time warp"] = "Distorsione temporale",
    ["Crusader Strike"] = "Colpo del Crociato",
    ["Judgement"] = "Giudizio",
    ["Cast the held seal"] = "Lancia il sigillo trattenuto",
    ["Cast the twist seal"] = "Lancia il sigillo del twist",
    ["Filler"] = "Riempitivo",
    ["Start / stop attack"] = "Avvia / ferma l'attacco",
    ["wait"] = "attendi",
    ["Next action"] = "Prossima azione",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffPROSSIMA AZIONE|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Spostamento della prossima azione attivo. |cff9b6cffTrascina il riquadro viola|r oppure usa i |cff9b6cfftasti freccia|r (MAIUSC = 5px). Fai di nuovo clic su 'Sblocca / Prova' per terminare.",
    ["Next action mover disabled."] = "Spostamento della prossima azione disattivato.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaUn'icona dell'unica cosa da premere, dove vuoi tu. Risponde alla stessa domanda della riga sotto la barra -- i tre interruttori qui sotto alimentano entrambe, così la parola e l'immagine non possono mai contraddirsi.|r",
    ["Show the next action guide"] = "Mostra la guida alla prossima azione",
    ["When to show it"] = "Quando mostrarla",
    ["Show a hold instead of nothing"] = "Mostra un'attesa invece del vuoto",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Quando la mossa giusta è non premere nulla di proposito -- il twist sta arrivando e qualsiasi altra cosa lo farebbe perdere -- la guida continua a mostrare il sigillo, scolorito e contornato. Un riquadro vuoto dice la stessa cosa in modo molto meno chiaro.",
    ["Suggest Judgement"] = "Suggerisci Giudizio",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Il giudizio consuma il sigillo, quindi viene proposto solo quando resta spazio per rimettere il sigillo dopo. Disattivato di base: un giudizio fuori tempo costa più di nessun suggerimento.",
    ["Suggest a filler"] = "Suggerisci un riempitivo",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Consacrazione, oppure Esorcismo dove il bersaglio può subirlo, nel tratto del colpo che è libero per farlo. Esorcismo viene proposto chiedendo al client se l'incantesimo può essere puntato sul tuo bersaglio, il che è corretto in ogni lingua.",
    ["Consecration mana floor (%)"] = "Soglia minima di mana per Consacrazione (%)",
    ["Below this share of your mana the filler is not worth it."] = "Sotto questa quota del tuo mana il riempitivo non ne vale la pena.",
    ["Exorcism mana floor (%)"] = "Soglia minima di mana per Esorcismo (%)",
    ["Longest Crusader Strike delay (ms)"] = "Ritardo massimo per Colpo del Crociato (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "Quando rimandare il colpo oltre questo limite significherebbe sprecarlo, smette di essere un suggerimento e diventa la risposta. Misurato rispetto al primo istante in cui potresti davvero lanciarlo, non rispetto a ora.",
    ["Twist!"] = "Twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffTESTO TWIST|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Spostamento del testo del twist attivo. |cff9b6cffTrascina il riquadro viola|r oppure usa i |cff9b6cfftasti freccia|r (MAIUSC = 5px). Fai di nuovo clic su 'Sblocca / Prova' per terminare.",
    ["Twist text mover disabled."] = "Spostamento del testo del twist disattivato.",
    ["Twist landed"] = "Twist riuscito",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaTutti e tre i segnali qui sotto aspettano una PROVA, non una previsione. Un colpo deve andare a segno con entrambi i sigilli attivi, e il danno del sigillo trattenuto deve seguirlo nel registro di combattimento. Nulla scatta senza quella seconda riga -- una conferma che è giusta quasi sempre è una conferma su cui non puoi allenarti.|r",
    ["Sound channel"] = "Canale audio",
    ["Master"] = "Principale",
    ["Sound effects"] = "Effetti sonori",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Il canale principale ignora il cursore degli effetti sonori, ed è proprio ciò che serve a una conferma: è un riscontro sul combattimento, non una sua parte.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Gli schiocchi del fucile di precisione e della carabina sono inclusi; il resto sono i segnali propri del client. Sotto di essi trovi i suoni che altri componenti aggiuntivi hanno registrato come risorse condivise.",
    ["Sniper"] = "Fucile di precisione",
    ["Level up"] = "Passaggio di livello",
    ["Quest complete"] = "Missione completata",
    ["Bonus objective"] = "Obiettivo bonus",
    ["Map ping"] = "Segnale sulla mappa",
    ["Glow on the bar when the twist lands"] = "Bagliore sulla barra quando il twist riesce",
    ["Glow style"] = "Stile del bagliore",
    ["Pixel border"] = "Bordo a pixel",
    ["Autocast ring"] = "Anello di lancio automatico",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "Il bordo a pixel segue il contorno della barra a qualsiasi larghezza. L'anello di lancio automatico fissa l'anello del client ai quattro angoli, così resta un anello per quanto larga diventi la barra.",
    ["Glow colour"] = "Colore del bagliore",
    ["Glow duration (seconds)"] = "Durata del bagliore (secondi)",
    ["Text when the twist lands"] = "Testo quando il twist riesce",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Una riga da qualche parte sullo schermo, con una posizione tutta sua. Utile quando la barra sta con la coda dell'occhio e la conferma dovrebbe stare al centro dello sguardo.",
    ["Text font"] = "Carattere del testo",
    ["Text outline"] = "Contorno del testo",
    ["Text colour"] = "Colore del testo",
    ["Text duration (seconds)"] = "Durata del testo (secondi)",
    ["|cffffffffSEALS|r"] = "|cffffffffSIGILLI|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Spostamento dell'indicatore dei sigilli attivo. |cff9b6cffTrascina il riquadro viola|r oppure usa i |cff9b6cfftasti freccia|r (MAIUSC = 5px). Fai di nuovo clic su 'Sblocca / Prova' per terminare.",
    ["Seal indicator mover disabled."] = "Spostamento dell'indicatore dei sigilli disattivato.",
    ["Match the bar height"] = "Adatta all'altezza della barra",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Dimensiona le icone sulla barra invece che sulla loro impostazione, così la coppia resta allineata con essa quando l'altezza della barra cambia.",
    ["Ignored while the icons match the bar height."] = "Ignorato mentre le icone seguono l'altezza della barra.",
    ["Seal icon spacing"] = "Distanza tra le icone dei sigilli",
    ["Centre the icons"] = "Centra le icone",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Mantiene fermo il punto medio della coppia quando il secondo sigillo compare o svanisce. L'allineamento a sinistra tiene fermo invece la prima icona, che è ciò che serve a una coppia agganciata -- quel bordo è la barra.",
    ["Show the cooldown sweep"] = "Mostra la spazzata del tempo di recupero",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "La spazzata propria del client sull'icona. Dice la stessa cosa del numero che sta sotto, ma la dice senza dover essere letta.",
    ["Seal timer colour"] = "Colore del contatore dei sigilli",
    ["Detach from the bar"] = "Stacca dalla barra",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Dà alla coppia una posizione tutta sua, ovunque sullo schermo. Per tutto il resto restano legate alla barra: quando è nascosta, lo sono anche loro.",
    ["Twist lost"] = "Twist perso",
    ["Swing ready -- restart your attack"] = "Colpo pronto -- riavvia l'attacco",
    ["(none available)"] = "(nessuno disponibile)",
    ["Solid"] = "Tinta unita",
    ["Attack speed"] = "Velocità d'attacco",
    ["Swing timer"] = "Contatore del colpo",
    ["Latency (ms)"] = "Latenza (ms)",
    ["Global cooldown left"] = "Recupero globale rimanente",
    ["Nothing"] = "Niente",
    ["Left readout"] = "Valore a sinistra",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "Ciò che mostra l'estremità sinistra della barra. La velocità d'attacco passa al colore d'avviso sotto i due tempi di recupero globali per colpo -- sotto quella soglia il twist e il ritorno del sigillo non ci stanno più entrambi, quindi aspetta il recupero prima di fare twist.",
    ["Right readout"] = "Valore a destra",
    ["Readout text size"] = "Dimensione del testo dei valori",
    ["The two numbers inside the bar. 0 follows the general text size."] = "I due numeri dentro la barra. 0 segue la dimensione generale del testo.",
    ["Global cooldown bar texture"] = "Texture della barra del recupero globale",
    ["Border"] = "Bordo",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Tinta unita disegna quattro bordi piatti nel colore qui sotto. Texture prende un file di bordo dalle risorse condivise, ed è l'aspetto che ha un bordo preso da un altro pacchetto d'interfaccia.",
    ["Only used while the border is set to texture."] = "Usato solo quando il bordo è impostato su texture.",
    ["Border width"] = "Spessore del bordo",
    ["Marker texture"] = "Texture del marcatore",
    ["Marker width"] = "Spessore del marcatore",
    ["Font colour"] = "Colore del carattere",
    ["Frame strata"] = "Strato del riquadro",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "In quale livello dell'interfaccia si trova l'aiuto. Alzalo per portare la barra sopra un altro componente aggiuntivo che disegna nello stesso punto.",
    ["Draw level"] = "Livello di disegno",
    ["The order inside the chosen layer. Higher draws on top."] = "L'ordine all'interno del livello scelto. Un valore più alto disegna sopra.",
    ["Colour the bar by"] = "Colora la barra in base a",
    ["The zone the swing is in"] = "La fase in cui si trova il colpo",
    ["The seal you are carrying"] = "Il sigillo che stai portando",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Le fasi colorano il riempimento in base al tratto del colpo in cui ti trovi, ed è il criterio attorno a cui è costruito questo aiuto. Il sigillo lo colora in base a ciò che stai portando, e si legge più in fretta quando il tempismo è ormai nelle dita. In ogni caso i colori speciali qui sotto hanno la precedenza sulla scelta.",
    ["Seal of Command"] = "Sigillo del Comando",
    ["Seal of Righteousness"] = "Sigillo della Rettitudine",
    ["Seal of Blood / the Martyr"] = "Sigillo del Sangue / del Martire",
    ["Seal of Vengeance"] = "Sigillo della Vendetta",
    ["Seal of the Crusader"] = "Sigillo del Crociato",
    ["Seal of Justice"] = "Sigillo della Giustizia",
    ["Seal of Light"] = "Sigillo della Luce",
    ["Seal of Wisdom"] = "Sigillo della Saggezza",
    ["No twist possible"] = "Nessun twist possibile",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "Il riempimento quando il twist di questo colpo è ormai perso, e la coda del colpo che un lancio non può più raggiungere.",
    ["Warning"] = "Avviso",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Gli avvisi sulla barra, e la velocità d'attacco quando l'arma è troppo veloce per fare twist.",
    ["Twisting"] = "Twist in corso",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "Il riempimento mentre entrambi i sigilli sono attivi: il twist è a posto e questo colpo lo porta.",
    ["Default"] = "Predefinito",
    ["The fill with no seal up and between swings."] = "Il riempimento senza alcun sigillo attivo e tra un colpo e l'altro.",
    ["Global cooldown"] = "Tempo di recupero globale",
    ["Deadzone"] = "Zona morta",
    ["Twist window padding"] = "Margine della finestra di twist",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Anticipa la finestra di twist così che il lancio raggiunga comunque il server al suo interno. Dinamico segue la tua latenza calibrata; fisso è un numero che scegli tu.",
    ["Fixed twist padding (ms)"] = "Margine di twist fisso (ms)",
    ["Only used while the padding mode is set to fixed."] = "Usato solo quando la modalità del margine è impostata su fisso.",
    ["Dynamic (follows latency)"] = "Dinamico (segue la latenza)",
    ["Fixed"] = "Fisso",
    ["Latency"] = "Latenza",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaIl tempo di andata e ritorno riportato dal tuo client non è il ritardo che un twist deve battere: il client aggiunge una fetta tutta sua, quindi il valore da cui parte tutto ciò che segue è (latenza del mondo x moltiplicatore) + scostamento. Alza il moltiplicatore se continui a mancare twist che sembravano in tempo.|r",
    ["Latency multiplier"] = "Moltiplicatore della latenza",
    ["Latency offset (ms)"] = "Scostamento della latenza (ms)",
    ["Shade the deadzone"] = "Ombreggia la zona morta",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "La coda del colpo che un lancio non può più attraversare, ombreggiata alla fine della barra. La sua dimensione segue la tua latenza del mondo grezza invece del valore calibrato, perché questa è la linea e non una previsione. Questo interruttore la disegna soltanto -- il tempismo la considera sempre, quindi imposta la scala a 0 se non vuoi alcuna compensazione.",
    ["Deadzone scale"] = "Scala della zona morta",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Moltiplica la tua latenza del mondo. Alzala se non riesci a fare twist appena fuori dal tratto ombreggiato, abbassala se ci riesci ancora al suo interno. 0 disattiva del tutto la compensazione.",
    ["Deadzone texture"] = "Texture della zona morta",
    ["Deadzone transparency"] = "Trasparenza della zona morta",
    ["Global cooldown padding"] = "Margine del recupero globale",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Anticipa il confine del recupero globale di una parte della tua latenza, così che un lancio avviato proprio sul segno superi comunque il recupero in tempo.",
    ["Fixed global cooldown padding (ms)"] = "Margine fisso del recupero globale (ms)",
    ["Show the judgement mark"] = "Mostra il segno del giudizio",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Una quarta linea dove Giudizio torna disponibile durante questo colpo, così da poter mettere un giudizio prima del twist invece che sopra di esso. Disegnata solo mentre un sigillo è attivo.",
    ["Show the global cooldown bar"] = "Mostra la barra del recupero globale",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Una striscia lungo il fondo della barra che arriva fino all'istante in cui il recupero globale si libera, così vedi quanta parte di questo colpo è già impegnata.",
    ["Global cooldown bar height"] = "Altezza della barra del recupero globale",
    ["When to show the bar"] = "Quando mostrare la barra",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "Sempre la tiene sullo schermo, ed è il modo più facile per allenare il tempismo su un manichino. Sigillo attivo la mostra ogni volta che stai portando un sigillo, dentro o fuori dal combattimento.",
    ["Seal active"] = "Sigillo attivo",
    ["In combat or seal active"] = "In combattimento o sigillo attivo",
    ["Only with Two-Handed Weapon Specialization"] = "Solo con Specializzazione in Armi a Due Mani",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Nasconde l'aiuto se non hai un punto nel talento. Il twist funziona anche senza, ma il colpo lento attorno a cui è costruito è ciò che rende utile tutta l'abitudine.",
    ["Neck"] = "Collo",
    ["Shoulder"] = "Spalle",
    ["Waist"] = "Vita",
    ["Legs"] = "Gambe",
    ["Wrist"] = "Polsi",
    ["Hands"] = "Mani",
    ["Finger 2"] = "Anello 2",
    ["Trinket 2"] = "Monile 2",
    ["Off Hand"] = "Mano Secondaria",
    ["Ranged"] = "A Distanza",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "Pratica – Un orologio dei colpi che gira da solo, con i tuoi tasti e un voto su ogni colpo",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "Prossima azione – Un'icona dell'unica cosa da premere, dove la vuoi tu",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "Latenza – Calibra il ritardo che un twist deve battere, con moltiplicatore e scostamento propri",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "Ombreggia la zona morta – La coda del colpo che un lancio non può più attraversare",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "Mostra la barra del recupero globale – Una striscia fino al momento in cui il recupero si libera",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "Quando mostrare la barra – Sempre, in combattimento, finché un sigillo è attivo, o entrambi",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "Colora la barra in base a – La zona in cui si trova il colpo, o il sigillo che porti",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "Stacca dalla barra – Le icone dei sigilli prendono una posizione propria, con la spazzata di recupero",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "Suggerisci Giudizio – Proposto solo se resta spazio per risigillare, e spento finché non lo chiedi",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "Texture, bordo, carattere, strato del riquadro, larghezza dei segni e i due valori dentro la barra sono a tua scelta, e ogni sigillo ha il suo colore.",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "Il twist si chiama twist in ogni lingua, la parola che i paladini usano davvero. In tedesco era Siegelwechsel; l'aiuto e la sua finestra prendono ora il nome dal twist.",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "L'avviso di un twist riuscito non tira più a indovinare. Prima scattava appena un sigillo partiva dentro la finestra, una previsione su cui il server può dissentire. Ora il registro di combattimento deve mostrare un colpo che va a segno con entrambi i sigilli attivi e, dietro, il danno proprio del sigillo mantenuto. Senza quello non suona nulla.",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "Disattivare il modulo lasciava indietro la barra delle borse, quella della latenza e i dodici pulsanti della Barra azioni 1 fino a un /reload. Ora tutte tre tornano da sole.",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "Le righe che occupano tutta la larghezza iniziano il loro controllo dove lo iniziano le vicine, invece che ognuna misuri la propria etichetta.",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "Osserva questa unità – Un gruppo può seguire il tuo bersaglio, il tuo focus o il tuo famiglio invece di te",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "Solo ciò che lancio io stesso – Un gruppo può pretendere che l'aura sia tua e non di chiunque",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "Ordine – Ordinare un gruppo per il tempo rimasto invece che per l'ordine in cui lo hai riempito",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "Le condizioni appartengono ora alla singola voce, non più solo al tipo di gruppo in cui si trova. Una voce può chiedere un numero di accumuli o gli ultimi secondi mentre le vicine non chiedono nulla.",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "Barre di lancio davanti alle altre targhette – Così il lancio che stai guardando non finisce dietro la targhetta accanto",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "Scurire i nemici fuori dal combattimento – Con una sua intensità, così un nemico inattivo si legge come inattivo a prima vista",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "Intensità dell’evidenziazione – Quanto la targhetta sotto il cursore si stacca dalla fila",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "L'area cliccabile viene ora misurata sulla targhetta invece di essere presunta, quindi le impostazioni di larghezza e altezza cadono dove il cursore si trova davvero.",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "Un menu a tendina con più voci di quante stiano sullo schermo ora scorre invece di uscire dal fondo, e un'etichetta diventata troppo lunga torna a stare nella sua riga.",
    -- Patch notes 1.43.0
    ["Compatibility"] = "Compatibilità",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "La finestra del personaggio restava vuota su client che non avevamo mai nominato. Il pannello chiedeva se il client si dichiarasse una di due versioni precise e rifiutava tutte le altre, comprese quelle che hanno esattamente le cornici di cui ha bisogno. Ora chiede l'unica cosa senza la quale non può funzionare. Incantamenti, castoni e statistiche degli oggetti mancavano per lo stesso motivo e tornano insieme a lui.",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "Valutazione di attacco, valutazione di celerità e valutazione di attacco magico compaiono anche sui client basati su Wrath. Erano legate per nome a una sola versione, benché lì il gioco abbia davvero quelle statistiche.",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "Le righe di statistiche che Wrath disegna a pagine con due menu a tendina ora restano nascoste sotto il nostro pannello, invece di trasparire attraverso di esso.",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – L'addon non si dichiara più obsoleto sul client cinese, la cui versione ora è elencata",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "Il riconoscimento della versione ripiega sul numero di build ogni volta che un client comunica un identificativo di cui non conosciamo il nome. Prima un client simile finiva con tutti i contrassegni di versione a falso, il che lo lasciava messo peggio di un client del tutto privo di identificativo, perché quello almeno ripiegava su qualcosa.",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "242 testi che nulla nell'interfaccia consulta più sono spariti da tutti e nove i file di lingua, circa l'otto per cento ciascuno. Li hanno lasciati indietro le impostazioni rinominate: tempo fa le barre delle azioni hanno ricevuto nomi più chiari e le vecchie voci sono semplicemente rimaste. Ora un controllo pone la domanda inversa dopo ogni modifica, se ogni testo tradotto sia ancora in uso, così non possono più accumularsi.",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "Pulsante di richiamo – Un quinto pulsante dei totem per le magie che evocano un intero set di totem salvato, visibile solo ai personaggi che ne conoscono una",
    ["Icon Strip"] = "Striscia di icone",
    ["Distance from frame"] = "Distanza dalla finestra",
    ["Spacing between icons"] = "Spaziatura tra le icone",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "La capacità razziale, il monile PvP e la fila DR stanno sullo stesso bordo della finestra e vengono disposti uno dopo l'altro, in quest'ordine, verso l'esterno.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "La posizione si imposta una sola volta per tutti e tre i tracciamenti in Disposizione, Striscia di icone.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Spazio sotto ogni finestra. La barra del famiglio dell'avversario sporge dal fondo della finestra, quindi con poco spazio invade quella successiva.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Arena: capacità razziale, monile PvP e fila DR condividono ora un'unica striscia di icone; il lato che avevi scelto è stato mantenuto.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Disposizione dell'arena non riuscita:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Errore nella striscia di icone dell'arena:|r %s",
    ["Drag to reorder. Right-click removes it."] = "Trascina per riordinare. Clic destro per rimuoverlo.",
    ["That icon is added automatically — switch off auto-tracking to remove it."] = "Quell’icona viene aggiunta automaticamente: disattiva il tracciamento automatico per rimuoverla.",
    ["Drag to reorder. Right-click an icon to remove it."] = "Trascina per riordinare. Clic destro su un’icona per rimuoverla.",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "Non c’è ancora nulla su questa barra. Aggiungi sotto una magia o un monile, oppure trascinane uno sulla barra.",
    ["+  New cooldown bar"] = "+  Nuova barra dei tempi di recupero",
    ["+  New buff / proc bar"] = "+  Nuova barra di benefici e proc",
    ["+  New target debuff bar"] = "+  Nuova barra di malefici sul bersaglio",
    ["+  New missing-buff reminder"] = "+  Nuovo promemoria dei benefici mancanti",
    ["Buffs & Procs"] = "Benefici e proc",
    ["Target debuffs"] = "Malefici sul bersaglio",
    ["Missing buffs"] = "Benefici mancanti",
    ["New name for this bar"] = "Nuovo nome per questa barra",
    ["Delete this bar and everything on it?"] = "Eliminare questa barra e tutto ciò che contiene?",
    ["That is the last bar — there has to be one."] = "Questa è l’ultima barra: una deve restare.",
    ["Drag to reorder bars"] = "Trascina per riordinare le barre",
    ["Rename this bar"] = "Rinomina questa barra",
    ["Delete this bar"] = "Elimina questa barra",
    ["Duplicate bar"] = "Duplica barra",
    ["Copies the selected bar with all entries and layout settings."] = "Copia la barra selezionata con tutte le voci e le impostazioni di disposizione.",
    ["Bar layout"] = "Disposizione della barra",
    ["Icon appearance"] = "Aspetto delle icone",
    ["Icon display"] = "Visualizzazione icone",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Barre dei cooldown spostabili e raggruppate come preferisci: proc, difensivi, offensivi, ognuna con aspetto e posizione propri.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "Quali ID devono essere mostrati nei tooltip? Alcuni tipi non esistono in questa versione del gioco e vengono ignorati (es. TraitNodeID, SourceID).",
    ["CDM Bars"] = "Barre CDM",
    ["Bug Fixes"] = "Correzioni di bug",
    ["Bar Glows"] = "Bagliori della barra",
    ["Click to edit this icon's glow."] = "Clicca per modificare il bagliore di questa icona.",
    ["Click an icon to edit its glow."] = "Clicca un'icona per modificarne il bagliore.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "Non c’è ancora nulla su questa barra. Aggiungi prima una magia o un monile nella scheda Barre CDM.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaOgni icona può brillare finché un tuo beneficio è attivo — o mancante. Clicca un’icona nell’anteprima qui sopra, poi aggiungi uno o più osservatori; il primo la cui condizione vale colora l’icona.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Nessuna icona scelta.|r",
    ["Glows: %s"] = "Bagliori: %s",
    ["Glow when"] = "Brilla quando",
    ["Buff is active"] = "Il beneficio è attivo",
    ["Buff is missing"] = "Il beneficio manca",
    ["Action button glow"] = "Bagliore da pulsante azione",
    ["Pulsing fill"] = "Riempimento pulsante",
    ["Gold (default)"] = "Oro (predefinito)",
    ["Pick color..."] = "Scegli colore...",
    ["Remove this glow"] = "Rimuovi questo bagliore",
    ["Watches: %s"] = "Osserva: %s",
    ["Add watcher (buff name / ID)"] = "Aggiungi osservatore (nome magia / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaNessun osservatore ancora. La maggior parte delle magie ti applica un beneficio con lo stesso nome — un clic qui sotto fa brillare questa icona finché quel beneficio è su di te. Oppure scrivi qualsiasi altro beneficio nel campo.|r",
    ["Glow while '%s' is on me"] = "Brilla finché '%s' è su di me",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "Striscia di icone – La capacità razziale, il monile e la fila DR condividono un bordo della finestra in ordine fisso, con un solo gruppo di controlli — non possono più finire uno sopra l'altro",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "La disposizione delle finestre d'arena — ordine, spaziatura, direzione di crescita — non è mai entrata in vigore: i suoi agganci venivano installati prima che l'interfaccia dell'arena fosse caricata. Le finestre segnalano ora i propri spostamenti e la disposizione li segue; in combattimento sono protette, e uno spostamento a metà round viene corretto alla fine.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "La spaziatura predefinita tra le finestre lascia spazio alla barra del famiglio dell'avversario, e il riquadro di trascinamento della modalità modifica copre l'intera pila invece di un'area fissa.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "Bagliori della barra – Qualsiasi icona può brillare finché un tuo beneficio è attivo o mancante: tre stili, oro, colore di classe o colore personalizzato, e un clic sorveglia il beneficio proprio della magia",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "La pagina è costruita attorno a un'anteprima che resta ferma mentre scorri: in alto il selettore delle barre con rinomina, elimina e trascina per riordinare, sotto ogni icona della barra nella sua dimensione e forma reali con la vera spirale di recupero. Trascinare riordina, il clic destro rimuove.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "La pagina è divisa in schede, e la barra delle risorse vi si è trasferita come una di esse. Le magie che aggiungi appartengono alla classe che le ha aggiunte e non compaiono più sugli altri tuoi personaggi.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "Il terzo alloggiamento degli oggetti extra non si allunga più per tutta la pagina con il campo scagliato al bordo.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "L'interfaccia non si paragona più da nessuna parte all'altra versione del gioco; un controllo tiene fuori per sempre formulazioni del genere.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "I moduli con più pagine le mostrano come una fila di schede lungo il bordo superiore; quando le schede superano la fila, due frecce la scorrono invece di andare a capo.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "La barra laterale si è accorciata: finestre di giocatore e bersaglio, barre dei caratteri, barra di lancio e impulso di recupero sono ora una sola voce, e una nuova voce Generale sotto Promemoria raccoglie le vecchie righe Extra, Personaggio e Correzioni di bug — le correzioni come un'unica scheda.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "Scrivere in un campo di aggiunta e premere il pulsante accanto non faceva nulla, in silenzio; il testo digitato contava solo dopo Invio. I pulsanti ora portano con sé il testo del campo.",
    ["Developer"] = "Sviluppatore",
    ["Suppress Lua Errors"] = "Nascondi gli errori Lua",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "Nasconde la finestra degli errori Lua del gioco (CVar scriptErrors). Gli errori continuano a verificarsi e gli addon che li raccolgono li vedono comunque - semplicemente non ti interrompono più.",
    ["Show IDs in Tooltips"] = "Mostra gli ID nei tooltip",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "Mostra ID di incantesimi, oggetti, PNG e altro nei tooltip. Quali tipi di ID appaiono si regola nella pagina ID nei tooltip del gruppo Extra.",
    ["Reset All Settings"] = "Ripristina tutte le impostazioni",
    ["Optimize My FPS and Graphics"] = "Ottimizza i miei FPS e la grafica",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "Applica un insieme collaudato di impostazioni grafiche che aumenta sensibilmente gli FPS mantenendo il gioco gradevole - ombre, liquidi, occlusione ambientale e distanza visiva scendono, texture ed effetti degli incantesimi restano nitidi. I valori attuali vengono prima salvati e il pulsante di ripristino li riporta. Vengono toccate solo impostazioni che questo client conosce.",
    ["Restore My Graphics Settings"] = "Ripristina le mie impostazioni grafiche",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "Riporta ogni impostazione grafica cambiata dal pulsante di ottimizzazione al valore precedente e rimuove il backup.",
    ["Graphics optimized: %d settings applied."] = "Grafica ottimizzata: %d impostazioni applicate.",
    ["Graphics settings restored."] = "Impostazioni grafiche ripristinate.",
    ["Fonts & Colors"] = "Caratteri e colori",
    ["Global Font"] = "Carattere globale",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Il carattere per l'intera interfaccia di VuloClassicUI. Compaiono anche i caratteri condivisi da altri addon.\n\n|cffaaaaaaRichiede /reload per applicarsi ovunque.|r",
    ["Outline Mode"] = "Modalità contorno",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Contorno predefinito per i testi di VuloClassicUI. Gli elementi con una propria impostazione di contorno la mantengono.\n\n|cffaaaaaaRichiede /reload per applicarsi ovunque.|r",
    ["Apply to All Game Texts"] = "Applica a tutti i testi di gioco",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "Sostituisce il carattere dei testi del gioco (chat, tooltip, registro missioni e altro) con il carattere globale.\n\n|cffaaaaaaDisattivandolo serve /reload per ripristinare i caratteri originali.|r",
    ["Class Colors"] = "Colori delle classi",
    ["Resource Colors"] = "Colori delle risorse",
    ["Font changed. /reload required to apply it everywhere."] = "Carattere cambiato. Serve /reload per applicarlo ovunque.",
    ["Reset to default"] = "Ripristina predefinito",
    ["Rename..."] = "Rinomina...",
    ["Rename loadout '%s'. Enter new name:"] = "Rinomina il loadout “%s”. Nuovo nome:",
    ["A loadout named '%s' already exists."] = "Esiste già un loadout chiamato “%s”.",
    ["Loadout '%s' renamed to '%s'."] = "Loadout “%s” rinominato in “%s”.",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "Il livello degli oggetti nei collegamenti all'equipaggiamento sta ora dopo il collegamento, non dentro le sue parentesi. Alcuni client ricontrollano il testo dei collegamenti con i propri dati, e il testo cambiato trasformava il collegamento nel nome della missione con quel numero.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "Una magia non compare più su un'altra classe solo perché quella classe possiede una magia diversa con lo stesso nome. Le voci rispettano il loro sigillo di classe sulle barre, e quelle vecchie vengono adottate per identificativo della magia invece che per nome.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "La libreria multimediale inclusa scartava in silenzio le registrazioni dei caratteri quando nessun altro addon portava una copia più recente; il carattere dell'addon si registra ora a ogni installazione.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "Rinomina... – Nel menu contestuale del set e nella pagina dei set; icona, contenuto e legame ai talenti traslocano con il nome",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "Ottimizza i miei FPS e la grafica – Un insieme collaudato di impostazioni grafiche con salvataggio unico; il pulsante di ripristino accanto riporta i tuoi valori precedenti",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "Caratteri e colori – Una nuova scheda: carattere globale con modalità contorno, a scelta per tutti i testi di gioco, più colori di classi e risorse con ripristino su ogni riga",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "Sviluppatore – Nascondere gli errori Lua, attivare gli ID nei tooltip e ripristinare tutte le impostazioni, in una nuova sezione della scheda Generale",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "La scheda Generale è organizzata in sezioni su una griglia a due colonne, come il resto della finestra. La nuova scheda porta un file di texture: riavvia il client una volta dopo l'aggiornamento, un /reload da solo non mostra le frecce di ripristino.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "L'ingrandimento resta spento sui client basati su Wrath (Titan Reforged): il loro registro missioni è già la finestra larga a due pannelli, e ingrandirlo spingeva il pannello dei dettagli sulla fila dei pulsanti.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "Gli elenchi a discesa lunghi si aprono verso l'alto quando sotto manca lo spazio. Prima uscivano dal bordo inferiore dello schermo, dove le ultime voci non si potevano mai raggiungere.",
    ["On"] = "Attivato",
    ["Select all"] = "Seleziona tutto",
    ["Deselect all"] = "Deseleziona tutto",
    ["Interface layout (window positions and links)"] = "Disposizione dell'interfaccia (posizioni e collegamenti delle finestre)",
    ["Fonts & colors (account-wide)"] = "Caratteri e colori (per tutto l'account)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "Porta con sé anche le impostazioni di carattere e colore valide per tutto l'account; si applicano subito all'importazione della stringa.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaL'esportazione includerà %d moduli su %d.|r",
    ["Nothing selected to export."] = "Niente di selezionato da esportare.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaTogli la spunta ai moduli per condividere solo una parte - una stringa parziale si fonde con il profilo attivo di chi importa.|r",
    ["Standard Action Bars"] = "Barre delle azioni standard",
    ["Modern"] = "Moderno",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaLe barre delle azioni del gioco restano al loro posto. Lo stile della cornice e la Modalità Scura qui sotto vengono dal modulo Dark Skin e vestono direttamente i pulsanti di Blizzard.|r",
    ["Apply layout to all bars"] = "Applica la disposizione a tutte le barre",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Copia la disposizione di questa barra - scala, dimensione delle icone, pulsanti per riga, spaziatura, direzione - su tutte le altre.",
    ["Layout applied to all bars."] = "Disposizione applicata a tutte le barre.",
    ["Text sizes"] = "Dimensioni del testo",
    ["Bar Display"] = "Visualizzazione barre",
    ["Menu, Bags & XP Bar"] = "Menu, borse e barra esperienza",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaAttivo solo in modalità Moderna (scheda Visualizzazione barre).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Clic: impostazioni di disposizione. Clic destro: dimensioni del testo.",
    ["Bar Animations"] = "Animazioni delle barre",
    ["Tint the pressed state"] = "Tinta lo stato premuto",
    ["Colours the flash a button shows while it is pressed down."] = "Colora il lampo che un pulsante mostra mentre è premuto.",
    ["Tint the hover highlight"] = "Tinta l'evidenziazione al passaggio",
    ["Colours the glow a button shows under the mouse."] = "Colora il bagliore che un pulsante mostra sotto il mouse.",
    ["Use class colour"] = "Usa il colore della classe",
    ["Enable bar background"] = "Attiva lo sfondo della barra",
    ["A flat colour panel behind the bar, sized with it."] = "Un pannello in tinta unita dietro la barra, dimensionato con essa.",
    ["Padding"] = "Margine",
    ["Flat (default)"] = "Tinta unita (predefinito)",
    ["Core"] = "Principale",
    ["Opacity"] = "Opacità",
    ["Durability"] = "Integrità",
    ["Talent points"] = "Punti talento",
    ["Pulse"] = "Pulsazione",
    ["Steady"] = "Costante",
    ["Background"] = "Sfondo",
    ["Low"] = "Basso",
    ["Medium"] = "Medio",
    ["High"] = "Alto",
    ["Dialog"] = "Dialogo",
    ["Click an icon to jump to its settings."] = "Clicca su un'icona per andare alla sua impostazione.",
    ["Middle-click: hide until the next loading screen."] = "Clic centrale: nascondi fino alla prossima schermata di caricamento.",
    ["Nothing to preview: every reminder is switched off."] = "Niente da mostrare: tutti i promemoria sono disattivati.",
    ["Show effects missing on others"] = "Mostra effetti mancanti agli altri",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Esamina il tuo gruppo o incursione alla ricerca dei benefici di classe che potresti lanciare e ti avvisa quando a qualcuno ne manca uno.",
    ["Missing on %s: %s"] = "Manca a %s: %s",
    ["In raids (minutes)"] = "In incursione (minuti)",
    ["In dungeons (minutes)"] = "In spedizione (minuti)",
    ["0 uses the global warn threshold."] = "0 usa la soglia di avviso globale.",
    ["Preferred food"] = "Cibo preferito",
    ["Preferred flask or elixir"] = "Ampolla o elisir preferiti",
    ["Preferred weapon enhancement"] = "Potenziamento dell'arma preferito",
    ["Automatic (best in bags)"] = "Automatico (il migliore nelle borse)",
    ["Click to use."] = "Clicca per usare.",
    ["Attach reminders to the cursor"] = "Aggancia i promemoria al cursore",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Mostra piccole copie dei promemoria attuali accanto al cursore del mouse.",
    ["Helpers"] = "Assistenti",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Conto alla rovescia della coda, assistente del minigioco dei potenziamenti e libro dell'addestratore in un unico posto.",
    ["Open group board"] = "Apri la bacheca dei gruppi",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Scansiona la chat alla ricerca di chi forma gruppi e li elenca per istanza Classic/TBC in una finestra (/vlfg o il pulsante qui sotto).",
    ["Show minimap button"] = "Mostra il pulsante sulla minimappa",
    ["PvP Settings"] = "Impostazioni PvP",
    ["Fullscreen"] = "Schermo intero",
    ["Fullscreen dialog"] = "Dialogo a schermo intero",
    ["Tooltip"] = "Tooltip",
    ["Orientation"] = "Orientamento",
    ["Horizontal"] = "Orizzontale",
    ["Vertical (up)"] = "Verticale (verso l'alto)",
    ["Vertical (down)"] = "Verticale (verso il basso)",
    ["Fill opacity"] = "Opacità del riempimento",
    ["Below 100 the world shows through the filled part of the bar."] = "Sotto 100 il mondo traspare attraverso la parte piena della barra.",
    ["The fill fades into a second colour towards its end."] = "Il riempimento sfuma in un secondo colore verso la sua estremità.",
    ["Name inside the bar"] = "Nome dentro la barra",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "Ancora il nome al bordo sinistro dentro la barra della salute invece che sopra — il bordo destro resta libero per il testo della salute.",
    ["Show plates for enemy pets"] = "Mostra le targhette dei famigli nemici",
    ["Divider line on the target's bar"] = "Linea divisoria sulla barra del bersaglio",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "Disegna una sottile linea verticale alla percentuale indicata della barra della salute — un segno di esecuzione.",
    ["Line position (%)"] = "Posizione della linea (%)",
    ["Only on your target"] = "Solo sul tuo bersaglio",
    ["Spell name"] = "Nome dell'incantesimo",
    ["Colour the last tick"] = "Colora l'ultimo tick",
    ["Show latency text"] = "Mostra il testo della latenza",
    ["Vertical"] = "Verticale",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "Automatico impila uno slot laterale in colonna e uno slot superiore o inferiore in riga.",
    ["Show older versions"] = "Mostra le versioni precedenti",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "%d valori numerici corrotti sono stati rimossi dalle impostazioni per poterle salvare di nuovo.",
    ["Widen window"] = "Allarga la finestra",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Larghezza extra per la finestra degli amici, così nomi lunghi, note e zone stanno su una riga. 0 mantiene la larghezza di Blizzard.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ mantiene il layout di Blizzard con degli extra. Modern aggiunge la cornice scura e sposta tutte le statistiche in un pannello a destra della finestra del personaggio.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Sostituisce l'interruttore di gruppo solo per questa voce - ad es. per tracciare un beneficio lanciato su di te da qualcun altro.",
    ["Group default"] = "Predefinito del gruppo",
    ["Anyone's"] = "Di chiunque",
    ["Use conditions"] = "Usa condizioni",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Deselezionata, questa voce viene parcheggiata: mantiene le impostazioni ma non appare mai. L'ingranaggio contiene spostamento, rimozione e impostazioni per voce.",
    ["Talent Window"] = "Finestra dei talenti",
    ["Shows all three talent trees side by side in one window."] = "Mostra tutti e tre gli alberi dei talenti affiancati in un'unica finestra.",
    ["Points left: %d"] = "Punti rimasti: %d",
    ["TALENTS"] = "TALENTI",
    ["Open Blizzard's talent window"] = "Apri la finestra dei talenti di Blizzard",
    ["For glyphs and everything this window does not cover."] = "Per i glifi e tutto ciò che questa finestra non copre.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaTutti e tre gli alberi dei talenti affiancati, con ranghi in tempo reale e apprendimento con un clic. I glifi restano nella finestra di Blizzard, a un pulsante di distanza.|r",
    ["Replace Blizzard's talent window"] = "Sostituisci la finestra dei talenti di Blizzard",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "Aprendo i talenti appare questa finestra. Disattivala per riavere la finestra di Blizzard a un solo albero.",
    ["Open talent window"] = "Apri la finestra dei talenti",
    ["See-through"] = "Trasparenza",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Nasconde il riempimento e le etichette dei riquadri durante la modifica, così vedi l'interfaccia che stai allineando. I bordi sottili restano.",
    -- Patch notes 1.46.0
    ["Options"] = "Opzioni",
    ["Talents"] = "Talenti",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "La pagina si apre con due modalità: Standard mantiene le barre di Blizzard con le righe di aspetto, Moderno usa le barre dell'addon con anteprima dal vivo, sfondo per barra, tinte di pressione e passaggio del mouse sui pulsanti e una texture per la barra esperienza",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Moderno – Terzo stile della barra di lancio del giocatore: aspetto piatto con nome e tempo sulla barra, più texture della barra, bordo, un ultimo tick colorato e un indicatore di latenza",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "La pagina delle opzioni ha un'anteprima dal vivo; un clic sulla sua icona o sulla barra porta alla sezione corrispondente",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "Le indicazioni di incantamento e gemme non si scacciano più a vicenda sui client non inglesi, e il testo cinese degli incantamenti non viene più tagliato a metà carattere",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "Le voci seguite stanno due per riga, ognuna con ingranaggio: parcheggiare una voce senza cancellarla, spostarla o rimuoverla, impostare condizioni e sostituire Solo ciò che lancio io stesso per quella voce sola",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Trasparenza – Nasconde il riempimento e le etichette dei riquadri durante la modifica, così vedi l'interfaccia che stai allineando",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "Durante il trascinamento le coordinate appaiono sul riquadro, e la finestra a cui ci si aggancia pulsa in bianco",
    ["The loot window can be moved on Wrath clients"] = "La finestra del bottino può essere spostata sui client Wrath",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Allarga la finestra – Larghezza extra perché nomi lunghi, note e zone stiano su una riga",
    ["The close glyph of every window is larger now"] = "Il segno di chiusura di tutte le finestre ora è più grande",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Tre schede con anteprima fissata, un'opzione nome nella barra e separatori delle migliaia sui numeri di salute",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "Le righe con ingranaggio si aprono nella propria colonna, le righe delle aure si allineano per riga, gli strumenti ausiliari condividono una scheda, e l'intestazione fissata dell'ultima scheda visitata viene rimossa al cambio",
    ["Only the last five versions build at once; a button loads the older ones"] = "Vengono costruite solo le ultime cinque versioni alla volta; un pulsante carica le più vecchie",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Orientamento, opacità del riempimento, livello della cornice e un'anteprima nella pagina delle opzioni",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Una stringa di profilo può portare una selezione: moduli scelti, la disposizione delle finestre, le sostituzioni dei talenti e i caratteri e colori dell'account",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Interruttori per regola con nomi nei colori di classe, una scansione del gruppo per i benefici mancanti, cibo, boccetta e olio per armi preferiti, soglie per incursione e spedizione, stili di bagliore, scala e un'anteprima; il clic centrale nasconde un promemoria fino alla prossima schermata di caricamento",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "I valori numerici danneggiati vengono rimossi prima del salvataggio e segnalati al prossimo accesso. Un solo valore del genere riportava tutte le impostazioni dell'account ai valori predefiniti",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "Il richiamo dei totem ha un proprio pulsante dopo gli elementi sui client Wrath",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Finestra dei talenti – I tre alberi dei talenti affiancati con gradi dal vivo e apprendimento al clic sui client Wrath; i glifi restano a un pulsante",
    ["The string is selected - press Ctrl+C to copy it."] = "La stringa è selezionata: premi Ctrl+C per copiarla.",
    ["%d characters"] = "%d caratteri",
    ["Paste the string here with Ctrl+V."] = "Incolla qui la stringa con Ctrl+V.",
    ["String captured - %d characters."] = "Stringa acquisita: %d caratteri.",
    ["Partial string: anything missing is taken from your active profile."] = "Stringa parziale: ciò che manca viene preso dal profilo attivo.",
    ["Unticked parts keep your current settings."] = "Le parti deselezionate mantengono le impostazioni attuali.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Profilo '%s' importato. Passare subito a esso e ricaricare l'interfaccia?",
    ["Switch and reload"] = "Cambia e ricarica",
    ["Save a backup copy"] = "Crea una copia di backup",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Crea una copia datata del profilo attivo come punto di ripristino. Non cambia nulla: la copia resta semplicemente nell'elenco dei profili.",
    ["Backup '%s' created."] = "Copia di backup '%s' creata.",
    ["Go back"] = "Indietro",
    ["Pixel-true plate size"] = "Dimensione targhette al pixel",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Dimensiona le targhette in pixel dello schermo invece che in unità dell'interfaccia: un'altezza di 27 corrisponde sempre a 27 pixel, su ogni monitor e scala.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "I riquadri ora coprono esattamente la loro finestra, nello stesso stile scuro del resto dell'interfaccia, con il nome centrato e in arancione quando la finestra è agganciata a un'altra",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Fuori dall'editor resta la piccola maniglia, così una barra dei tempi di recupero sbloccata continua ad accettare le magie trascinate e le anteprime di prova restano visibili",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "Lo slot dell'equipaggiamento del mantello era tradotto in sei lingue con la parola di navigazione indietro e ora è corretto ovunque",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Dimensione targhette al pixel – Dimensiona le targhette in pixel dello schermo: un'altezza di 27 corrisponde a 27 pixel su qualsiasi monitor e scala dell'interfaccia",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Le dimensioni delle targhette ora significano esattamente ciò che dicono i cursori: il gioco non ingrandisce più di nascosto la targhetta del bersaglio né rimpicciolisce quelle lontane, e l'anteprima corrisponde al gioco — ingrandire il bersaglio è ora compito esclusivo dell'opzione di scala della targhetta del bersaglio",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Crea una copia di backup – Un clic conserva una copia datata del profilo attivo come punto di ripristino",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "L'esportazione apre una vera finestra con la stringa già selezionata, e l'importazione mostra prima un'anteprima: rinomina il profilo e togli la spunta a ciò che non vuoi prima che venga scritto qualcosa",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "Le stringhe di esportazione sono compresse a una frazione della vecchia lunghezza ed entrano in un messaggio di chat; le stringhe delle versioni precedenti si importano ancora",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "Sul client Wrath il tooltip dei talenti mostrava un segnaposto invece della descrizione, e il tasto dei talenti apriva la finestra ma non la chiudeva — entrambi corretti",
    ["%s Locked"] = "%s bloccata",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffPERDITA DI CONTROLLO|r\n|cffaaaaaaTrascina o frecce|r",
    ["%.1f seconds"] = "%.1f secondi",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Spostamento della perdita di controllo attivo. |cff9b6cffTrascina il riquadro viola|r oppure usa le |cff9b6cfffrecce|r (MAIUSC = 5 px). Premi di nuovo il pulsante per terminare.",
    ["Preview"] = "Anteprima",
    ["Loss of Control"] = "Perdita di controllo",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Mostra ciò che ti sta controllando in questo momento – stordimento, paura, radicamento, silenzio, disarmo o una scuola bloccata – con l’icona dell’effetto, il suo nome e il tempo rimanente. Se due effetti sono attivi insieme, quello più importante viene mostrato grande e il successivo come piccola icona accanto.",
    ["Show loss of control alert"] = "Mostra l’avviso di perdita di controllo",
    ["Show in"] = "Mostra in",
    ["Arena and battlegrounds"] = "Arene e campi di battaglia",
    ["Arena only"] = "Solo arene",
    ["Name font size"] = "Dimensione del carattere del nome",
    ["Timer font size"] = "Dimensione del carattere del tempo",
    ["Background and red lines"] = "Sfondo e linee rosse",
    ["Show the next effect"] = "Mostra l’effetto successivo",
    ["Profile changed. Use /reload when you are out of combat."] = "Profilo cambiato. Usa /reload quando sei fuori dal combattimento.",
    ["Profile keybind"] = "Scorciatoia del profilo",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Passa a questo profilo fuori dal combattimento e poi chiede di ricaricare l’interfaccia. Le scorciatoie vengono ripristinate all’accesso.",
    ["Use the global font"] = "Usa il carattere globale",
    ["Name color"] = "Colore del nome",
    ["Timer color"] = "Colore del tempo",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffINTERRUZIONI|r\n|cffaaaaaaTrascina o frecce|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Spostamento della barra delle interruzioni attivo. |cff9b6cffTrascina il riquadro viola|r oppure usa le |cff9b6cfffrecce|r (MAIUSC = 5 px). Premi di nuovo il pulsante per terminare.",
    ["Interrupts"] = "Interruzioni",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Controlla il registro di combattimento per le interruzioni nemiche e avvia un tempo di recupero per ciascuna, distinto per incantatore: due nemici della stessa classe ricevono un’icona ciascuno. Il bordo porta il colore di classe dell’incantatore.",
    ["Show interrupt bar"] = "Mostra la barra delle interruzioni",
    ["Show interrupts that are still ready"] = "Mostra anche le interruzioni disponibili",
    ["Timer text on the icons"] = "Testo del tempo sulle icone",
    ["Cooldown swipe on the icons"] = "Sweep del recupero sulle icone",
    ["Only take over the key while a fishing pole is worn"] = "Occupa il tasto solo con una canna equipaggiata",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Senza canna in mano il tasto mantiene ciò che gli hai assegnato, quindi resta utilizzabile fuori dalla pesca. Un lancio già in acqua mantiene il tasto. Questo disattiva l’equipaggiamento automatico della canna, che ha bisogno del tasto proprio quando non ne indossi nessuna.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Segnaposto di un riquadro nemico: la striscia laterale è posizionata dalle impostazioni qui sotto.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Finestra delle opzioni",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Perdita di controllo – Mostra lo stordimento, la paura, il radicamento, il silenzio o il blocco che ti trattiene, con icona, nome e tempo rimanente",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Interruzioni – Segue le interruzioni nemiche nel registro di combattimento, un’icona per incantatore, bordata del colore della sua classe",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Testo del tempo sulle icone – Secondi rimanenti sulle icone di interruzione, con carattere, contorno e colore propri",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Sweep del recupero sulle icone – Toglie l’ombra che ruota e lascia solo il numero",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "La striscia di icone accanto ai riquadri nemici ha un’anteprima dal vivo nella scheda Generale. Quei riquadri esistono solo dentro un’arena, quindi i suoi cursori spostavano qualcosa che non si poteva vedere.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Un riquadro di spostamento sbloccato non sparisce più un istante dopo che il pulsante lo ha mostrato. Il riquadro e un’anteprima in corso ignorano ora il filtro di zona: una barra si posiziona dove ci si trova, e raramente è un’arena.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "La striscia di icone fissata compare ora anche nella scheda Layout, dove dimensione, spaziatura, forma e zoom si leggono su di essa mentre il cursore si muove.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Spostare i riquadri di Blizzard non contrassegna più ogni finestra della modalità di modifica come toccata da questo componente, cosa che faceva rifiutare la comparsa del riquadro del famiglio in combattimento. La causa era la selezione di un layout, e avveniva a ogni ingresso nell’editor anche se non era mai stato posizionato nulla.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "Il selettore di icone ha un pulsante di chiusura e non resta più sospeso sopra il gioco dopo la chiusura della scheda del personaggio.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Occupa il tasto solo con una canna equipaggiata – Senza canna il tasto mantiene ciò che gli hai assegnato",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "La rotellina scorre la barra laterale e la pagina. La finestra si rimpicciolisce inoltre per stare in uno schermo più piccolo di lei, che è esattamente ciò che la rendeva impossibile da spostare con una scala dell’interfaccia alta.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Scorciatoia del profilo – Assegna un profilo a un tasto e passaci fuori dal combattimento",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "La scansione delle borse dietro i promemoria di cibo, fiala e olio per armi viene conservata finché le borse non cambiano, invece di percorrere tutte le borse tre volte due volte al secondo.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "Lo stile moderno del riquadro del giocatore non tocca più i riquadri del famiglio e dei totem.",
    ["Fine tuning for this slot"] = "Regolazione fine di questa posizione",
    ["Slot settings"] = "Impostazioni della posizione",
    ["Border settings"] = "Impostazioni del bordo",
    ["Border size"] = "Spessore del bordo",
    ["How solid the empty part of the bar is."] = "Quanto è piena la parte vuota della barra.",
    ["Absorb settings"] = "Impostazioni dell'assorbimento",
    ["Border around the cast bar"] = "Bordo attorno alla barra di lancio",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Disattivato lascia la barra di lancio senza un contorno proprio; la barra della vita mantiene il suo.",
    ["Top text"] = "Testo in alto",
    ["Left text"] = "Testo a sinistra",
    ["Right text"] = "Testo a destra",
    ["Centred text"] = "Testo centrato",
    ["Unit name"] = "Nome dell'unità",
    ["Main text positions"] = "Posizioni principali del testo",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaUna cosa per posizione. Il livello sta al bordo sinistro del nome e lo segue.|r",
    ["Health and cast bar"] = "Barra della vita e di lancio",
    ["Health bar width"] = "Larghezza della barra della vita",
    ["Health bar height"] = "Altezza della barra della vita",
    ["Cast icon"] = "Icona di lancio",
    ["Cast icon settings"] = "Impostazioni dell’icona di lancio",
    ["Cast background"] = "Sfondo di lancio",
    ["Cast bar border"] = "Bordo della barra di lancio",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Spessore del bordo proprio della barra di lancio. 0 lo rimuove; la barra della vita mantiene il suo.",
    ["Cast bar border colour"] = "Colore del bordo della barra di lancio",
    ["Cast timer"] = "Timer di lancio",
    ["Cast timer settings"] = "Impostazioni del timer",
    ["Cast bar Y offset"] = "Scostamento Y della barra di lancio",
    ["Cast colours and effects"] = "Colori ed effetti di lancio",
    ["The bar's colour while a spell is being cast."] = "Il colore della barra mentre viene lanciata una magia.",
    ["More cast colours"] = "Altri colori di lancio",
    ["Interrupt ready"] = "Interruzione pronta",
    ["Interrupt flash"] = "Lampo di interruzione",
    ["Interrupt-ready hint"] = "Suggerimento: interruzione pronta",
    ["Show cast bars in front of nameplates"] = "Mostra le barre di lancio davanti alle targhette",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "I lanci vengono disegnati sopra ogni targhetta, così un lancio importante non finisce mai dietro la barra di un’altra unità.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "La barra di lancio del nemico lampeggia e mostra per un attimo «Interrotto» quando la sua magia viene fermata.",
    ["Interrupt flash settings"] = "Impostazioni del lampo di interruzione",
    ["Target, focus and hover effects"] = "Effetti di bersaglio, focus e passaggio del mouse",
    ["Target effect"] = "Effetto bersaglio",
    ["A coloured edge around the plate you have targeted."] = "Un bordo colorato attorno alla targhetta che hai come bersaglio.",
    ["Target effect settings"] = "Impostazioni dell’effetto bersaglio",
    ["Target arrows"] = "Frecce del bersaglio",
    ["Arrow settings"] = "Impostazioni delle frecce",
    ["Target bar colour on"] = "Attiva il colore del bersaglio",
    ["Focus bar colour on"] = "Attiva il colore del focus",
    ["A coloured edge around the plate you have set as your focus."] = "Un bordo colorato attorno alla targhetta impostata come focus.",
    ["Mouseover effect"] = "Effetto al passaggio del mouse",
    ["Mouseover effect settings"] = "Impostazioni dell’effetto del mouse",
    ["General text"] = "Testo generale",
    ["Debuff duration"] = "Durata dei malefici",
    ["Buff duration"] = "Durata dei benefici",
    ["Crowd control duration"] = "Durata del controllo",
    ["Aura stacks"] = "Cariche delle aure",
    ["Timer text colour"] = "Colore del timer",
    ["Stack text colour"] = "Colore delle cariche",
    ["Text settings"] = "Impostazioni del testo",
    ["Spell target"] = "Bersaglio della magia",
    ["Background settings"] = "Impostazioni dello sfondo",
    ["Hide the gryphons"] = "Nascondi i grifoni",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Rimuove le due bestie alle estremità della barra delle azioni originale. La barra resta.",
    ["Extra indicators"] = "Indicatori aggiuntivi",
    ["Enemy colours"] = "Colori dei nemici",
    ["Enemy types"] = "Tipi di nemico",
    ["The health bar colour a unit takes from its reaction to you."] = "Il colore che la barra assume dall’atteggiamento dell’unità verso di te.",
    ["Neutral enemies"] = "Nemici neutrali",
    ["Units that are not hostile until you make them so."] = "Unità che diventano ostili solo se le provochi.",
    ["Other nameplates"] = "Altre targhette",
    ["Nameplate spacing"] = "Spaziatura delle targhette",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaImpostazioni del gioco stesso, applicate subito e fuori dal profilo — tranne l’area cliccabile. Non modificabili in combattimento.|r",
    ["Stackable nameplates"] = "Targhette impilabili",
    ["Extra aura options"] = "Opzioni aggiuntive delle aure",
    ["Target and focus effects"] = "Effetti di bersaglio e focus",
    ["Plate scale while casting"] = "Dimensione della targhetta durante il lancio",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "La targhetta di un’unità che lancia cresce fino a questa dimensione, così quella che conta risalta. 100 = disattivato.",
    ["Opacity while casting"] = "Opacità durante il lancio",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "La targhetta di un’unità che lancia resta almeno così opaca, anche se hai un altro bersaglio.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "Il nome dell’unità lascia il posto al nome della magia per tutta la durata del lancio.",
    ["Active talent group"] = "Gruppo talenti attivo",
    ["Left-click: show this talent group"] = "Clic sinistro: mostra questo gruppo talenti",
    ["Right-click: activate this talent group"] = "Clic destro: attiva questo gruppo talenti",
    ["Talent group %d (not active)"] = "Gruppo talenti %d (non attivo)",
    ["Talents can only be learned in the active talent group."] = "I talenti possono essere appresi solo nel gruppo talenti attivo.",
    ["Talent groups cannot be switched in combat."] = "Non è possibile cambiare gruppo talenti in combattimento.",
    ["This client refused to switch the talent group."] = "Questo client ha rifiutato il cambio di gruppo talenti.",
    ["Input line above the chat"] = "Riga di scrittura sopra la chat",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Mette la riga di scrittura sopra l’area dei messaggi invece che sotto. Il pannello e la barra delle schede la seguono.",
    ["Own background for the input line"] = "Sfondo proprio per la riga di scrittura",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Disegna la riga di scrittura su uno sfondo scuro proprio invece che su quello di Blizzard. Il pannello di sfondo scuro copre già la riga di scrittura, quindi questo si vede quando quel pannello è disattivato.",
    ["Addon buttons"] = "Pulsanti degli addon",
    ["Click to show or hide the collected buttons."] = "Clicca per mostrare o nascondere i pulsanti raccolti.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Dove stanno i pulsanti della minimappa degli altri addon: attorno alla mappa, nascosti finché il mouse non ci passa sopra, o raccolti in una scatola sotto.",
    ["Around the minimap"] = "Attorno alla minimappa",
    ["Only on mouseover"] = "Solo al passaggio del mouse",
    ["Collected in a box"] = "Raccolti in una scatola",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Nascondi i grifoni – Toglie le due bestie alle estremità della barra principale di Blizzard senza smorzare nient’altro",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Disattivare il modulo ora lo disattiva davvero. I suoi gestori vengono registrati al caricamento, quindi un modulo già spento all’accesso non eseguiva mai il proprio spegnimento: essere storditi in un campo di battaglia faceva comunque comparire l’avviso di perdita di controllo, e la barra delle interruzioni si riempiva senza svuotarsi più, perché il ticker che ripulisce le sue icone parte solo all’accensione.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "La barra delle interruzioni non legge più il registro di combattimento del mondo intero. Si registrava al caricamento e non si annullava mai, così ogni riga di combattimento ovunque — diverse migliaia al secondo in incursione — veniva smontata per una barra il cui valore predefinito è arena e campi di battaglia soltanto. Ora usa lo stesso filtro di zona dell’avviso che le sta accanto.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Attivare il modulo dentro un’arena vale come arrivare. La decisione sulla zona viveva solo nella schermata di caricamento, quindi chi lo attivava già dentro non aveva alcun ticker per la riduzione fino all’arena successiva.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "Il cursore della dimensione del testo del livello oggetto funziona di nuovo. Cercava i numeri in due punti in cui sperava di trovarli, e dove un client aggancia i propri pulsanti dell’equipaggiamento altrove non ne trovava nessuno e non faceva nulla in silenzio — cosa che da fuori non si distingue da un testo semplicemente troppo piccolo.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Riga di scrittura sopra la chat – Mette la riga di scrittura sopra l’area dei messaggi invece che sotto, il pannello e la barra delle schede la seguono; solo sul client Wrath",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Sfondo proprio per la riga di scrittura – Disegna la riga di scrittura su uno sfondo scuro proprio invece che su quello di Blizzard, quello che vedevi una volta spento il pannello scuro; solo sul client Wrath",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "Lo zoom delle icone ora si chiama ritaglio delle icone e si legge in percentuale. È la stessa domanda che pongono i cursori delle targhette, e rispondeva in centesimi mentre quelli rispondevano in percentuale.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "La larghezza aggiuntiva appartiene ora alla sola scheda degli amici. I testi delle righe lì si allungano con la finestra, ma le intestazioni di colonna delle schede ricerca, gilda e incursione stanno a distanze fisse e non si muovono, quindi ogni punto di larghezza aggiunto finiva in una metà destra vuota. Quelle tre schede tornano alle proporzioni di Blizzard, quelle per cui le loro colonne sono state misurate.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "L’elenco dei set e il selettore di icone prendono lo stile della finestra del personaggio. Nello stile classico erano una superficie scura e piatta con bordo viola che conteneva i pulsanti rossi di Blizzard — due materiali in un palmo. Ora portano lì la cornice di dialogo di Blizzard e stanno nello stesso materiale della finestra a cui sono agganciati, mentre lo stile moderno mantiene l’aspetto piatto.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "La finestra del personaggio non si rompe più quando la barra laterale costruisce la sua prima riga di set. La barra di marcatura della riga cercava ancora un colore d’accento che era stato rimosso, quindi l’elenco restava vuoto e la finestra si apriva spoglia.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Pulsanti degli addon – Scegli dove stanno i pulsanti degli altri addon: attorno alla mappa, nascosti finché il mouse non ci passa sopra, o raccolti in una scatola sotto; solo sul client Wrath",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Ritaglio delle icone (%) – Quanto viene tolto del bordo che il gioco incorpora nelle sue icone, regolabile per riga di aure e per l’icona della barra di lancio",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "Lo stile a barra arrotondata non lascia più spazio morto alle due estremità. La forma tonda non riempie la propria immagine — un bordo trasparente le corre tutto attorno —, e allungare quel bordo su una barra larga e bassa lasciava circa undici punti di barra vuota a ogni estremità e appena uno sopra e sotto, ecco perché si notava in orizzontale e non in verticale.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "La pagina delle opzioni è tagliata per domande invece che per meccanica. Sedici sezioni avevano impostazioni affini lontane tra loro, con la trama della barra sotto un titolo e quella della barra di lancio sotto un altro; otto impostazioni erano raggiungibili da due sezioni insieme.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Ogni testo sulla targhetta occupa ora una posizione, come già facevano le righe delle aure: in alto, a sinistra, a destra o centrato, riempito con il nome dell’unità o il testo della vita. Quattro interruttori sono diventati selettori di posizione, ciascuno partendo dal posto che il suo testo già aveva.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "Il menu a tendina dell’impilamento non mostrava alcun valore leggibile. Leggeva un’impostazione che questo client non ha; quella che ha viene ora letta e scritta, misurata nel gioco in esecuzione.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Un ingranaggio su una riga a mezza larghezza apre una piccola finestra fluttuante invece di aprirsi dentro la cella. Mezza cella non ha spazio per un cursore, e sei di essi erano stati compressi in monconi.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "I campioni di colore, gli occhi, gli ingranaggi e le frecce stanno subito accanto al controllo a cui appartengono invece che nella striscia di icone a destra, che resta riservata all’ingranaggio e al punto informativo.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "Sul client Wrath il modulo si ritira del tutto e il client mantiene la propria finestra. Il nostro restyling si rivolge agli elementi di Blizzard per nome e per numero di regione, e dietro quei nomi quel client ha un’altra anatomia: buchi neri dove stavano le regioni nascoste, una barra del titolo allungata, menu a tendina sopra l’elenco delle ricette — e nessun errore, perché non solleva nulla, semplicemente atterra sugli elementi sbagliati.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Lungo il bordo destro corrono pulsanti per i gruppi talenti, uno per ogni gruppo acquistato. Il clic sinistro mostra un gruppo, il destro lo attiva, la stessa divisione che usa la finestra di Blizzard. I talenti si possono apprendere solo nel gruppo attivo, quindi un clic nell’anteprima non fa nulla e il suggerimento lo dice prima.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "La scheda porta un libro invece di un punto interrogativo. Quel segno è il segnaposto di Blizzard per un’icona mancante e si leggeva come un difetto.",
    ["Glyphs"] = "Glifi",
    ["CHARACTER"] = "Personaggio",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Impacchetta il set di barre selezionato in una stringa da passare ad altri. Slot, macro e scorciatoie viaggiano con essa.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Legge una stringa di set di barre nella tua libreria. Applicarla alle barre resta un passo a parte.",
    ["The bar setup string is damaged."] = "La stringa del set di barre è danneggiata.",
    ["This is not a bar setup string."] = "Questa non è una stringa di set di barre.",
    ["Bar setup '%s' imported."] = "Set di barre '%s' importato.",
    ["Macros left alone: the switch above is off."] = "Macro non toccate: l’interruttore qui sopra è spento.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Macro: %d ripristinate, |cffff8800%d fallite|r: la lista delle macro potrebbe essere piena.",
    ["Macros: %d restored."] = "Macro: %d ripristinate.",
    ["Key bindings left alone: the switch above is off."] = "Scorciatoie non toccate: l’interruttore qui sopra è spento.",
    ["Key bindings: %d applied."] = "Scorciatoie da tastiera: %d applicate.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Set di barre '%s' salvato: %d slot, %d macro, %d scorciatoie da tastiera.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800Nessuna scorciatoia da tastiera è stata acquisita.|r Questo client potrebbe non segnalarle.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Esporta come stringa – Impacchetta il set selezionato in una stringa da passare ad altri, con i suoi slot, le macro e le scorciatoie",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Importa da stringa – Legge il set di qualcun altro nella tua libreria; un nome che usi già riceve un numero invece di essere sovrascritto",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Un set importato viene ricostruito voce per voce prima di essere riposto. Il ripristino attraversa ogni voce, quindi una malformata avrebbe generato un errore a metà corsa, con parte delle tue barre già cambiate. Le voci rotte vengono scartate, il resto arriva lo stesso.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "Salvataggio e caricamento dicono che cosa hanno fatto. Entrambi contavano il proprio lavoro da sempre e ne buttavano via i numeri: un set le cui macro fallivano tutte sembrava uno senza macro, e un salvataggio che non acquisiva scorciatoie non diceva nulla.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "La finestra del personaggio si può posizionare a mano sul client Wrath. L’editor di Blizzard non possiede quella finestra, quindi prende la stessa via diretta già usata dalla finestra del bottino; una scatola muove insieme le schede personaggio, reputazione e abilità, e il pannello delle statistiche e l’elenco dei set viaggiano con essa.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "La finestra parte larga sul client Wrath. Il cursore è sempre arrivato a 400: partiva semplicemente da nulla, quindi lo spazio in più raggiungeva solo chi andava a cercarlo.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "La pagina dei glifi si apre da un pulsante sotto i pulsanti dei gruppi talenti, ed è scura adesso. Il cerchio runico viene attenuato invece che rimosso, perché è ciò che rende riconoscibile quella pagina; gli incastoni prendono il colore d’accento, e la grafica del glifo e l’evidenziazione di presa restano come sono.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "Il pulsante del gruppo talenti mostra l’icona del suo albero invece di un punto interrogativo. La chiedeva attraverso un’interfaccia che non risponde su ogni client e ripiegava sul segnaposto; ora la risposta viene ricavata dai ranghi stessi, che non possono essere letti male.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "Il numero del livello sulla finestra del giocatore sta dove lo mette il client, sul client Wrath. I nostri due ancoraggi sono misurati su un foglio di cornice, e dove ne viene distribuito un altro il numero finiva accanto al ritratto: lì il client mantiene quell’ancoraggio da sé e lo sposta a seconda delle icone di riposo e PvP.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "Barra dei castoni sotto la finestra",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "Mette sotto la finestra del personaggio una barra con ogni castone del tuo equipaggiamento. Clicca su un castone per incastonarvi una gemma dalle tue borse. Resta vuota sui client il cui gioco non ha gemme.",
    ["Choose a gem"] = "Scegli una gemma",
    ["No gems in your bags."] = "Nessuna gemma nelle tue borse.",
    ["Empty socket"] = "Castone vuoto",
    ["Click to pick a gem from your bags."] = "Clicca per scegliere una gemma dalle tue borse.",
    ["Cannot socket gems in combat."] = "Non è possibile incastonare gemme in combattimento.",
    ["Close the socketing window first."] = "Chiudi prima la finestra di incastonatura.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Barra dei castoni sotto la finestra – Una fila con ogni castone del tuo equipaggiamento, sotto la finestra del personaggio; clicca su un castone per incastonarvi una gemma dalle tue borse",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "Il testo dell'incantamento sulle caselle dell'armatura mostra di nuovo l'incantamento invece del marchio di difficoltà dell'oggetto. Il filtro prendeva la prima riga verde della descrizione, e dove un oggetto porta quel marchio esso sta sopra l'incantamento — così ogni casella mostrava il marchio, mentre un'arma due righe più in basso mostrava correttamente il suo perché davanti non c'era nulla. Il marchio e i suggerimenti tra parentesi angolari del client vengono ora riconosciuti entrambi, e in ogni lingua invece che solo in inglese e tedesco.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "L'elenco dei set non proietta più un'ombra oltre la propria cornice. Quello che sembrava uno sfondo che sporgeva dal bordo era un'ombra: non un contorno, ma quattro rettangoli pieni che arrivavano fino a sette pixel oltre la cornice su ogni lato, e dietro la cornice di dialogo di Blizzard non c'era nulla su cui cadere. È sparita in entrambi gli stili.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "Nello stile Classic+ lo sfondo scuro finiva prima della linea decorata invece che su di essa, e sporgeva quindi dalla cornice su ogni lato.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "Applica questa disposizione",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "Mette il nome dell'unità e il valore di salute dentro la barra, il controllo a sinistra, le penalità in arrivo sopra di esso e i potenziamenti alla sua destra, e dà alla barra di lancio la sua icona, il tempo rimanente e il suo bersaglio. La tua disposizione attuale viene salvata prima e il pulsante accanto la riporta indietro.",
    ["Restore my arrangement"] = "Ripristina la mia disposizione",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "Riporta ogni posizione di testo e aura a com'era prima che la disposizione venisse applicata, e rimuove la copia salvata. Anche tutto ciò che hai spostato a mano da allora torna indietro.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "Disposizione delle targhette applicata. Il pulsante accanto riporta quella precedente.",
    ["Nameplate layout restored."] = "Disposizione delle targhette ripristinata.",
    ["Shows"] = "Mostra",
    ["Current health"] = "Salute attuale",
    ["Current and maximum"] = "Attuale e massima",
    ["Current and percent"] = "Attuale e percentuale",
    ["Separator"] = "Separatore",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "Ciò che sta fra i due numeri, quando la riga sopra è impostata su attuale e percentuale.",
    ["Brackets"] = "Parentesi",
    ["Vertical bar"] = "Barra verticale",
    ["Dash"] = "Trattino",
    ["Space"] = "Spazio",
} end)
